// ============================================================================
// V2 Animation VM — independent reimplementation of sub_14207/sub_1424c
//
// The original VM (sub_1424c) is a bytecode interpreter that processes
// animation scripts for dynamic objects (intro screens, cutscenes, etc.).
// It dispatches opcodes via the off_30CAC table (216 opcodes, 0x00-0xD7).
//
// This v2 version reads the SAME bytecode and game data from DS segment,
// but renders to v2_render_buf instead of drawBuffer.
//
// The original VM continues to run for the first window.
// This VM runs in parallel for the second window.
// ============================================================================

#include <cstdint>
#include <cstring>
#include <cstdio>
#include <cstdlib>
#include <map>
#include <set>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#ifndef _WIN32
#include <unistd.h>   // _exit, close, syscall — some libcs pull these in
                      // transitively, Ubuntu's does not.
#endif
#include <algorithm>
#include <SDL2/SDL.h>
#include "render_v2.h"
#include "v2_ds_layout.h"
#include "v2_obj_view.h"

// Access to emulated memory
extern uint8_t* v2_m2c_base;

// SDL spec-key state (defined in sdl/render.cpp). Game logic ORs this in
// at byte_31xxx CMP/TEST sites to mirror what orig int 9 ISR would have set.
extern uint8_t sdl_spec_get(uint16_t off);
extern uint8_t sdl_spec_state_get(uint16_t off);

// SDL/adlmidi sound API (defined in sdl/play.cpp).
// In default mode the orig also calls these; in V2_ONLY only v2 calls them.
// v2 uses methods on independent v2_pool instance (defined in play.cpp). Same
// class as orig_pool — only the instance differs. v2_pool is globally_muted in
// default mode (no audio output) but slot tracking continues for DS verify.
#include "play.h"

// ============================================================================
// SFX AUDIT INFRASTRUCTURE
// ============================================================================
// Detects divergences between orig (sub_177bb in seg000) and v2 (v2_vm_op_sound)
// in SFX playback. In default mode both process same VM bytecode and SHOULD
// fire the same op_sound calls. Discrepancies indicate v2 is missing code paths.
//
// Three layers (all active simultaneously):
//   L1: per-frame count comparison (cheap, catches frame-level mismatches)
//   L2: per-event matching by (seq, obj) within timing window (±3 frames)
//   L3: at-exit unique-seq set comparison + unmatched event detail dump
//
// Audio output is hardcoded:
//   default build  — orig sub_177bb plays via play_xmidi_external;
//                    v2_sfx_play_177bb_v2 is muted (#ifdef V2_ONLY no-op).
//   V2_ONLY build  — v2_sfx_play_177bb_v2 plays; orig executor not present.
// Slot table divergence in shadow vs real DS is already excluded from verify
// (0x990C..0x991E), so muted v2 doesn't break anything else.
//
// Hooks:
//   - vikings.exe_seg000.cpp orig sub_177bb SDL inline (seq=ax, obj=ds:0x42)
//   - v2_vm_op_sound (this file) when SFX request fires
//
// Periodic check at v2_phase_post_vm end + final dump on atexit.
// ============================================================================

struct SfxAuditEvent {
    int frame;          // v2_dbg_pre_vm_iter snapshot
    uint16_t seq;       // sequence # 0..0xFF
    uint16_t obj;       // ds:0x42 (current VM object) or 0xFFFF if hardcoded
    uint8_t source;     // 0 = orig, 1 = v2
    uint32_t ts_ms;     // SDL_GetTicks at log time
    bool matched;       // L2 marker
};

static constexpr size_t V2_AUDIT_RING_SIZE = 2048;
static SfxAuditEvent g_audit_ring[V2_AUDIT_RING_SIZE];
static std::atomic<size_t> g_audit_ring_idx{0};  // next slot to write (always increments)
static std::mutex g_audit_mutex;
static std::atomic<int> g_audit_orig_frame_count{0};
static std::atomic<int> g_audit_v2_frame_count{0};
static std::atomic<int> g_audit_diverges{0};       // total divergences detected

// Deterministic handle generator. Both orig and v2 compute the SAME handle
// for the same logical op_sound — when v2 mirrors orig perfectly, slot bytes
// in shadow_ds match real_ds without any data copying. When v2 misses an
// op_sound (the bug we want to catch), handles for subsequent calls in same
// frame/obj diverge → verify-hash also catches it.
//
// Hash inputs: (seq, obj, frame, fire_idx). fire_idx is the Nth op_sound
// fired for this obj this frame (per-thread counter, reset on FRAME_BEGIN).
// Range 1..0xFFFE (0 + 0xFFFF reserved).
// Inputs: seq, obj, frame, fire_idx. Frame entropy works because counter is
// incremented ONCE per outer frame at FRAME_BEGIN barrier — both orig and v2
// see same value throughout the entire frame (incl. sub_115d2 sub-frames).
uint16_t v2_audit_compute_handle(uint16_t seq, uint16_t obj, int frame, int fire_idx) {
    // Mix bits using xorshift-like spread.
    uint32_t h = (uint32_t)(seq & 0xFF);
    h ^= ((uint32_t)(obj & 0xFF)) << 8;
    h ^= ((uint32_t)(frame & 0xFFFF)) << 16;
    h ^= ((uint32_t)fire_idx) * 0x9E3779B1u;  // golden-ratio mixer
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    uint16_t r = (uint16_t)(h & 0xFFFF);
    if (r == 0 || r == 0xFFFF) r = 1;  // avoid reserved
    return r;
}

// Per-thread per-obj fire counter. Reset on FRAME_BEGIN. Used to disambiguate
// multiple op_sound calls for same obj in same frame.
static int g_audit_orig_fire_count[256] = {0};
static int g_audit_v2_fire_count[256] = {0};

// Music play counter (shared concept — only one music plays at a time, no obj).
// Per-source: orig and v2 each have their own counter. As long as both call
// sub_176bd the same number of times in the same order, counters stay in sync
// and produce identical music handles. Used for deterministic music handle so
// orig (real producer) and v2 (muted reservation in default mode) reserve slots
// with matching handles → ds:0x990C contains identical value in real and shadow.
static int g_audit_orig_music_count = 0;
static int g_audit_v2_music_count = 0;

void v2_audit_reset_fire_counters() {
    // Reset SFX per-obj fire counters at FRAME_BEGIN. Frame entropy (in hash)
    // disambiguates SFX across frames, so counter only needs to disambiguate
    // multiple fires within same frame for same obj. Both orig+v2 reset in
    // same FRAME_BEGIN barrier handler → same starting point.
    for (int i = 0; i < 256; i++) {
        g_audit_orig_fire_count[i] = 0;
        g_audit_v2_fire_count[i] = 0;
    }
    // NOTE: music counter NOT reset (still monotonic). Music fires once per
    // track change — counter wrap at 65k calls is unreachable in practice.
    // Frame entropy not added to music hash because music has no per-obj
    // fire_idx to disambiguate within a frame; monotonic counter is sufficient.
}

// Get next fire_idx for orig source (per-obj) and increment.
int v2_audit_orig_next_fire_idx(uint16_t obj) {
    return g_audit_orig_fire_count[obj & 0xFF]++;
}

// Get next fire_idx for v2 source (per-obj) and increment.
int v2_audit_v2_next_fire_idx(uint16_t obj) {
    return g_audit_v2_fire_count[obj & 0xFF]++;
}

int v2_audit_orig_next_music_idx() { return g_audit_orig_music_count++; }
int v2_audit_v2_next_music_idx() { return g_audit_v2_music_count++; }

// Compute deterministic music handle. Inputs: bx_seg (segment containing music
// XMI data) and play_idx (monotonic Nth music play counter — never resets).
// Per-source counter (orig + v2 each track separately) — they stay in sync as
// long as both fire sub_176bd the same number of times. Monotonic counter alone
// gives unique handle per call, no frame entropy needed (which was breaking
// orig+v2 sync in default mode where they may fire in different frames).
// Revival-on-collision protected by set_dontstop_external safety check (skips
// slots already marked need_close).
uint16_t v2_audit_compute_music_handle(uint16_t bx_seg, int play_idx) {
    uint32_t h = (uint32_t)bx_seg;
    h ^= ((uint32_t)play_idx) * 0x9E3779B1u;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    // Music handles in upper half of range to visually distinguish from SFX.
    // 15-bit space (0x8000..0xFFFE) for ~32k unique handles.
    uint16_t r = (uint16_t)((h & 0x7FFF) | 0x8000);
    if (r == 0xFFFF) r = 0x8001;
    return r;
}

// True while inside v2_vm_replay_anim_cmd — suppresses side effects from v2
// handlers via fx:: wrappers. Side-effect impls themselves don't know about
// this flag — only fx:: wrappers route through it. This keeps verify concerns
// out of production code (sub_177bb_v2, sub_176bd_v2, etc.).
thread_local bool v2_in_replay_anim = false;

// ============================================================================
// Verify skip ranges — table-driven for centralization (closes tasks #92-102).
//
// Each entry: [start, end] inclusive byte offsets in DS to exclude from
// v2_ds_hash comparison + per-byte init verify. Reasons documented per entry.
//
// PREVIOUSLY in tasks but NOW IN-SYNC (no skip needed — fix moved to mirror):
//   #92  ds:0x2E5C..0x2E7C DosMemAlloc seg addrs → v2_record_alloc mirrors
//   #93  ds:0x2E6A..0x2E70 sound seg ptrs (sub_10E85) → same mechanism
//   #96  ds:0x8638..0x863C PRNG seed → v2_vm_op_55 reads/writes shadow ds:0x8639
//   #101 ds:0xA398..0xA39C VGA page flip counter → v2_ds_modify_mutex atomic
// These ranges DO still appear in init-time skip (v2_ds_init_extra_skips) because
// they diverge at sub_11080 init before mirror mechanisms catch up.
// ============================================================================
struct VerifySkip {
    uint16_t start;
    uint16_t end;       // inclusive
    const char* reason;
};

static const VerifySkip v2_ds_skip_ranges[] = {
    // DOS/BIOS system state (not VM-controlled — host environment)
    {0x86AC, 0x86B0, "DOS INT 24h vector (#94)"},
    {0x86D0, 0x86D0, "BIOS checksum (#95)"},
    // Input layer — render thread async update mirrors orig INT9 ISR (#83/#105)
    {0x86DC, 0x86DE, "word_30bbc/30bbe input layer (orig INT9 async race)"},
    // {DS_LAST_CHAR,0x028D} skip REMOVED (#37b): the letter channel is now a
    // frame-boundary snap (sdl_int9_char_pending), both DS get it at one point.
    // VGA hardware state
    {0x9300, 0x9300, "VGA mode byte (#97)"},
    // Sound system — v2 doesn't fully replicate AIL/XMI
    {0x9934, 0x9934, "XMI buffer pointer (#99 sub_10E85 normalize, not in v2)"},
    {0x98E4, 0x9950, "AIL sound driver state (#98/#100/#102 merged)"},
    // VGA page-flip / vsync counter — render-thread async update
    {DS_VSYNC_COUNT, DS_VSYNC_COUNT, "word_3287C VGA interrupt race — orig pending, v2 clears immediate"},
    // Sound segment pointers — sub_10E85 normalize results (v2 doesn't mirror)
    {0x2E6A, 0x2E70, "sound segment pointers (#93 partial — sub_10E85 result fields)"},
};

// Bitmap cache over the static skip table (task #36): the linear range scan
// cost 30% of total CPU inside v2_ds_hash (16384 dwords × ~40 ranges × 2
// hashes per opcode). The table is static const — build the byte-granular
// lookup once; every caller (dword-step hash, byte/word-step verify loops)
// gets bit-identical answers.
static bool v2_ds_skip_bm[0x10000];
static bool v2_ds_skip_bm_ready = false;
static inline bool v2_ds_hash_skip(uint32_t i) {
    if (!v2_ds_skip_bm_ready) {
        for (const auto& r : v2_ds_skip_ranges)
            for (uint32_t a = r.start; a <= r.end && a < 0x10000; a++)
                v2_ds_skip_bm[a] = true;
        v2_ds_skip_bm_ready = true;
    }
    return i < 0x10000 ? v2_ds_skip_bm[i] : false;
}

// Push event into ring + bump per-frame counter. Thread-safe (lock).
// "Production" impl — no replay knowledge. v2 callers MUST go through
// fx::log_sfx wrapper. orig SFX callers (vikings.exe_seg000.cpp:16079) call
// directly with source=0 — they're never in replay context anyway.
void v2_audit_log_sfx(uint8_t source, uint16_t seq, uint16_t obj) {
    extern int v2_dbg_pre_vm_iter;
    SfxAuditEvent e;
    e.frame = v2_dbg_pre_vm_iter;
    e.seq = seq & 0xFF;
    e.obj = obj;
    e.source = source;
    e.ts_ms = SDL_GetTicks();
    e.matched = false;

    {
        std::lock_guard<std::mutex> g(g_audit_mutex);
        size_t slot = g_audit_ring_idx.fetch_add(1, std::memory_order_relaxed) % V2_AUDIT_RING_SIZE;
        g_audit_ring[slot] = e;
    }
    if (source == 0) g_audit_orig_frame_count.fetch_add(1, std::memory_order_relaxed);
    else             g_audit_v2_frame_count.fetch_add(1, std::memory_order_relaxed);
}

// L1: per-frame count check. Called at v2_phase_post_vm end (frame boundary).
// On divergence, dumps all SFX events from this frame so user sees which
// (seq, obj) the orig fired that v2 didn't (and vice versa).
void v2_audit_check_frame_end() {
    int orig = g_audit_orig_frame_count.exchange(0, std::memory_order_relaxed);
    int v2   = g_audit_v2_frame_count.exchange(0, std::memory_order_relaxed);
#ifdef V2_ONLY
    // Standalone build: there is no orig side to audit against — every v2
    // SFX would read as a false frame-count divergence.
    (void)orig; (void)v2;
    return;
#endif
    if (orig != v2) {
        extern int v2_dbg_pre_vm_iter;
        int cur_frame = v2_dbg_pre_vm_iter;
        fprintf(stderr, "AUDIT-FRAME-DIVERGE[f%d]: orig=%d v2=%d (delta=%d)\n",
                cur_frame, orig, v2, orig - v2);
#ifdef HEADLESS
        extern void headless_dump_divergence(const char*, int, const char*);
        char buf[128];
        snprintf(buf, sizeof(buf), "orig=%d v2=%d (delta=%d)", orig, v2, orig - v2);
        headless_dump_divergence("audit", cur_frame, buf);
#endif
        // Dump all events from THIS frame (orig and v2 separately).
        std::lock_guard<std::mutex> g(g_audit_mutex);
        size_t end = g_audit_ring_idx.load(std::memory_order_relaxed);
        size_t start = end > V2_AUDIT_RING_SIZE ? end - V2_AUDIT_RING_SIZE : 0;
        for (size_t i = start; i < end; i++) {
            SfxAuditEvent& e = g_audit_ring[i % V2_AUDIT_RING_SIZE];
            if (e.frame != cur_frame) continue;
            const char* src = e.source == 0 ? "ORIG" : "V2  ";
            fprintf(stderr, "  [%s] f%d seq=0x%02X obj=0x%02X ts=%ums\n",
                    src, e.frame, e.seq, e.obj, e.ts_ms);
        }
        g_audit_diverges.fetch_add(1, std::memory_order_relaxed);
    }
}

// L2: pairwise match. For each unmatched orig event, find v2 event with same
// (seq, obj) within ±3 frames and mark both matched. Called periodically
// (e.g., every 60 frames) and at final dump.
void v2_audit_match_events() {
    std::lock_guard<std::mutex> g(g_audit_mutex);
    size_t end = g_audit_ring_idx.load(std::memory_order_relaxed);
    size_t start = end > V2_AUDIT_RING_SIZE ? end - V2_AUDIT_RING_SIZE : 0;

    for (size_t i = start; i < end; i++) {
        SfxAuditEvent& a = g_audit_ring[i % V2_AUDIT_RING_SIZE];
        if (a.matched) continue;
        if (a.source != 0) continue;  // pair from orig side

        for (size_t j = start; j < end; j++) {
            if (i == j) continue;
            SfxAuditEvent& b = g_audit_ring[j % V2_AUDIT_RING_SIZE];
            if (b.matched) continue;
            if (b.source != 1) continue;
            if (b.seq != a.seq) continue;
            if (b.obj != a.obj) continue;
            int df = (b.frame > a.frame) ? b.frame - a.frame : a.frame - b.frame;
            if (df > 3) continue;
            a.matched = b.matched = true;
            break;
        }
    }
}

// L3: final dump on atexit. Unique seq sets, missing/extra summary, unmatched event detail.
void v2_audit_dump_final() {
    v2_audit_match_events();  // ensure final pairing pass
    std::lock_guard<std::mutex> g(g_audit_mutex);

    std::set<uint16_t> orig_seqs, v2_seqs;
    int orig_total = 0, v2_total = 0;
    int unmatched_orig = 0, unmatched_v2 = 0;

    size_t end = g_audit_ring_idx.load(std::memory_order_relaxed);
    size_t start = end > V2_AUDIT_RING_SIZE ? end - V2_AUDIT_RING_SIZE : 0;

    for (size_t i = start; i < end; i++) {
        SfxAuditEvent& e = g_audit_ring[i % V2_AUDIT_RING_SIZE];
        if (e.source == 0) {
            orig_seqs.insert(e.seq); orig_total++;
            if (!e.matched) unmatched_orig++;
        } else {
            v2_seqs.insert(e.seq); v2_total++;
            if (!e.matched) unmatched_v2++;
        }
    }

    fprintf(stderr, "\n========== SFX AUDIT FINAL REPORT ==========\n");
    fprintf(stderr, "Total events:    orig=%d  v2=%d  delta=%d\n", orig_total, v2_total, orig_total - v2_total);
    fprintf(stderr, "Unmatched events: orig=%d  v2=%d\n", unmatched_orig, unmatched_v2);
    fprintf(stderr, "L1 frame-diverges total: %d\n", g_audit_diverges.load());

    fprintf(stderr, "\nOrig unique seqs (%zu): ", orig_seqs.size());
    for (auto s : orig_seqs) fprintf(stderr, "0x%02X ", s);
    fprintf(stderr, "\n");
    fprintf(stderr, "V2 unique seqs   (%zu): ", v2_seqs.size());
    for (auto s : v2_seqs) fprintf(stderr, "0x%02X ", s);
    fprintf(stderr, "\n");

    bool any_missing = false;
    fprintf(stderr, "MISSING in v2 (orig has, v2 doesn't): ");
    for (auto s : orig_seqs) {
        if (v2_seqs.find(s) == v2_seqs.end()) {
            fprintf(stderr, "0x%02X ", s);
            any_missing = true;
        }
    }
    if (!any_missing) fprintf(stderr, "(none)");
    fprintf(stderr, "\n");

    bool any_extra = false;
    fprintf(stderr, "EXTRA in v2 (v2 has, orig doesn't):   ");
    for (auto s : v2_seqs) {
        if (orig_seqs.find(s) == orig_seqs.end()) {
            fprintf(stderr, "0x%02X ", s);
            any_extra = true;
        }
    }
    if (!any_extra) fprintf(stderr, "(none)");
    fprintf(stderr, "\n");

    if (unmatched_orig > 0) {
        fprintf(stderr, "\nUnmatched ORIG events (orig fired, no matching v2 within ±3 frames):\n");
        int shown = 0;
        for (size_t i = start; i < end && shown < 30; i++) {
            SfxAuditEvent& e = g_audit_ring[i % V2_AUDIT_RING_SIZE];
            if (e.matched || e.source != 0) continue;
            fprintf(stderr, "  f%d seq=0x%02X obj=0x%02X ts=%ums\n",
                    e.frame, e.seq, e.obj, e.ts_ms);
            shown++;
        }
        if (unmatched_orig > 30) fprintf(stderr, "  ... (%d more, truncated)\n", unmatched_orig - 30);
    }
    if (unmatched_v2 > 0) {
        fprintf(stderr, "\nUnmatched V2 events (v2 fired, no matching orig within ±3 frames):\n");
        int shown = 0;
        for (size_t i = start; i < end && shown < 30; i++) {
            SfxAuditEvent& e = g_audit_ring[i % V2_AUDIT_RING_SIZE];
            if (e.matched || e.source != 1) continue;
            fprintf(stderr, "  f%d seq=0x%02X obj=0x%02X ts=%ums\n",
                    e.frame, e.seq, e.obj, e.ts_ms);
            shown++;
        }
        if (unmatched_v2 > 30) fprintf(stderr, "  ... (%d more, truncated)\n", unmatched_v2 - 30);
    }
    fprintf(stderr, "============================================\n");
}

// Periodic match — called from frame-end check, every 60 frames.
static int v2_audit_periodic_counter = 0;
void v2_audit_periodic() {
    if (++v2_audit_periodic_counter >= 60) {
        v2_audit_periodic_counter = 0;
        v2_audit_match_events();
    }
}

// ============================================================================
// Opcode execution coverage (B5).
// Per-opcode counters bumped at every dispatch. Dumped at atexit:
//   - Top 20 most-executed opcodes (hotspots — confirm tested paths).
//   - All never-executed opcodes (coverage gaps — untested branches).
// Separate buckets: main VM (collision VM dispatcher, opcodes 0x00..0xD7) and
// anim cmds (handler-table dispatched, 0x00..0x1A).
// ============================================================================
uint64_t v2_op_main_count[256] = {0};   // main VM opcodes (via v2_vm_optable)
uint64_t v2_op_anim_count[32]  = {0};   // anim cmds (cmd <= 0x1A)

void v2_dump_opcode_coverage() {
    fprintf(stderr, "\n========== OPCODE COVERAGE REPORT ==========\n");
    {
        extern uint64_t v2_ch30c98_count[8];
        fprintf(stderr, "off_30C98 getter channels: 0:%llu 1:%llu 2:%llu 3:%llu 4:%llu "
                "| overlap 5:%llu 6:%llu 7:%llu\n",
                (unsigned long long)v2_ch30c98_count[0], (unsigned long long)v2_ch30c98_count[1],
                (unsigned long long)v2_ch30c98_count[2], (unsigned long long)v2_ch30c98_count[3],
                (unsigned long long)v2_ch30c98_count[4], (unsigned long long)v2_ch30c98_count[5],
                (unsigned long long)v2_ch30c98_count[6], (unsigned long long)v2_ch30c98_count[7]);
    }
    {
        extern uint64_t v2_pal_probe_frames, v2_pal_probe_diverged, v2_pal_probe_colors;
        fprintf(stderr, "PAL-PROBE (class C, task #12): frames=%llu diverged=%llu "
                "color-slots=%llu\n",
                (unsigned long long)v2_pal_probe_frames,
                (unsigned long long)v2_pal_probe_diverged,
                (unsigned long long)v2_pal_probe_colors);
    }
    // Main VM
    {
        int never = 0, executed = 0;
        for (int i = 0; i < 0xD8; i++) {
            if (v2_op_main_count[i] == 0) never++; else executed++;
        }
        fprintf(stderr, "Main VM opcodes (0x00..0xD7): %d executed, %d never (of 216 total)\n",
                executed, never);
        // Top 20 by count
        struct Entry { uint64_t c; int op; };
        Entry sorted[256];
        for (int i = 0; i < 256; i++) { sorted[i].c = v2_op_main_count[i]; sorted[i].op = i; }
        std::sort(sorted, sorted + 256, [](const Entry& a, const Entry& b){ return a.c > b.c; });
        fprintf(stderr, "  Top 20 most-executed:\n");
        for (int i = 0; i < 20 && sorted[i].c > 0; i++) {
            fprintf(stderr, "    op_%02X: %llu\n", sorted[i].op, (unsigned long long)sorted[i].c);
        }
        // Never-executed list
        fprintf(stderr, "  Never executed (coverage gaps): ");
        int shown = 0;
        for (int i = 0; i < 0xD8; i++) {
            if (v2_op_main_count[i] != 0) continue;
            if (shown++ < 40) fprintf(stderr, "%02X ", i);
        }
        if (shown == 0) fprintf(stderr, "(all covered)");
        else if (shown > 40) fprintf(stderr, "... +%d more", shown - 40);
        fprintf(stderr, "\n");
    }
    // Anim cmds
    {
        int never = 0, executed = 0;
        for (int i = 0; i <= 0x1A; i++) {
            if (v2_op_anim_count[i] == 0) never++; else executed++;
        }
        fprintf(stderr, "Anim cmds (0x00..0x1A): %d executed, %d never (of 27 total)\n",
                executed, never);
        for (int i = 0; i <= 0x1A; i++) {
            if (v2_op_anim_count[i] > 0)
                fprintf(stderr, "    anim_%02X: %llu\n", i, (unsigned long long)v2_op_anim_count[i]);
        }
        fprintf(stderr, "  Never executed: ");
        bool any = false;
        for (int i = 0; i <= 0x1A; i++) {
            if (v2_op_anim_count[i] == 0) { fprintf(stderr, "%02X ", i); any = true; }
        }
        if (!any) fprintf(stderr, "(all covered)");
        fprintf(stderr, "\n");
    }
    fprintf(stderr, "============================================\n");
}

// One-time atexit registration.
extern void v2_dump_psnap_summary();
struct V2AuditAtexitInit {
    V2AuditAtexitInit() {
        atexit(v2_audit_dump_final);
        atexit(v2_dump_opcode_coverage);
        atexit(v2_dump_psnap_summary);
    }
};
static V2AuditAtexitInit g_v2_audit_init;

// ============================================================================
// Audio slot leak detector (B2).
// Proactively detects stale handles in DS slot table (ds:0x990C..0x991E)
// BEFORE the FRAME_BEGIN cleanup hides them. Frame-level signal is much faster
// than ear-test for catching bugs like the elevator/platform sound regression
// (#126): a slot holding handle X where X is no longer active in the pool means
// the natural-end of that SFX wasn't propagated back to DS by the AIL ISR
// (which SDL port can't replicate without race). Reports also when the count
// of "DS-tracked slots" disagrees with "pool active SFX count" — net leak.
// Per-slot persistence counter flags chronic leaks (>60 frames stale).
// ============================================================================
static const uint16_t v2_audio_slot_h_off[4] = {0x990E, 0x9910, 0x9912, 0x9914};
static const uint16_t v2_audio_slot_s_off[4] = {0x9918, 0x991A, 0x991C, 0x991E};

// Per-(side, slot) stale-frame counters: side=0 real, 1=shadow. Reset on clear.
static int v2_audio_stale_streak[2][4] = {{0}};
// Per-(side, slot) one-shot first-leak log gate.
static bool v2_audio_first_leak_logged[2][4] = {{false}};

void v2_verify_audio_slots(uint8_t* ds, class AudioPool* pool, const char* side_tag, int side_idx, int frame) {
    if (!ds || !pool) return;
    int used = 0, stale = 0;
    for (int i = 0; i < 4; i++) {
        uint16_t h = *(uint16_t*)(ds + v2_audio_slot_h_off[i]);
        uint16_t s = *(uint16_t*)(ds + v2_audio_slot_s_off[i]);
        if (h == 0xFFFF) {
            v2_audio_stale_streak[side_idx][i] = 0;
            continue;
        }
        used++;
        bool active = pool->is_handle_active(h);
        if (active) {
            v2_audio_stale_streak[side_idx][i] = 0;
            continue;
        }
        stale++;
        v2_audio_stale_streak[side_idx][i]++;
        // First-ever leak in this slot → log.
        if (!v2_audio_first_leak_logged[side_idx][i]) {
            v2_audio_first_leak_logged[side_idx][i] = true;
            fprintf(stderr, "V2-AUDIO-LEAK[%s f%d]: slot=%d handle=0x%04X seq=0x%04X STALE (first sighting)\n",
                    side_tag, frame, i, h, s);
        }
        // Chronic leak → log every 60 frames.
        int streak = v2_audio_stale_streak[side_idx][i];
        if (streak == 60 || (streak > 60 && streak % 600 == 0)) {
            fprintf(stderr, "V2-AUDIO-LEAK-CHRONIC[%s f%d]: slot=%d handle=0x%04X seq=0x%04X stale for %d frames\n",
                    side_tag, frame, i, h, s, streak);
        }
    }
    // Capacity-exhaustion signal: 3+ slots simultaneously stale = approaching the
    // 4-slot DS capacity with no room for new SFX → real bug class (#126 elevator).
    if (stale >= 3) {
        static int _all_stale_logged[2] = {0};
        if (++_all_stale_logged[side_idx] == 1 || _all_stale_logged[side_idx] % 600 == 0) {
            fprintf(stderr, "V2-AUDIO-CAPACITY-LEAK[%s f%d]: %d/%d DS slots stale (capacity-exhaustion risk)\n",
                    side_tag, frame, stale, used);
        }
    }
}

// ============================================================================
// Render buffer compare (A2): viewport region pixel-level orig vs v2 verify.
// Catches render-only bugs (dialog cut-off #120, palette anim #125) that don't
// surface as DS divergence. Called at end of v2_phase_render3 after both orig
// and v2 have finished drawing this frame's final page.
// Orig side is CRTC-unfolded via v2_fetch_orig_page (task #19): drawBuffer is
// VGA Mode X memory ×4, rows scan from myOffset with pitch 0x56 bytes (CRTC
// offset reg 0x13 = 0x2B words) — NOT a flat 320-wide framebuffer.
// ============================================================================
struct myDrawInfoS_a2_fwd {  // forward layout for myDrawInfo access
    uint8_t drawBuffer[65536 * 4];
    SDL_Color drawPalette[256];
    uint32_t myOffset;
    uint8_t myPixelOffset;
};
extern struct myDrawInfoS_a2_fwd* myDrawInfo;
extern "C" uint32_t v2_fntest_game_ds_linear(void);
extern "C" int v2_fetch_orig_page(uint8_t* out, uint32_t count);
extern "C" int v2_vga_parity_check(const uint8_t* real_drawbuffer, int log_limit);
extern "C" int v2_vga_fetch_page(uint8_t* out, uint32_t count);
#ifdef V2_ONLY
// fn-test infrastructure lives in v2_fn_test.cpp + the m2c seg files, which
// are not part of the V2_ONLY build. The referencing paths are all gated by
// the oracle/verify context (never taken standalone) — link-level stubs.
extern "C" int v2_fntest_vm_soft = 0;
extern "C" uint32_t v2_fntest_game_ds_linear(void) { return 0; }
#endif
extern "C" void v2_draw_one_sprite_late(uint16_t ds_val, int obj);
static uint16_t v2_current_ds_val; // DS segment value for rendering calls (defined here, used below)
// Dirty-lag classification counters (task #20/#21) — printed by the
// headless render-diff summary.
uint64_t v2_render_lag_frames = 0, v2_render_lag_px = 0;
// Task #21 ring: per-sub-frame trace of one object's draw decisions on BOTH
// sides. Writers: orig sub_1dd9c head (gate path), orig type-2 renderer entry,
// v2 draw_sprites layers. Dumped on the first hard events (event-based).
struct V2ObjTrace { uint32_t seq; char tag[12]; int16_t a, b, c, d; };
static V2ObjTrace v2_objtrace_ring[256];
static uint32_t v2_objtrace_n = 0;
// Traced object index (env V2_OBJTRACE_DI, default 0x48).
extern "C" int v2_objtrace_di = 0xFFFF;  // #40 flag: default OFF (was 0x48); env V2_OBJTRACE_DI re-enables the per-object diagnostic trace
extern "C" void v2_objtrace(const char* tag, int a, int b, int c, int d) {
    static int _init = 0;
    if (!_init) {
        _init = 1;
        if (const char* e = getenv("V2_OBJTRACE_DI")) v2_objtrace_di = (int)strtol(e, 0, 0);
        fprintf(stderr, "OBJTRACE-DI=%02X\n", v2_objtrace_di);
    }
    V2ObjTrace& e = v2_objtrace_ring[v2_objtrace_n % 256];
    e.seq = v2_objtrace_n++;
    snprintf(e.tag, sizeof(e.tag), "%s", tag);
    e.a = (int16_t)a; e.b = (int16_t)b; e.c = (int16_t)c; e.d = (int16_t)d;
}
// Task #19 aid: env V2_PIXWATCH=<y*320+x> — print every stage (across ALL
// render passes) that changes that v2_render_buf pixel.
void v2_pixwatch_stage(const char* stage) {
    static long _pw = -2;
    static uint8_t _pw_last = 0;
    if (_pw == -2) { const char* e = getenv("V2_PIXWATCH"); _pw = e ? strtol(e, 0, 0) : -1; }
    if (_pw < 0) return;
    extern uint8_t v2_render_buf[];
    uint8_t cur = v2_render_buf[_pw];
    if (cur != _pw_last) {
        fprintf(stderr, "PIXWATCH[%s]: %02X -> %02X\n", stage, _pw_last, cur);
        _pw_last = cur;
    }
}
int v2_render_frame = 0;   // #32: deterministic render-frame index (see below)
void v2_verify_render_buf(int frame) {
    // #32 determinism: the caller passes v2_dbg_pre_vm_iter, which is inflated
    // by v2_blocking_loop_tick() inside the viking-switch / pause blocking loops
    // (#180 max-frames guard). Those loops spin a WALL-CLOCK-variable number of
    // times, so the same replay produced different frame labels across runs even
    // though the pixel content is identical (proven: hard-diff multisets match
    // run-to-run). This counter advances once per render3 comparison — one per
    // real game frame, deterministic per replay — and drives every divergence /
    // A2 label below. v2_dbg_pre_vm_iter is left untouched (input-replay tagging
    // and the headless max-frames guard still need its blocking-loop cadence).
    frame = ++v2_render_frame;
    extern uint8_t v2_render_buf[320*200];
    if (!myDrawInfo) return;
    uint32_t page_offset = myDrawInfo->myOffset * 4 + myDrawInfo->myPixelOffset;
    // CRTC unfold of the visible page (pitch 0x56 bytes/row — task #19).
    static uint8_t orig_unfold[320 * 176];
    if (!v2_fetch_orig_page(orig_unfold, sizeof(orig_unfold))) return;
    const uint8_t* orig_pixels = orig_unfold;
    // #39: is the myOffset(CRTC) vs ds:92F9(SHOWN-role) lag constant? Log per
    // frame: roles + myOffset + scroll_x. Env V2_PAGELOG.
    if (getenv("V2_PAGELOG") && v2_vm_get_shadow_ds() && v2_m2c_base) {
        uint8_t* rds4 = v2_m2c_base + v2_fntest_game_ds_linear();
        uint16_t scx = *(uint16_t*)(rds4 + 0x2581);
        static int _pn = 0;
        if (scx != 0 && _pn < 50) { _pn++;
            uint16_t shown = *(uint16_t*)(rds4 + 0x92F9);
            // base for the SHOWN role via the page-VGA LUT (row 0): [shown - 0x7608]
            uint16_t base_shown = *(uint16_t*)(rds4 + (uint16_t)(shown - 0x7608));
            uint8_t gdirty = rds4[0x956B];       // glyph dirty flag (1e0c7 entry gate)
            uint16_t thr98dc = *(uint16_t*)(rds4 + 0x98DC);  // 1e0c7 throttle counter (caps flush at 4)
            uint8_t c25cf = rds4[0x25CF];
            uint8_t g_first = 0; uint16_t g_at = 0;
            for (uint16_t p = 0; p < 0x370; p++) if (rds4[0x956C + p]) { g_first = rds4[0x956C + p]; g_at = p; break; }
            fprintf(stderr, "PAGELOG f%d: scroll_x=%d 956B=%d 98DC(throttle)=%d 25CF&E0=%02X | glyph@%d=%02X\n",
                    frame, scx, gdirty, thr98dc, c25cf & 0xE0, g_at, g_first);
        }
    }
    // shadow-VGA: the A2 sensor compares the shadow-VGA CRTC window — the same
    // byte-parity channel V2_VGAPARITY verifies (intro 0 hard, scenarios
    // PASS). Before the first page flip (no CRTC yet) fall back to the clean
    // display frame.
    static uint8_t v2_vga_win[320 * 176];
    const uint8_t* v2_frame =
        v2_vga_fetch_page(v2_vga_win, sizeof(v2_vga_win)) ? v2_vga_win
                                                          : v2_render_buf;
    // Tile-anim phase parity (task #21 f459 class): checksum tile 0xC0's 64
    // bytes in the REAL vs SHADOW tile-graphics segments at verify time.
    if (v2_objtrace_di != 0xFFFF && v2_m2c_base) {
        static int _tc = 0;
        if (_tc < 24) {
            uint8_t* _rds = v2_m2c_base + v2_fntest_game_ds_linear();
            uint16_t gr = *(uint16_t*)(_rds + DS_SEG_TILEGFX);
            extern uint8_t* v2_vm_get_shadow_ds();
            uint8_t* shd2 = v2_vm_get_shadow_ds();
            uint16_t gs = shd2 ? *(uint16_t*)(shd2 + DS_SEG_TILEGFX) : 0;
            extern uint8_t* v2_resolve_segment(uint16_t seg, uint8_t* shadow_ds);
            uint8_t* rb = gr ? v2_m2c_base + ((uint32_t)gr << 4) : nullptr;
            uint8_t* sb = gs ? v2_resolve_segment(gs, shd2) : nullptr;
            if (rb && sb) {
                int sr = 0, ss = 0;
                for (int i = 0; i < 64; i++) { sr += rb[0xC0 * 64 + i]; ss += sb[0xC0 * 64 + i]; }
                if (sr != ss || _tc < 4) {
                    _tc++;
                    fprintf(stderr, "TILE-C0[f%d]: real=%d shadow=%d%s\n",
                        frame, sr, ss, sr != ss ? "  <-- PHASE DRIFT" : "");
                }
            }
        }
    }
    // 3-page rotation ring: last 3 distinct myOffset values. The orig dirty
    // channels repaint a changed object on [obj+0x114D]-low-byte pages only
    // (sub_1dd9c: DEC per draw; the 0x202 sub-sprite channel grants just TWO
    // repaints) — so one rotation page legitimately lags one animation phase
    // behind on DOS hardware too. Classify each diff pixel: if the v2 value
    // matches ANY rotation page, orig has already painted that phase
    // somewhere — a legit dirty-lag ("lag"); if it matches NO page, it is a
    // real render divergence ("hard").
    static uint32_t _pg_ring[3] = {0, 0, 0};
    if (_pg_ring[0] != myDrawInfo->myOffset) {
        _pg_ring[2] = _pg_ring[1]; _pg_ring[1] = _pg_ring[0]; _pg_ring[0] = myDrawInfo->myOffset;
    }

    // Hash viewport region (rows 0-175, HUD has separate page-flip logic)
    uint32_t h_orig = 0, h_v2 = 0;
    int viewport_diff = 0;
    int first_diff_x = -1, first_diff_y = -1;
    for (int y = 0; y < 176; y++) {
        for (int x = 0; x < 320; x++) {
            uint8_t o = orig_pixels[y * 320 + x];
            uint8_t v = v2_frame[y * 320 + x];
            h_orig = h_orig * 131u + o;
            h_v2   = h_v2   * 131u + v;
            if (o != v) {
                if (viewport_diff == 0) { first_diff_x = x; first_diff_y = y; }
                viewport_diff++;
            }
        }
    }
    // shadow-VGA: byte parity of the shadow VGA (covered bytes) vs the real
    // drawBuffer. Env V2_VGAPARITY. Zero diffs = every migrated writer is
    // byte-exact at its orig addresses.
    if (getenv("V2_VGAPARITY")) {
        static uint64_t vp_sum = 0; static int vp_frames = 0, vp_bad = 0;
        int d = v2_vga_parity_check(myDrawInfo->drawBuffer, 6);
        extern int v2_vga_parity_hud;
        vp_sum += (uint64_t)d; vp_frames++; if (d) vp_bad++;
        static int _vp = 0;
        if (d || ++_vp % 100 == 0)
            fprintf(stderr, "VGAPARITY[f%d]: vp=%d hud=%d (frames=%d bad=%d cum=%llu)\n",
                    frame, d, v2_vga_parity_hud, vp_frames, vp_bad, (unsigned long long)vp_sum);
    }
    // #39: compare render_buf (clean tiles, NO glyph/emu overlay) vs orig, to
    // measure whether the emu glyph/page layer helps or hurts. Env V2_RBUF_CMP.
    if (getenv("V2_RBUF_CMP")) {
        static uint64_t rbuf_sum = 0, emu_sum = 0; static int rbuf_frames = 0;
        int rd = 0;
        for (int i = 0; i < 320*176; i++) if (orig_pixels[i] != v2_render_buf[i]) rd++;
        rbuf_sum += rd; emu_sum += viewport_diff; rbuf_frames++;
        static int _rc = 0;
        if (++_rc % 50 == 0 || rd != viewport_diff)
            fprintf(stderr, "RBUF-CMP[f%d]: render_buf-diff=%d emu-diff=%d | cum rbuf=%llu emu=%llu\n",
                    frame, rd, viewport_diff, (unsigned long long)rbuf_sum, (unsigned long long)emu_sum);
    }
    if (h_orig == h_v2) return;
    // Split the diff into hard vs dirty-lag using the alternate pages.
    int hard_diff = 0, lag_diff = 0;
    int first_hard_x = -1, first_hard_y = -1;
    {
        const uint8_t* alt[2] = {nullptr, nullptr};
        static uint8_t altbuf[2][320 * 176];
        int nalt = 0;
        for (int r = 1; r < 3 && nalt < 2; r++) {
            if (!_pg_ring[r]) continue;
            bool ok = true;
            for (uint32_t y = 0; y < 176 && ok; y++) {
                uint32_t base = (_pg_ring[r] + y * 0x56u) * 4u + myDrawInfo->myPixelOffset;
                if (base + 320 > sizeof(myDrawInfo->drawBuffer)) { ok = false; break; }
                memcpy(altbuf[nalt] + y * 320, myDrawInfo->drawBuffer + base, 320);
            }
            if (ok) { alt[nalt] = altbuf[nalt]; nalt++; }
        }
        for (int y = 0; y < 176; y++) {
            for (int x = 0; x < 320; x++) {
                uint8_t o = orig_pixels[y * 320 + x];
                uint8_t v = v2_frame[y * 320 + x];
                if (o == v) continue;
                bool legit = false;
                for (int a = 0; a < nalt && !legit; a++)
                    if (alt[a][y * 320 + x] == v) legit = true;
                if (legit) lag_diff++;
                else {
                    if (hard_diff == 0) { first_hard_x = x; first_hard_y = y; }
                    hard_diff++;
                }
            }
        }
    }
    v2_render_lag_frames += (lag_diff > 0);
    v2_render_lag_px += (uint64_t)lag_diff;
    if (hard_diff == 0) return;   // pure dirty-lag frame — counted in the summary
    // Class-C aid (env V2_A2_DUMP=1): on the FIRST hard frame dump both frames
    // as PGM + raw drawBuffer + (orig,v2) pixel-pair histogram + Y-shift
    // autodetect — identifies the diverging layer (#39 methodology).
    {
        static int _dump_on = -1;
        static int _dump_hard = -2;   // env V2_A2_DUMP_HARD=N: dump the first frame whose hard==N (any layer, event-based)
        static int _dump_hard_min = -2; // env V2_A2_DUMP_HARD_MIN=N: dump the first frame whose hard>=N
        if (_dump_on == -1) {
            _dump_on = getenv("V2_A2_DUMP") ? 1 : 0;
            const char* h = getenv("V2_A2_DUMP_HARD");
            _dump_hard = h ? atoi(h) : -1;
            const char* hm = getenv("V2_A2_DUMP_HARD_MIN");
            _dump_hard_min = hm ? atoi(hm) : -1;
        }
        static bool dumped = false;
        bool want = _dump_on && !dumped &&
                    (_dump_hard_min >= 0 ? hard_diff >= _dump_hard_min :
                     (_dump_hard < 0 ? true : hard_diff == _dump_hard));
        if (want) {
            dumped = true;
            // #39: compute orig glyph screen_y for buffer rows 2-7 using THIS
            // frame's myOffset + shown page, definitively (no page-pair ambiguity).
            if (v2_vm_get_shadow_ds() && v2_m2c_base) {
                uint8_t* rds3 = v2_m2c_base + v2_fntest_game_ds_linear();
                uint16_t scrx = *(uint16_t*)(rds3 + 0x2581);
                uint16_t pg9  = *(uint16_t*)(rds3 + 0x92F9);
                uint32_t moff = myDrawInfo->myOffset;
                fprintf(stderr, "A2-GLYPHY: scr_x=%d 92F9=%04X myOffset=%04X\n", scrx, pg9, moff);
                for (int r = 2; r <= 7; r++) {
                    uint16_t rs = (uint16_t)(r + scrx);
                    uint16_t d2 = (uint16_t)(rs*2 + pg9);
                    uint16_t vr = *(uint16_t*)(rds3 + (uint16_t)(d2 - 0x7608));
                    fprintf(stderr, "  row%d rs=%d vga_row=%04X orig_screen_y=%d (v2 draws at %d)\n",
                            r, rs, vr, ((int)vr - (int)moff)/86, r*8);
                }
            }
            FILE* fo = fopen("/tmp/v2_a2_orig.pgm", "wb");
            if (fo) { fprintf(fo, "P5\n320 176\n255\n"); fwrite(orig_pixels, 1, 320*176, fo); fclose(fo); }
            FILE* fv = fopen("/tmp/v2_a2_v2.pgm", "wb");
            if (fv) { fprintf(fv, "P5\n320 176\n255\n"); fwrite(v2_frame, 1, 320*176, fv); fclose(fv); }
            // #39: v2 render_buf (clean tiles, NO glyph/sprite overlay) — tests
            // whether the dialog box FRAME comes from tiles (matches orig y39) or glyph.
            { FILE* fr = fopen("/tmp/v2_a2_renderbuf.pgm", "wb");
              if (fr) { fprintf(fr, "P5\n320 176\n255\n"); fwrite(v2_render_buf, 1, 320*176, fr); fclose(fr); } }
            FILE* fb = fopen("/tmp/v2_a2_drawbuffer.bin", "wb");
            if (fb) { fwrite(myDrawInfo->drawBuffer, 1, 65536*4, fb); fclose(fb); }
            // FS tilemap first rows: real vs shadow (title-scene tile-channel probe)
            {
                extern uint8_t* v2_vm_get_shadow_ds();
                uint8_t* shd2 = v2_vm_get_shadow_ds();
                uint8_t* rds2 = v2_m2c_base ? v2_m2c_base + v2_fntest_game_ds_linear() : nullptr;
                if (shd2 && rds2) {
                    uint16_t fs_r = *(uint16_t*)(rds2 + DS_SEG_FS);
                    uint16_t fs_s = *(uint16_t*)(shd2 + DS_SEG_FS);
                    uint8_t* fr = v2_m2c_base + ((uint32_t)fs_r << 4);
                    extern uint8_t* v2_resolve_segment(uint16_t seg, uint8_t* shadow_ds);
                    uint8_t* fh = v2_resolve_segment(fs_s, shd2);
                    fprintf(stderr, "V2-A2-FS: real_seg=%04X shadow_seg=%04X\n", fs_r, fs_s);
                    // tilegfx tile #0 (64B) both sides + chunk plane row-0 heads
                    uint16_t tg_r = *(uint16_t*)(rds2 + DS_SEG_TILEGFX);
                    uint16_t tg_s = *(uint16_t*)(shd2 + DS_SEG_TILEGFX);
                    uint8_t* tr = v2_m2c_base + ((uint32_t)tg_r << 4);
                    uint8_t* ts = v2_resolve_segment(tg_s, shd2);
                    fprintf(stderr, "V2-A2-TILE0: real_seg=%04X shadow_seg=%04X\n  real  :", tg_r, tg_s);
                    for (int i = 0; i < 32 && tr; i++) fprintf(stderr, "%02X", tr[i]);
                    fprintf(stderr, "\n  shadow:");
                    for (int i = 0; i < 32 && ts; i++) fprintf(stderr, "%02X", ts[i]);
                    fprintf(stderr, "\n");
                    extern uint8_t* v2_vm_get_shadow_chunk();
                    uint8_t* shc2 = v2_vm_get_shadow_chunk();
                    uint16_t psz = *(uint16_t*)(shd2 + DS_DECOMP_SIZE);
                    fprintf(stderr, "V2-A2-CHUNKROW0: plane_size=%04X planes:", psz);
                    for (int p = 0; p < 4 && shc2; p++) {
                        fprintf(stderr, " p%d=", p);
                        for (int i = 0; i < 6; i++) fprintf(stderr, "%02X", shc2[(uint32_t)psz*p + i]);
                    }
                    fprintf(stderr, "\n");
                    for (int r = 4; r <= 8 && fr && fh; r++) {
                        fprintf(stderr, "  row%d real:", r);
                        for (int c = 8; c < 21; c++) fprintf(stderr, " %04X", *(uint16_t*)(fr + (r*43+c)*2));
                        fprintf(stderr, " | sh:");
                        for (int c = 8; c < 21; c++) fprintf(stderr, " %04X", *(uint16_t*)(fh + (r*43+c)*2));
                        fprintf(stderr, "\n");
                    }
                }
            }
            fprintf(stderr, "V2-A2-DUMPCTX: myOffset=%05X pixelOff=%u\n",
                    (unsigned)myDrawInfo->myOffset, (unsigned)myDrawInfo->myPixelOffset);
            static uint32_t pairs[256*256];
            memset(pairs, 0, sizeof(pairs));
            for (int y = 0; y < 176; y++)
                for (int x = 0; x < 320; x++) {
                    uint8_t o = orig_pixels[y*320+x], v = v2_frame[y*320+x];
                    if (o != v) pairs[o*256+v]++;
                }
            fprintf(stderr, "V2-A2-HIST[f%d]: top diff pairs (orig->v2 count):\n", frame);
            for (int k = 0; k < 10; k++) {
                uint32_t best = 0, bi = 0;
                for (uint32_t i = 0; i < 256*256; i++) if (pairs[i] > best) { best = pairs[i]; bi = i; }
                if (!best) break;
                fprintf(stderr, "  %02X->%02X : %u\n", bi>>8, bi&0xFF, best);
                pairs[bi] = 0;
            }
            // Y-shift autodetect: best dy in [-24,24] maximizing v2[y]==orig[y+dy].
            {
                int best_dy = 0; uint32_t best_m = 0;
                for (int dy = -24; dy <= 24; dy++) {
                    uint32_t m = 0;
                    for (int y = 0; y < 176; y++) {
                        int oy2 = y + dy; if (oy2 < 0 || oy2 >= 176) continue;
                        for (int x = 0; x < 320; x += 2)
                            if (v2_frame[y*320+x] == orig_pixels[oy2*320+x]) m++;
                    }
                    if (m > best_m) { best_m = m; best_dy = dy; }
                }
                fprintf(stderr, "V2-A2-YSHIFT[f%d]: best dy=%+d (match=%u of %u) — v2[y]==orig[y+dy]\n",
                        frame, best_dy, best_m, 176u*160u);
            }
            // Dump the v2 CRTC window + all 3 orig pages (offsets 0/0x34/0x68)
            // for offline diff.
            {
                FILE* fv = fopen("/tmp/v2_a2_vga_win.pgm", "wb");
                if (fv) { fprintf(fv, "P5\n320 176\n255\n");
                          fwrite(v2_frame, 1, 320*176, fv); fclose(fv); }
            }
            for (int p = 0; p < 3; p++) {
                char fn[64];
                static const uint32_t offs[3] = {0x0000, 0x0034, 0x0068};
                static uint8_t pg[320*176];
                bool ok = true;
                for (uint32_t y = 0; y < 176 && ok; y++) {
                    uint32_t base = (offs[p] + y * 0x56u) * 4u + myDrawInfo->myPixelOffset;
                    if (base + 320 > sizeof(myDrawInfo->drawBuffer)) { ok = false; break; }
                    memcpy(pg + y*320, myDrawInfo->drawBuffer + base, 320);
                }
                if (ok) {
                    snprintf(fn, sizeof(fn), "/tmp/v2_a2_orig_p%d.pgm", p);
                    FILE* fr = fopen(fn, "wb");
                    if (fr) { fprintf(fr, "P5\n320 176\n255\n"); fwrite(pg, 1, 320*176, fr); fclose(fr); }
                }
            }
        }
    }
    // Task #21 aid (env V2_HARD_OBJDUMP=1): on the first hard events dump the
    // live object table from BOTH sides (shadow vs real DS) plus the viewport
    // state — identifies which object owns the hard bbox and whether the two
    // sides disagree on its position/sprite-phase fields at compare time.
    {
        static int _od = -1;
        if (_od == -1) _od = getenv("V2_HARD_OBJDUMP") ? 8 : 0;
        if (_od > 0) {
            _od--;
            // Dump the obj-trace ring (writers: orig 1dd9c/renderer, v2 layers)
            for (uint32_t i = (v2_objtrace_n > 256 ? v2_objtrace_n - 256 : 0); i < v2_objtrace_n; i++) {
                V2ObjTrace& e = v2_objtrace_ring[i % 256];
                fprintf(stderr, "  OT[%u] %s a=%d b=%d c=%d d=%d\n", e.seq, e.tag, e.a, e.b, e.c, e.d);
            }
            extern uint8_t* v2_vm_get_shadow_ds();
            uint8_t* sh = v2_vm_get_shadow_ds();
            uint8_t* rl = v2_m2c_base ? v2_m2c_base + v2_fntest_game_ds_linear() : nullptr;
            if (!sh) return;
            fprintf(stderr, "V2-HARD-OBJ[f%d]: hard=%d first=(%d,%d) myOff=0x%X "
                    "sh vp=(%d,%d) sc=(%04X,%04X) | rl vp=(%d,%d) sc=(%04X,%04X)\n",
                    frame, hard_diff, first_hard_x, first_hard_y, myDrawInfo->myOffset,
                    *(int16_t*)(sh + 0x44), *(int16_t*)(sh + 0x46),
                    *(uint16_t*)(sh + DS_SCROLL_COL), *(uint16_t*)(sh + DS_SCROLL_ROW),
                    rl ? *(int16_t*)(rl + 0x44) : -1, rl ? *(int16_t*)(rl + 0x46) : -1,
                    rl ? *(uint16_t*)(rl + DS_SCROLL_COL) : 0xDEAD, rl ? *(uint16_t*)(rl + DS_SCROLL_ROW) : 0xDEAD);
            for (int obj = 0; obj <= 0xFE; obj += 2) {
                uint16_t sf = *(uint16_t*)(sh + obj + OBJ_SPRITE_FLAGS);
                uint16_t rf = rl ? *(uint16_t*)(rl + obj + OBJ_SPRITE_FLAGS) : 0;
                if (!(sf & 0x8000) && !(rf & 0x8000)) continue;
                fprintf(stderr, "  obj=%02X sh[fl=%04X xy=(%d,%d) spr=%04X:%04X sz=%04X rd=%04X pc=%04X]"
                        " rl[fl=%04X xy=(%d,%d) spr=%04X:%04X sz=%04X rd=%04X pc=%04X]%s\n",
                        obj, sf,
                        *(int16_t*)(sh + obj + OBJ_SPRITE_X), *(int16_t*)(sh + obj + OBJ_SPRITE_Y),
                        *(uint16_t*)(sh + obj + OBJ_SPRITE_SEG), *(uint16_t*)(sh + obj + OBJ_SPRITE_OFF),
                        *(uint16_t*)(sh + obj + OBJ_STRIP_COUNT), *(uint16_t*)(sh + obj + OBJ_DIRTY_MODE),
                        *(uint16_t*)(sh + obj + OBJ_ANIM_PC),
                        rf,
                        rl ? *(int16_t*)(rl + obj + OBJ_SPRITE_X) : 0, rl ? *(int16_t*)(rl + obj + OBJ_SPRITE_Y) : 0,
                        rl ? *(uint16_t*)(rl + obj + OBJ_SPRITE_SEG) : 0, rl ? *(uint16_t*)(rl + obj + OBJ_SPRITE_OFF) : 0,
                        rl ? *(uint16_t*)(rl + obj + OBJ_STRIP_COUNT) : 0, rl ? *(uint16_t*)(rl + obj + OBJ_DIRTY_MODE) : 0,
                        rl ? *(uint16_t*)(rl + obj + OBJ_ANIM_PC) : 0,
                        (rl && (sf != rf ||
                                *(uint16_t*)(sh + obj + OBJ_SPRITE_X) != *(uint16_t*)(rl + obj + OBJ_SPRITE_X) ||
                                *(uint16_t*)(sh + obj + OBJ_SPRITE_Y) != *(uint16_t*)(rl + obj + OBJ_SPRITE_Y) ||
                                *(uint16_t*)(sh + obj + OBJ_SPRITE_OFF) != *(uint16_t*)(rl + obj + OBJ_SPRITE_OFF)))
                            ? "  <-- SH/RL DIFF" : "");
            }
        }
    }
    // Throttle log: first 10 then every 60 frames
    static int _logged = 0;
    if (_logged < 10 || _logged % 60 == 0) {
        extern uint8_t* v2_vm_get_shadow_ds();
        uint8_t* shd = v2_vm_get_shadow_ds();
        if (!shd) shd = (uint8_t*)&frame; // never: keeps printf safe
        fprintf(stderr, "V2-RENDER-DIVERGE[f%d]: hard=%d lag=%d (first hard @ x=%d y=%d) "
                "orig_hash=%08X v2_hash=%08X page_off=0x%X roles=%04X/%04X/%04X "
                "vp=(%d,%d) shake=(%d,%d) sc=(%04X,%04X)\n",
                frame, hard_diff, lag_diff, first_hard_x, first_hard_y, h_orig, h_v2, page_offset,
                *(uint16_t*)(shd + DS_PAGE_DRAW), *(uint16_t*)(shd + DS_PAGE_SHOWN), *(uint16_t*)(shd + DS_PAGE_BG),
                *(int16_t*)(shd + 0x44), *(int16_t*)(shd + 0x46),
                *(int16_t*)(shd + DS_SHAKE_X), *(int16_t*)(shd + DS_SHAKE_Y),
                *(uint16_t*)(shd + DS_SCROLL_COL), *(uint16_t*)(shd + DS_SCROLL_ROW));
        // Task #23: pixel dump of the traced object's 24x16 area, orig vs v2,
        // on divergent frames (event-based, first 3).
        if (v2_objtrace_di != 0xFFFF) {
            static int _adump = 0;
            uint8_t* shd2 = v2_vm_get_shadow_ds();
            if (shd2 && _adump < 3) {
                int16_t ox = *(int16_t*)(shd2 + (uint16_t)(v2_objtrace_di + OBJ_SPRITE_X));
                int16_t oyw = *(int16_t*)(shd2 + (uint16_t)(v2_objtrace_di + OBJ_SPRITE_Y));
                int16_t vx = *(int16_t*)(shd2 + 0x44), vy = *(int16_t*)(shd2 + 0x46);
                int sx = ox - vx, sy = oyw - vy;
                if (first_hard_x >= sx - 8 && first_hard_x < sx + 40 &&
                    first_hard_y >= sy - 8 && first_hard_y < sy + 40) {
                    _adump++;
                    for (int yy = 0; yy < 16; yy++) {
                        int Y = sy + yy;
                        if (Y < 0 || Y >= 176) continue;
                        fprintf(stderr, "  A23-o y=%d:", Y);
                        for (int xx = 0; xx < 24; xx++) fprintf(stderr, " %02X", orig_pixels[Y*320 + sx + xx]);
                        fprintf(stderr, "\n  A23-v y=%d:", Y);
                        for (int xx = 0; xx < 24; xx++) fprintf(stderr, " %02X", v2_frame[Y*320 + sx + xx]);
                        fprintf(stderr, "\n");
                    }
                }
            }
        }
    }
    _logged++;
    first_diff_x = first_hard_x; first_diff_y = first_hard_y;
    viewport_diff = hard_diff;
    // Task #21 aid (env V2_RENDER_ALT_PAGE=1): on a divergent frame, re-unfold
    // the orig side from the OTHER two pages of the 3-page rotation and count
    // diffs against the same v2 frame. If an alternate page matches (or is
    // drastically closer), the residual classes are a page-selection lag of
    // the sensor (myOffset already advanced), not a render divergence.
    {
        static int _alt = -1;
        if (_alt == -1) _alt = getenv("V2_RENDER_ALT_PAGE") ? 1 : 0;
        if (_alt) {
            static uint32_t ring[3] = {0, 0, 0};   // last 3 distinct myOffset values
            uint32_t cur = myDrawInfo->myOffset;
            if (ring[0] != cur) { ring[2] = ring[1]; ring[1] = ring[0]; ring[0] = cur; }
            static int _alt_logged = 0;
            if (_alt_logged < 40) {
                _alt_logged++;
                char line[256]; int pos = 0;
                pos += snprintf(line + pos, sizeof(line) - (size_t)pos,
                                "V2-ALT-PAGE[f%d]: cur=0x%X diff=%d", frame, cur, viewport_diff);
                for (int r = 1; r < 3 && ring[r]; r++) {
                    int d = 0;
                    for (int y = 0; y < 176 && d >= 0; y++) {
                        uint32_t base = (ring[r] + (uint32_t)y * 0x56u) * 4u + myDrawInfo->myPixelOffset;
                        if (base + 320 > sizeof(myDrawInfo->drawBuffer)) { d = -1; break; }
                        const uint8_t* rowp = &myDrawInfo->drawBuffer[base];
                        const uint8_t* vrow = &v2_frame[y * 320];
                        for (int x = 0; x < 320; x++) if (rowp[x] != vrow[x]) d++;
                    }
                    pos += snprintf(line + pos, sizeof(line) - (size_t)pos,
                                    " | alt0x%X=%d", ring[r], d);
                }
                fprintf(stderr, "%s\n", line);
            }
        }
    }
    // Classification aid (env V2_RENDER_DIFF_DUMP=1): one-shot PPM pair + top
    // orig→v2 color pairs on the FIRST divergence event of the run.
#ifdef HEADLESS
    {
        static int _dumped = 0;
        static long _dump_at = -2;   // Nth divergence EVENT to dump (default 1st)
        if (_dump_at == -2) { const char* e = getenv("V2_RENDER_DIFF_DUMP_AT"); _dump_at = e ? strtol(e, 0, 0) : 1; }
        // Multi-dump mode (V2_RENDER_DIFF_DUMP=multi): PPM pair for the first
        // event of up to 6 distinct divergent frames, filenames carry frame no.
        static int _multi = -1;
        if (_multi == -1) { const char* e = getenv("V2_RENDER_DIFF_DUMP"); _multi = (e && !strcmp(e, "multi")) ? 1 : 0; }
        if (_multi && _dumped < 6) {
            static int _last_f = -1;
            if (frame != _last_f) {
                _last_f = frame;
                _dumped++;
                char pn[64];
                extern void headless_write_ppm(const char*, const uint8_t*, int, int, const SDL_Color*);
                snprintf(pn, sizeof(pn), "/tmp/v2_rdiff_f%d_orig.ppm", frame);
                headless_write_ppm(pn, orig_pixels, 320, 176, nullptr);
                snprintf(pn, sizeof(pn), "/tmp/v2_rdiff_f%d_v2.ppm", frame);
                headless_write_ppm(pn, v2_frame, 320, 176, nullptr);
            }
        }
        if (!_dumped && getenv("V2_RENDER_DIFF_DUMP") && _logged >= _dump_at) {
            _dumped = 1;
            extern void headless_write_ppm(const char*, const uint8_t*, int, int, const SDL_Color*);
            headless_write_ppm("/tmp/v2_rdiff_orig.ppm", orig_pixels, 320, 176, nullptr);
            headless_write_ppm("/tmp/v2_rdiff_v2.ppm", v2_frame, 320, 176, nullptr);
            struct Pair { uint8_t o, v; uint32_t n, at; };
            Pair top[6] = {};
            for (uint32_t i = 0; i < 320u * 176u; i++) {
                if (orig_pixels[i] == v2_frame[i]) continue;
                for (int k = 0; k < 6; k++) {
                    if (top[k].n && top[k].o == orig_pixels[i] && top[k].v == v2_frame[i]) { top[k].n++; break; }
                    if (!top[k].n) { top[k] = { orig_pixels[i], v2_frame[i], 1, i }; break; }
                }
            }
            for (int k = 0; k < 6 && top[k].n; k++)
                fprintf(stderr, "V2-RENDER-DIFF-PAIR: %02X->%02X n=%u sample@(%u,%u)\n",
                        top[k].o, top[k].v, top[k].n, top[k].at % 320, top[k].at / 320);
            // Task #19: tile-level forensics for the first diff cell — the map
            // word (from the REAL FS tilemap) and the current tile GFX row so
            // we can tell which side painted from the CURRENT tile-anim phase.
            if (v2_m2c_base) {
                uint8_t* rds = v2_m2c_base + v2_fntest_game_ds_linear();
                // v2_draw_tiles semantics: 8x8 tiles; scroll_x = ds:0x2581 is
                // the ROW scroll, scroll_y = ds:0x257F the COLUMN scroll.
                uint16_t row_sc = *(uint16_t*)(rds + DS_SCROLL_ROW);
                uint16_t col_sc = *(uint16_t*)(rds + DS_SCROLL_COL);
                uint16_t fsseg = *(uint16_t*)(rds + DS_SEG_FS);
                uint16_t gfxseg = *(uint16_t*)(rds + DS_SEG_TILEGFX);
                int trow = (first_diff_y >> 3) + row_sc;
                int tcol = (first_diff_x >> 3) + col_sc;
                uint16_t row_base = *(uint16_t*)(rds + (uint16_t)(trow * 2 - LUT_ROW_BASE));
                uint16_t map_off = (uint16_t)((row_base + tcol) * 2u);
                uint8_t* fs_real = v2_m2c_base + (uint32_t)fsseg * 16;
                uint16_t mapw_real = *(uint16_t*)(fs_real + map_off);
                extern uint8_t* v2_resolve_segment(uint16_t seg, uint8_t* shadow_ds);
                extern uint8_t* v2_vm_get_shadow_ds();
                uint8_t* sds = v2_vm_get_shadow_ds();
                uint8_t* fs_shad = sds ? v2_resolve_segment(fsseg, sds) : nullptr;
                uint16_t mapw_shad = fs_shad ? *(uint16_t*)(fs_shad + map_off) : 0xDEAD;
                uint8_t* gfx_shad = sds ? v2_resolve_segment(gfxseg, sds) : nullptr;
                fprintf(stderr, "V2-RENDER-DIFF-TILE: t=(%d,%d) rowsc=%04X colsc=%04X fs=%04X gfx=%04X "
                        "map_off=%04X mapw real=%04X shadow=%04X\n",
                        tcol, trow, row_sc, col_sc, fsseg, gfxseg, map_off, mapw_real, mapw_shad);
                uint8_t* gr = v2_m2c_base + (uint32_t)gfxseg * 16 + (mapw_real & 0xFFC0);
                fprintf(stderr, "  gfx(real mapw) 0-15:");
                for (int b = 0; b < 16; b++) fprintf(stderr, " %02X", gr[b]);
                if (gfx_shad) {
                    uint8_t* gs = gfx_shad + (mapw_shad & 0xFFC0);
                    fprintf(stderr, "\n  gfx(shad mapw,shad seg) 0-15:");
                    for (int b = 0; b < 16; b++) fprintf(stderr, " %02X", gs[b]);
                }
                fprintf(stderr, "\n");
                // actual painted rows of that cell from both sides
                int bx = (first_diff_x & ~15), by = (first_diff_y & ~15);
                fprintf(stderr, "  orig rows y=%d..%d @x=%d:", by, by + 1, bx);
                for (int yy = by; yy < by + 2; yy++)
                    for (int xx = bx; xx < bx + 16; xx++)
                        fprintf(stderr, "%s%02X", (xx == bx) ? " | " : " ", orig_pixels[yy * 320 + xx]);
                fprintf(stderr, "\n  v2   rows          :");
                for (int yy = by; yy < by + 2; yy++)
                    for (int xx = bx; xx < bx + 16; xx++)
                        fprintf(stderr, "%s%02X", (xx == bx) ? " | " : " ", v2_frame[yy * 320 + xx]);
                fprintf(stderr, "\n");
            }
        }
    }
#endif
#ifdef HEADLESS
    // Render diff is NON-CRITICAL — pixel-level only, DS state can match.
    // Log to render_diffs.log inside dump dir, summary at clean exit.
    // Do NOT exit — game continues, real DS divergences still cause exit.
    extern void headless_log_render_diff(int frame, int viewport_diff, int x, int y,
                                          uint32_t orig_hash, uint32_t v2_hash);
    headless_log_render_diff(frame, viewport_diff, first_diff_x, first_diff_y,
                              h_orig, h_v2);
#endif
}

// Symmetry verify: orig + v2 DS slot tables must show identical staleness pattern
// (same handles in same slots, same active/stale state). If diverged, v2's cleanup
// logic isn't synced with orig's DS slot state. Called once at FRAME_BEGIN after
// individual side verifies. Only meaningful in default mode. Caller passes both
// pointers (file-scope statics aren't visible here yet — see line 564, 1328).
void v2_verify_audio_slots_symmetry(uint8_t* real_ds, uint8_t* shadow_ds, int frame) {
    if (!real_ds || !shadow_ds) return;
    for (int i = 0; i < 4; i++) {
        uint16_t r_h = *(uint16_t*)(real_ds   + v2_audio_slot_h_off[i]);
        uint16_t s_h = *(uint16_t*)(shadow_ds + v2_audio_slot_h_off[i]);
        uint16_t r_s = *(uint16_t*)(real_ds   + v2_audio_slot_s_off[i]);
        uint16_t s_s = *(uint16_t*)(shadow_ds + v2_audio_slot_s_off[i]);
        if (r_h != s_h || r_s != s_s) {
            static bool _logged[4] = {false};
            if (!_logged[i]) {
                _logged[i] = true;
                fprintf(stderr, "V2-AUDIO-ASYMMETRY[f%d]: slot=%d real(h=%04X,s=%04X) != shadow(h=%04X,s=%04X)\n",
                    frame, i, r_h, r_s, s_h, s_s);
#ifdef HEADLESS
                extern void headless_dump_divergence(const char*, int, const char*);
                char buf[128];
                snprintf(buf, sizeof(buf), "slot=%d real(h=%04X,s=%04X) shadow(h=%04X,s=%04X)", i, r_h, r_s, s_h, s_s);
                headless_dump_divergence("audio-sym", frame, buf);
#endif
            }
        }
    }
}

// ============================================================================
// V2 VM shadow state — complete copy of DS region used by animation VM.
// Copied from real DS at frame start. VM reads/writes operate on shadow.
// This ensures v2 VM is fully independent from the original VM.
// ============================================================================

// Shadow of DS segment (animation table + globals).
// Covers ds:0x0000 to ds:0x1C00 — all animation fields + globals.
static const uint32_t V2_VM_SHADOW_SIZE = 0x10000; // Full 64KB DS segment
static uint8_t v2_vm_shadow_ds[V2_VM_SHADOW_SIZE];

static uint16_t v2_pre_vm_32F_snapshot = 0; // ds:0x32F before pre-VM phase modifies it

// Snapshot of orig DS taken right after orig sub_115d2 completes.
// Used by v2 to compare sub_115d2 output (exact same point in execution).
static uint8_t v2_115d2_snapshot[0x10000];
static bool v2_115d2_snapshot_valid = false;

// Shadow tile map — copy of the tile map segment (ES = ds:0x2E63).
// Copied from real tile map at frame start. v2 writes go here, not to real memory.
// v2_draw_tiles reads from here when V2_RENDER_FROM_SHADOW is enabled.
static const uint32_t V2_TILEMAP_SHADOW_SIZE = 0x10000; // 64KB max segment
static uint8_t v2_vm_shadow_tilemap[V2_TILEMAP_SHADOW_SIZE];
static bool v2_tilemap_shadow_valid = false;

// Shadow tile graphics — copy of the tile graphics segment (ds:0x2E5F).
// Read-only level data, but shadowed for full v2 independence.
static const uint32_t V2_TILEGFX_SHADOW_SIZE = 0x10000;
static uint8_t v2_vm_shadow_tilegfx[V2_TILEGFX_SHADOW_SIZE];
static bool v2_tilegfx_shadow_valid = false;

// Shadow animation data — copy of animation bytecode segment (ds:0x2E67).
// Contains 21-byte anim records + bytecodes. Read by VM, not normally modified.
static const uint32_t V2_ANIMDATA_SHADOW_SIZE = 0x10000;
static uint8_t v2_vm_shadow_animdata[V2_ANIMDATA_SHADOW_SIZE];
static bool v2_animdata_shadow_valid = false;

// Shadow GS segment — tile mask data (ds:0x2E61).
// Used by sub_1c8f1 / v2_draw_flagged_tiles for masked tile rendering.
static const uint32_t V2_GS_SHADOW_SIZE = 0x10000;
static uint8_t v2_vm_shadow_gs[V2_GS_SHADOW_SIZE];
static bool v2_gs_shadow_valid = false;

// Shadow GS tile data segment (ds:0x2E5D).
// Contains per-tile lookup data (8 bytes per tile). Used by sub_173c7 to build FS.
// Loaded from bg_chunk (word_2AAC5) during level init.
// SEPARATE from ds:0x2E61 (masks) — different segment, different data.
static const uint32_t V2_GS_TILEDATA_SIZE = 0x10000;
static uint8_t v2_vm_shadow_gs_tiledata[V2_GS_TILEDATA_SIZE];
static bool v2_gs_tiledata_valid = false;

// Shadow sound data segment (ds:0x2E6B).
// Sound sequences read by sound opcodes (0x02, 0x04, 0xD5, 0xD7).
static const uint32_t V2_SOUND_SHADOW_SIZE = 0x10000;
static uint8_t v2_vm_shadow_sound[V2_SOUND_SHADOW_SIZE];
static bool v2_sound_shadow_valid = false;

// ============================================================================
// V2 sound state — mirror of orig sound bookkeeping for adlmidi/play.cpp.
//
// Orig (vikings.exe_seg000.cpp):
//   - std::map<uint32_t,uint32_t> chunk_sizes — keyed by linear address (seg<<4)+offset.
//     Populated in read_chunk (sub_10982) line 1266.
//   - static int id_music inside sub_176bd — tracks current music player num.
//
// In V2_ONLY mode the orig sub_10982 doesn't run, so v2_chunk_sizes_by_seg is
// populated by v2_read_chunk callers when loading sound chunks. Lookup is by
// segment value (start offset is always 0 for sound chunks per orig sub_12ab8).
//
// In default mode v2 sound calls are no-ops (orig handles real sound emission).
// ============================================================================
static std::map<uint16_t, uint32_t> v2_chunk_sizes_by_seg;
static int v2_id_music = 0;  // 0 = no music (matches handle convention: 0/0xFFFF reserved)

// Resolve a sound segment value to (pointer-into-shadow, recorded-size).
// Returns nullptr if seg is outside the v2_vm_shadow_sound window.
static uint8_t* v2_resolve_snd_seg(const uint8_t* s, uint16_t seg, uint32_t* out_size) {
    uint16_t snd_base = *(const uint16_t*)(s + DS_SEG_SOUND_BASE);
    uint32_t off = (uint32_t)(uint16_t)(seg - snd_base) * 16;
    if (off >= V2_SOUND_SHADOW_SIZE) {
        if (out_size) *out_size = 0;
        return nullptr;
    }
    if (out_size) {
        auto it = v2_chunk_sizes_by_seg.find(seg);
        *out_size = (it != v2_chunk_sizes_by_seg.end()) ? it->second : 0;
    }
    return v2_vm_shadow_sound + off;
}

// orig sub_176bd SDL inline (vikings.exe_seg000.cpp:15900-15915).
// Plays MUSIC track from segment bx_seg as default sequence (-1).
// Symmetric with sub_177bb pattern: V2_ONLY → real producer; default mode →
// muted reservation. Both modes use deterministic handle so orig (real) and v2
// (muted) reserve slots with matching handles → ds:0x990C matches in shadow.
// v2 music play: operates on independent v2_pool. No #ifdef V2_ONLY needed —
// v2_pool is globally_muted in default mode (set in sound_init), so no audio
// output, but slot tracking continues for DS verify symmetry. In V2_ONLY,
// v2_pool is unmuted and produces audible audio.
static void v2_music_play_176bd_v2(uint8_t* s, uint16_t bx_seg) {
    uint32_t size = 0;
    uint8_t* xmidi = v2_resolve_snd_seg(s, bx_seg, &size);
    if (!xmidi || size == 0) return;
    if (v2_id_music != 0) v2_pool.stop_xmidi((uint16_t)v2_id_music);
    extern int v2_audit_v2_next_music_idx();
    extern uint16_t v2_audit_compute_music_handle(uint16_t bx_seg, int play_idx);
    int play_idx = v2_audit_v2_next_music_idx();
    uint16_t handle = v2_audit_compute_music_handle(bx_seg, play_idx);
    // V2_ONLY: v2 is the sole audio producer → mute=false (real playback).
    // Default mode: orig produces real audio, v2 only reserves slot for DS verify
    // symmetry → mute=true (no producer thread, no audio output).
#ifdef V2_ONLY
    bool mute = false;
#else
    bool mute = true;
#endif
    v2_id_music = v2_pool.play_xmidi_external_with_handle_and_mute(xmidi, size, -1, handle, mute);
    if (v2_id_music > 0) {
        v2_pool.set_dontstop((uint16_t)v2_id_music);
        // Mirror orig sub_176bd eip 0x76DA: `mov [si-66F4h], ax` with si=0 (music
        // call site uses si=0). Stores music handle at ds:0x990C (slot 0).
        *(uint16_t*)(s + DS_MUSIC_ID) = (uint16_t)v2_id_music;
    }
}

// orig sub_177bb SDL inline (vikings.exe_seg000.cpp:15905-15909).
// Plays SFX/sequence ax_seq from segment ds:0x2E6D (sound bank).
// Uses deterministic handle from audit infra so DS slot bytes match between
// orig (real_ds) and v2 (shadow_ds) without copying. In default mode, mute=true
// so v2 only reserves slot tracking — orig handles real audio output.
// Returns the deterministic handle.
extern int play_xmidi_external_with_handle_and_mute(const void* xmidi, uint32_t len, int seq_num,
                                                     uint16_t handle, bool mute);
// "Production" impl — no replay knowledge. v2 callers go through fx::play_sfx.
static int v2_sfx_play_177bb_v2(uint8_t* s, uint16_t ax_seq);
// Forward decl — fx::stop_all_sfx wraps this (full impl after fx:: namespace).
static void v2_seq_stop_all_17912_v2(uint8_t* s);

// =====================================================================
// fx:: — single point of replay-aware side-effect dispatch for v2.
// All v2 code paths that produce side effects (audio, audit, music) MUST
// route through fx:: wrappers. Side-effect impls (v2_sfx_play_177bb_v2 etc.) have
// NO replay knowledge — that concern lives only here. Adding a new side
// effect = add a new fx:: wrapper that gates and delegates to impl.
//
// Replay context (v2_in_replay_anim=true) is set by v2_vm_replay_anim_cmd
// when running v2 handlers for verification. Side effects are skipped because:
//   - For audio: orig already produces the real audio; replay is for DS
//     verification only, not a second playback.
//   - For audit: counters would double-increment, breaking deterministic
//     handle hashes (caused AUDIT-FRAME-DIVERGE divergence in task #103).
// =====================================================================
namespace fx {
    // Play SFX. Audit log fires INSIDE v2_sfx_play_177bb_v2 (mirror of orig sub_177bb
    // internal hook), so both wrappers automatically log. Returns deterministic
    // handle (0 if skipped via replay context).
    inline int play_sfx(uint8_t* shadow, uint16_t seq, uint16_t obj) {
        (void)obj; // audit reads obj from ds:0x42 inside v2_sfx_play_177bb_v2
        if (v2_in_replay_anim) return 0;
        return v2_sfx_play_177bb_v2(shadow, seq);
    }
    // Backward-compat alias — both wrappers identical now (audit moved into
    // v2_sfx_play_177bb_v2). Kept distinct name for call-site clarity (inventory/
    // pause/transition sites historically used _no_audit).
    inline void play_sfx_no_audit(uint8_t* shadow, uint16_t seq) {
        if (v2_in_replay_anim) return;
        v2_sfx_play_177bb_v2(shadow, seq);
    }
    inline void play_music(uint8_t* shadow, uint16_t bx_seg) {
        if (v2_in_replay_anim) return;
        v2_music_play_176bd_v2(shadow, bx_seg);
    }
    inline void stop_all_sfx(uint8_t* shadow) {
        if (v2_in_replay_anim) return;
        v2_seq_stop_all_17912_v2(shadow);
    }
}

static int v2_sfx_play_177bb_v2(uint8_t* s, uint16_t ax_seq) {
    uint16_t bx_seg = *(const uint16_t*)(s + DS_SEG_SOUND2);
    uint32_t size = 0;
    uint8_t* xmidi = v2_resolve_snd_seg(s, bx_seg, &size);
    if (!xmidi || size == 0) {
        fprintf(stderr, "V2-SFX-FAIL: seq=%u bx_seg=%04X xmidi=%p size=%u (chunk_sizes_by_seg miss?)\n",
            ax_seq, bx_seg, (void*)xmidi, size);
        return -1;
    }
    // Compute deterministic handle: same input on orig + v2 → same handle.
    // obj from VM context (cur_obj = ds[0x42]).
    extern int v2_dbg_pre_vm_iter;
    extern uint16_t v2_audit_compute_handle(uint16_t seq, uint16_t obj, int frame, int fire_idx);
    extern int v2_audit_v2_next_fire_idx(uint16_t obj);
    uint16_t obj = *(const uint16_t*)(s + DS_CUR_OBJ);
    int fire_idx = v2_audit_v2_next_fire_idx(obj);
    uint16_t handle = v2_audit_compute_handle(ax_seq, obj, v2_dbg_pre_vm_iter, fire_idx);
    // Audit log: mirror orig sub_177bb internal audit hook (seg000:16352).
    // Orig logs from inside sub_177bb so all callers (op_sound + pause/inventory/
    // transition mirror sites) get audited. v2 must do the same here, NOT at
    // wrapper level (fx::play_sfx vs play_sfx_no_audit), to capture all paths.
    // Without this, audit shows false "missing in v2" for seq=0x00/0x01 fired
    // by pause entry / sub_11cbb arrow handlers via play_sfx_no_audit.
    extern void v2_audit_log_sfx(uint8_t source, uint16_t seq, uint16_t obj);
    v2_audit_log_sfx(1 /* v2 */, ax_seq, obj);
#ifdef V2_ONLY
    // V2_ONLY: v2 is the sole audio producer → real playback through v2_pool
    // (symmetric with v2_music_play_176bd_v2 music path).
    int sdl_handle = v2_pool.play_xmidi_external_with_handle_and_mute(xmidi, size, (int)ax_seq, handle, false);
#else
    // Default mode: orig plays audible audio via orig_pool (orig sub_177bb SDL
    // inline). v2 only mirrors DS slot bookkeeping for verify symmetry — no
    // pool slot needed. Returning deterministic handle directly avoids creating
    // mute slots in orig_pool that leak `is_handle_active=true` forever
    // (no natural-end for slots without producer), which previously jammed the
    // 4-entry DS slot table after ~4 SFX in a level → stop opcodes couldn't
    // find new SFX (elevator/dialog sounds stuck).
    (void)xmidi; (void)size;
    int sdl_handle = (int)handle;
#endif

    // Mirror orig sub_177bb SDL inline (vikings.exe_seg000.cpp:16179-16202): on
    // play success, scan slots si=8,6,4,2 for first free (FFFF or stale handle),
    // store handle+seq. Anim cmd 0x77B2 falls through to sub_177bb in orig so
    // anim-fired SFX also gets slot bookkeeping; v2 must mirror at production
    // helper level (not per-call-site) to keep both paths symmetric — without
    // this, ds:0x9912/0x991C diverges at f175 (FIRST MISMATCH, op_2F).
    if (sdl_handle > 0 && sdl_handle <= 0xFFFE) {
        // Only check 0xFFFF (matches orig DOS asm at loc_177ca: CMP [si-66F4],
        // FFFFh). Earlier added is_handle_active() to detect stale handles,
        // but it raced between orig and v2 threads → DS divergence (f168 was
        // typical). Reverted to strict orig behavior — see v2_phase_frame_begin
        // TODO comment for proper stale-slot cleanup design.
        for (int si = 8; si > 0; si -= 2) {
            uint16_t handle_off = (uint16_t)(si - 0x66F4);
            uint16_t seq_off    = (uint16_t)(si - 0x66EA);
            uint16_t cur = *(uint16_t*)(s + handle_off);
            if (cur == 0xFFFF) {
                *(uint16_t*)(s + handle_off) = (uint16_t)sdl_handle;
                *(uint16_t*)(s + seq_off)    = ax_seq & 0xFF;
                break;
            }
        }
    }
    return (int)sdl_handle;
}

// orig sub_1782a SDL inline (vikings.exe_seg000.cpp:15976).
// Stops all SFX (music protected by v2_pool.dontstop_handle).
// Targets v2_pool unconditionally — in default mode this is no-op (v2 doesn't
// reserve SFX slots in any pool); in V2_ONLY v2_pool holds the real audible
// SFX slots so this actually stops audio. Orig path's audible audio is stopped
// by orig sub_1782a SDL inline (targets orig_pool), independent of this.
static void v2_sfx_stop_all_1782a_v2() {
    v2_pool.stop_all_sfx();
}

// orig sub_178d6 (vikings.exe_seg000.cpp:16062): if music not muted, replay it.
// Removed #ifdef V2_ONLY gate — in default mode orig plays music via orig_pool
// AND writes real_ds[0x990C] = handle. v2 mirror must symmetrically write
// shadow_ds[0x990C] via fx::play_music → v2_music_play_176bd_v2 (which reserves
// muted slot in v2_pool and writes shadow_ds[0x990C] with deterministic
// handle). Without this, anim VM op_D5 paths cause DS divergence at 0x990C.
static void v2_music_start_178d6_v2(uint8_t* s) {
    if (*(const uint16_t*)(s + DS_MUSIC_MUTE) != 0) return;  // music muted/off
    uint16_t bx_seg = *(const uint16_t*)(s + DS_SEG_SOUND);
    fx::play_music(s, bx_seg);
}

// orig sub_17912 mirror (vikings.exe_seg000.cpp:16304-16350).
// Per-slot stop + DS clear. Now matches orig (m2c port previously bypassed
// the assembly via early RETN; both orig and v2 now execute the per-slot stop).
//
// Logic (eips 0x7912-0x7973):
//   if (ds:0x302 != 0 && ds:0x304 != 0) return;      // both muted → ret
//   si = (ds:0x25B9 == 1) ? 2 : 0;                    // skip slot 0 (music) if 25B9==1
//   for si=si_start; si < 0xA; si += 2:
//     if [si-66F4] != FFFF:
//       AIL_stop_sequence(handle)   → SDL: stop_xmidi_external(handle)
//       AIL_release_sequence(handle) → SDL: no-op (stop already releases)
//       [si-66F4] = FFFF; [si-66EA] = FFFF
// "Production" impl — no replay knowledge. v2 callers go through fx::stop_all_sfx.
static void v2_seq_stop_all_17912_v2(uint8_t* s) {
    if (*(uint16_t*)(s + DS_MUSIC_MUTE) != 0 && *(uint16_t*)(s + DS_SFX_MUTE) != 0) return;
    uint16_t si = (s[DS_SND_FLAG] == 1) ? 2 : 0;
    while ((int16_t)si < 0x0A) {
        uint16_t handle_off = (uint16_t)(si - 0x66F4); // wraps to 0x990C+
        uint16_t handle = *(uint16_t*)(s + handle_off);
        if (handle != 0xFFFF) {
            v2_pool.stop_xmidi(handle);
            // If music slot (si=0), clear v2_id_music — auto-cleared by
            // stop_xmidi_external_v2 when matching v2_pool.dontstop_handle.
            if (si == 0 && (int)handle == v2_id_music) v2_id_music = 0;
            *(uint16_t*)(s + handle_off) = 0xFFFF;
            *(uint16_t*)(s + (uint16_t)(si - 0x66EA)) = 0xFFFF;
        }
        si += 2;
    }
}

// Shadow chunk buffer segment (ds:0x2E77).
// Large multi-purpose buffer: animation bytecodes (from sub_116ae) + intro chunk data.
// Original allocation: 0x2ABA paragraphs = 175,392 bytes (~171KB).
// sub_10E85 normalizes es:di across 64KB segment boundaries within this allocation.
// For v2 linear shadow: single contiguous buffer, offset = (es - base_seg) * 16 + di.
static const uint32_t V2_CHUNK_SHADOW_SIZE = 0x2ABA0; // 0x2ABA * 16 = 175,392 bytes
static uint8_t v2_vm_shadow_chunk[V2_CHUNK_SHADOW_SIZE];
static bool v2_chunk_shadow_valid = false;

// Shadow FS segment — render tilemap (ds:0x2E69).
// Built from ES (tilemap) + GS (tile masks) by sub_173c7.
// Used by VGA rendering (sub_16dd9). v2 rendering doesn't read from it,
// but maintaining it for state consistency.
static const uint32_t V2_FS_SHADOW_SIZE = 0x10000;
uint8_t v2_vm_shadow_fs[V2_FS_SHADOW_SIZE]; // non-static: accessed from seg000 ring compare
static bool v2_fs_shadow_valid = false;
// Orig FS snapshot after chunk 3 decompress (saved by seg000, compared by v2_load_level_data)
uint8_t v2_orig_fs_after_chunk3[8192];
bool v2_orig_fs_after_chunk3_valid = false;
// Orig GS tiledata snapshot after sub_11204 (saved by seg000, compared by v2_load_level_data)
uint8_t v2_orig_gs_tiledata_snapshot[4096];
bool v2_orig_gs_tiledata_snapshot_valid = false;
// Orig FS snapshot after sub_173c7 (saved by seg000)
uint8_t v2_orig_fs_after_173c7[0x6000];
bool v2_orig_fs_after_173c7_valid = false;
// FS[5586] trap for setdata
uint8_t* v2_fs5586_trap_addr = nullptr;
int v2_fs5586_trap_count = 0;

// Shadow sprite data buffer — for decompressed sprite graphics.
// Decompression (anim cmd 0x34DC) writes here instead of real game memory.
// v2_draw_sprites reads from here when available.
// Max: 128 sub-sprites × 1152 bytes each = 147KB.
// Indexed by absolute address (segment*16 + offset).
// We use a map-like approach: track which addresses have shadow data.
static const uint32_t V2_SPRITE_SHADOW_SIZE = 256 * 1024; // 256KB
static uint8_t v2_sprite_shadow[V2_SPRITE_SHADOW_SIZE];
static uint32_t v2_sprite_shadow_base = 0; // base address of shadow region
static bool v2_sprite_shadow_active = false;

// Accumulator lives in the active shadow DS at offset 0x8A — same as original.
// v2_vm_acc_base points to whichever shadow is active (main or replay).
// This ensures opcode handlers always write acc to the correct shadow.
static uint8_t* v2_vm_acc_base = v2_vm_shadow_ds;
#define v2_vm_accumulator (*(uint16_t*)(v2_vm_acc_base + 0x8A))

// Per-opcode execution trace for verification
struct V2VMTraceEntry {
    uint8_t  opcode;
    uint16_t pc_before;  // PC before opcode dispatch (after reading opcode byte)
    uint16_t pc_after;   // PC after opcode execution
    uint16_t acc_before; // accumulator BEFORE opcode
    uint16_t acc_after;  // accumulator AFTER opcode
    uint16_t es_seg;     // es segment value at this opcode
};
static const int V2_VM_TRACE_MAX = 512;
static V2VMTraceEntry v2_vm_trace[128][V2_VM_TRACE_MAX]; // per object slot
static int v2_vm_trace_count[128];

// Per-object detailed trace: set v2_trace_object to object index (0,2,4,...) to log every opcode.
// Set to 0xFFFF to disable. Traces to stderr with PC, opcode, accumulator, key DS reads.
static uint16_t v2_trace_object = 0xFFFF;

// Anim command counters for verification
int v2_orig_anim_cmd_count = 0;  // incremented by original's anim cmd loop
static int v2_v2_anim_cmd_count = 0;  // incremented by v2's anim cmd loop

static bool v2_replay_verify_active = false; // when true, resolve_segment uses real memory
uint16_t v2_input_snapshot = 0; // snapshot of input_keys taken by seg000 after orig sub_12352

// Phase 1: render thread directly writes word_30bbe (ds:0x86DE) — mirrors orig
// DOS INT 9 ISR semantics. Atomic update to:
//   - real DS (via m2c::m.word_30bbe in render.cpp)
//   - shadow DS at 0x86DE
//   - ALL stored phase snapshots at 0x86DE (via v2_patch_all_snaps_input,
//     defined later — see "Variant D" comment near v2_psnap_ds)
//
// Implementation note: v2_patch_all_snaps_input forward-declared here, defined
// after v2_psnap_ds[] array (line ~6724). Render thread writes are ISR-instant
// for game thread (sub_12352's `OR ax, word_30bbe` sees update immediately),
// while snapshot patching keeps verify infrastructure consistent.
static void v2_patch_all_snaps_input(uint16_t bit, bool press); // fwd decl

// Render thread reads shadow word_288AC (intro mode flag) without locking —
// brief read of single uint16_t is atomic on x86. Used by render thread KEYDOWN
// handler to mirror orig INT9 ISR intro dispatch (eip 0x6458 CMP word_288AC, 0x8000).
extern "C" uint16_t v2_shadow_word_288ac() {
    return *(const uint16_t*)(v2_vm_shadow_ds + DS_GAME_MODE_AC);
}

extern "C" void v2_shadow_input_or(uint16_t bit) {
    if (!bit) return;
    __atomic_or_fetch(reinterpret_cast<uint16_t*>(&v2_vm_shadow_ds[DS_INPUT_ACCUM]),
                      bit, __ATOMIC_RELAXED);
    v2_patch_all_snaps_input(bit, true);
}
extern "C" void v2_shadow_input_and_not(uint16_t bit) {
    if (!bit) return;
    __atomic_and_fetch(reinterpret_cast<uint16_t*>(&v2_vm_shadow_ds[DS_INPUT_ACCUM]),
                      (uint16_t)~bit, __ATOMIC_RELAXED);
    v2_patch_all_snaps_input(bit, false);
}

// ============================================================================
// Ring buffer: writes to ds:0x91A4 (ALT byte_31684) and ds:0x302 (word_287E2)
// Used to find divergence root cause between orig and shadow.
// ============================================================================
struct V2WriteRingEntry {
    uint32_t frame;
    uint32_t time_ms;
    uint16_t addr;
    uint16_t old_val;
    uint16_t new_val;
    bool is_shadow;       // true=shadow, false=real
    const char* src_label; // static string from caller
};
static const int V2_WRITE_RING_SIZE = 256;
static V2WriteRingEntry v2_write_ring[V2_WRITE_RING_SIZE] = {};
static int v2_write_ring_head = 0;

extern int v2_dbg_pre_vm_iter; // local forward decl (matches earlier C++ linkage)

void v2_log_write_ring(uint16_t addr, uint16_t old_val, uint16_t new_val,
                       bool is_shadow, const char* src) {
    static SDL_mutex* mu = SDL_CreateMutex();
    SDL_LockMutex(mu);
    int i = v2_write_ring_head;
    v2_write_ring[i].frame = (uint32_t)v2_dbg_pre_vm_iter;
    v2_write_ring[i].time_ms = SDL_GetTicks();
    v2_write_ring[i].addr = addr;
    v2_write_ring[i].old_val = old_val;
    v2_write_ring[i].new_val = new_val;
    v2_write_ring[i].is_shadow = is_shadow;
    v2_write_ring[i].src_label = src ? src : "?";
    v2_write_ring_head = (i + 1) % V2_WRITE_RING_SIZE;
    SDL_UnlockMutex(mu);
}

void v2_dump_write_ring(const char* reason) {
    fprintf(stderr, "===== V2 WRITE RING DUMP (reason=%s) =====\n", reason);
    int start = v2_write_ring_head;
    for (int n = 0; n < V2_WRITE_RING_SIZE; n++) {
        int i = (start + n) % V2_WRITE_RING_SIZE;
        if (v2_write_ring[i].src_label == nullptr) continue;
        fprintf(stderr, "  [%s f=%u t=%ums] ds:0x%04X %04X->%04X [%s]\n",
            v2_write_ring[i].is_shadow ? "SHAD" : "REAL",
            v2_write_ring[i].frame, v2_write_ring[i].time_ms,
            v2_write_ring[i].addr, v2_write_ring[i].old_val, v2_write_ring[i].new_val,
            v2_write_ring[i].src_label);
    }
    fprintf(stderr, "===== END V2 WRITE RING DUMP =====\n");
    fflush(stderr);
}

// Helper macros: instrument byte writes to ds:0x91A4
#define V2_WRITE_91A4_SHAD(val, src) do { \
    uint8_t _v = (val); \
    v2_log_write_ring(DS_KEY_ALT, v2_vm_shadow_ds[DS_KEY_ALT], _v, true, src); \
    v2_vm_shadow_ds[DS_KEY_ALT] = _v; \
} while(0)

// Mirror orig sub_10350's spec_state OR-ins (seg000.cpp lines 2560-2563) to
// shadow synchronously in game thread, BEFORE orig's F10 detection runs. Needed
// so v2_pw_pre_loop (fired by sub_104a1's PW_ENTRY signal inside the same orig
// frame) reads correct shadow[0x91B0/A4/99/7C] state to pick F10 vs ESC path.
// v2_phase_post_flip3's PART A also does this OR but fires too LATE
// (after sub_104a1 → PW_ENTRY signal already happened).
extern "C" void v2_spec_ors_mirror_10350() {
    // Read frame-frozen snapshot (sdl_spec_snap) — same value orig saw in
    // sub_10350. snap is now COPY semantics (sdl_spec_snapshot_take), so both
    // orig and v2 see identical frame-stable values — no race with render
    // thread KEYUP between reads. sdl_spec_state itself is SDL adapter state
    // (not real DS), so reading it satisfies "v2 from own shadow state" rule.
    v2_vm_shadow_ds[DS_KEY_F10] = sdl_spec_get(DS_KEY_F10);
    V2_WRITE_91A4_SHAD(sdl_spec_get(DS_KEY_ALT), "v2:mirror_sub_10350");
    v2_vm_shadow_ds[DS_KEY_X] = sdl_spec_get(DS_KEY_X);
    v2_vm_shadow_ds[DS_KEY_Q] = sdl_spec_get(DS_KEY_Q);
}

// Unified input read for inline sub_12352 sites. In V2_ONLY: reads live input_keys
// via v2_input_intro_mask (handles intro mode word_288ac=0x8000). In default mode:
// reads v2_input_snapshot atomic set by orig sub_12352 (synchronized with orig).
// Without this helper, V2_ONLY sites read v2_input_snapshot=0 → writes shadow[0x3BA]=0
// → next viking switch/dialog wait sees fake "newly pressed" → double-press bug.
static inline uint16_t v2_input_or(uint8_t* shadow, uint16_t ax_prev) {
#ifdef V2_ONLY
    // V2_ONLY: render thread keeps shadow[0x86DE] (word_30bbe) updated correctly
    // for both intro mode (writes 0xFFFF) and normal mode (OR-bit). Read shadow
    // directly — no input_keys/input mask layer needed. Race-free atomic read.
    extern uint16_t sdl_input_press_snap_get();
    uint16_t shadow_30bbe = *(volatile uint16_t*)(shadow + DS_INPUT_ACCUM);
    return ax_prev | shadow_30bbe | sdl_input_press_snap_get();
#else
    return ax_prev | v2_input_snapshot;
#endif
}

// SDL replacement for orig int 9 ISR's effect on word_30bbe (ds:0x86DE).
// Original ISR (seg000_6440_proc):
//   - Normal mode (word_288ac != 0x8000): KEYDOWN OR's per-scancode input bit
//     into word_30bbe; KEYUP clears it. Game reads word_30bbe in sub_12352.
//   - Intro mode (word_288ac == 0x8000, eip 0x651F): non-spec key → MOV
//     word_30bbe = 0xFFFF (any-key edge signal). Movement keys do NOT leak
//     into game during intro.
// Our SDL handler doesn't have ISR; this helper applies the equivalent
// transformation to the OR'd `ax` value at the read point.
//
// Called from:
//   - seg000.cpp sub_12352 at eip 0x2363 (default mode orig executor)
//   - v2_vm.cpp v2_phase_pre_vm input read (V2_ONLY mode)
// Both reach the same read site at most once per frame, so the static
// `prev_intro_keys` evolves consistently within a single binary.
uint16_t v2_input_intro_mask(uint16_t prev_ax_or, uint16_t word_288ac, uint16_t input) {
    static uint16_t prev_intro_keys = 0;
    static bool     intro_signal_sticky = false;
    extern uint16_t sdl_input_press_snap_get();
    uint16_t press_snap = sdl_input_press_snap_get();
    if (word_288ac != 0x8000) {
        prev_intro_keys = 0;
        intro_signal_sticky = false;
        return prev_ax_or | input | press_snap;
    }
    // INTRO MODE replication of orig INT9 ISR (eip 0x64CA dispatch + 0x651F
    // default). Orig: ANY keyboard event in intro sets word_30bbe = 0xFFFF
    // unconditionally, sticky until sub_11080 level reload clears it.
    // Brief tap (KEYDOWN+KEYUP entirely between intro_mask calls) handled
    // by render thread directly: when word_288AC == 0x8000, KEYDOWN writes
    // word_30bbe = 0xFFFF synchronously (atomic), matching orig INT9 sync
    // behavior exactly. See render.cpp KEYDOWN handler.
    if (input != prev_intro_keys) intro_signal_sticky = true;
    prev_intro_keys = input;
    if (intro_signal_sticky) return prev_ax_or | press_snap | 0xFFFF;
    return prev_ax_or | input | press_snap;
}
static uint16_t v2_word30BBE_snapshot = 0; // snapshot of word_30BBE at barrier sync point

// ============================================================================
// HW watchpoint via perf_event_open — catches ALL writes including memset/spillover
// Linux-only: requires perf_event_open syscall + linux/perf_event ABI. On other
// platforms (Windows mingw cross-build) the v2_hw_wp_* entry points become
// no-op stubs so callers in vikings.exe_seg000.cpp / seg003.cpp still link.
// ============================================================================
#ifdef __linux__
#include <dlfcn.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/syscall.h>
#include <sys/mman.h>
#include <linux/perf_event.h>
#include <linux/hw_breakpoint.h>

static int v2_hw_wp_fd = -1;
static struct perf_event_mmap_page* v2_hw_wp_mmap = nullptr;
static uint8_t* v2_hw_wp_ring = nullptr; // ring buffer data starts after mmap page
static const char* v2_hw_wp_label = "";
static uint8_t* v2_hw_wp_ptr = nullptr;
static size_t v2_hw_wp_ring_size = 0;

// Arm watchpoint on any byte. Uses mmap ring buffer for samples with real IP.
void v2_hw_wp_arm(uint8_t* ptr, const char* label) {
    if (v2_hw_wp_fd >= 0) {
        if (v2_hw_wp_mmap) munmap(v2_hw_wp_mmap, (1 + 4) * 4096);
        close(v2_hw_wp_fd);
        v2_hw_wp_fd = -1;
        v2_hw_wp_mmap = nullptr;
    }
    if (!ptr) return;

    v2_hw_wp_ptr = ptr;
    v2_hw_wp_label = label;

    struct perf_event_attr pe = {};
    pe.type = PERF_TYPE_BREAKPOINT;
    pe.size = sizeof(pe);
    pe.bp_type = HW_BREAKPOINT_W;
    pe.bp_addr = (unsigned long)ptr;
    pe.bp_len = HW_BREAKPOINT_LEN_1;
    pe.disabled = 0;
    pe.sample_period = 1;
    pe.sample_type = PERF_SAMPLE_IP | PERF_SAMPLE_ADDR;
    pe.wakeup_events = 1;

    v2_hw_wp_fd = syscall(__NR_perf_event_open, &pe, 0, -1, -1, 0);
    if (v2_hw_wp_fd < 0) { perror("HW-WP: perf_event_open"); return; }

    // mmap ring buffer: 1 metadata page + 4 data pages (must match munmap size)
    size_t mmap_size = (1 + 4) * 4096;
    void* mm = mmap(NULL, mmap_size,
                    PROT_READ | PROT_WRITE, MAP_SHARED, v2_hw_wp_fd, 0);
    if (mm == MAP_FAILED) { perror("HW-WP: mmap"); close(v2_hw_wp_fd); v2_hw_wp_fd = -1; return; }

    v2_hw_wp_mmap = (struct perf_event_mmap_page*)mm;
    v2_hw_wp_ring = (uint8_t*)mm + v2_hw_wp_mmap->data_offset;
    v2_hw_wp_ring_size = v2_hw_wp_mmap->data_size;

    ioctl(v2_hw_wp_fd, PERF_EVENT_IOC_ENABLE, 0);
    fprintf(stderr, "HW-WP: armed on %s (addr=%p) mmap ring=%zuB\n", label, ptr, v2_hw_wp_ring_size);
}

// Drain ring buffer — call periodically to read samples with IP + callchain
void v2_hw_wp_drain() {
    if (!v2_hw_wp_mmap || v2_hw_wp_fd < 0) return;
    static int total_samples = 0;
    static bool wp_disabled = false;
    static int call_count = 0;
    static uint8_t last_val = 0;
    if (wp_disabled) return;
    call_count++;

    // Peek: if the watched byte ever changes value, writes ARE happening.
    if (v2_hw_wp_ptr) {
        uint8_t cur = *(volatile uint8_t*)v2_hw_wp_ptr;
        uint8_t shadow_cur = v2_vm_shadow_gs_tiledata[0x3600];
        static uint8_t last_shadow = 0;
        if (cur != last_val || shadow_cur != last_shadow || (call_count % 100) == 1) {
            fprintf(stderr, "HW-WP-PEEK[call=%d]: real=%s=0x%02X (was 0x%02X) shadow_gs[0x3600]=0x%02X (was 0x%02X)\n",
                    call_count, v2_hw_wp_label, cur, last_val, shadow_cur, last_shadow);
            last_val = cur;
            last_shadow = shadow_cur;
        }
    }

    // Memory barrier to see latest data_head
    uint64_t head = __atomic_load_n(&v2_hw_wp_mmap->data_head, __ATOMIC_ACQUIRE);
    uint64_t tail = v2_hw_wp_mmap->data_tail;
    if (head != tail && (call_count % 50) == 1) {
        fprintf(stderr, "HW-WP-RING[call=%d]: head=%lu tail=%lu pending=%lu\n",
                call_count, (unsigned long)head, (unsigned long)tail,
                (unsigned long)(head - tail));
    }

    // Modular byte reader — record fields may straddle the ring wrap point.
    auto read_modular = [&](uint64_t& p, void* dst, size_t n) {
        uint8_t* d = (uint8_t*)dst;
        for (size_t i = 0; i < n; i++) {
            d[i] = v2_hw_wp_ring[(p + i) % v2_hw_wp_ring_size];
        }
        p = (p + n) % v2_hw_wp_ring_size;
    };

    while (tail < head && total_samples < 5000) {
        uint64_t off = tail % v2_hw_wp_ring_size;
        struct perf_event_header hdr;
        uint64_t hp = off;
        read_modular(hp, &hdr, sizeof(hdr));

        // DIAG: log EVERY record type to see if kernel produces non-SAMPLE
        // records (LOST, MMAP, THROTTLE, etc) that we may be ignoring.
        { static int _rec = 0;
          if (_rec++ < 50)
              fprintf(stderr, "HW-WP-REC[%d]: type=%u size=%u (tail=%lu head=%lu)\n",
                  _rec, hdr.type, hdr.size, (unsigned long)tail, (unsigned long)head);
        }
        // Safety: if size is 0 (corrupted), break to avoid infinite loop
        if (hdr.size == 0) {
            fprintf(stderr, "HW-WP: ABORT — hdr.size=0 (type=%u tail=%lu head=%lu)\n",
                hdr.type, (unsigned long)tail, (unsigned long)head);
            break;
        }

        if (hdr.type == PERF_RECORD_SAMPLE) {
            // Layout (sample_type = IP | ADDR, in canonical order):
            //   u64 ip; u64 addr;
            uint64_t p = (off + sizeof(hdr)) % v2_hw_wp_ring_size;
            uint64_t ip = 0, addr = 0;
            read_modular(p, &ip, sizeof(ip));
            read_modular(p, &addr, sizeof(addr));

            total_samples++;
            uint8_t val = v2_hw_wp_ptr ? *v2_hw_wp_ptr : 0;
            // IP-4 = the actual store instruction on aarch64 (PC has advanced past it)
            uint64_t store_ip = ip - 4;
            Dl_info dli = {};
            dladdr((void*)store_ip, &dli);
            const char* fname = dli.dli_sname ? dli.dli_sname : "??";
            uintptr_t foff = dli.dli_saddr ? (store_ip - (uintptr_t)dli.dli_saddr) : 0;
            fprintf(stderr, "HW-WP[%d]: %s = 0x%02X  store=0x%lX (%s+0x%lX) data_addr=0x%lX\n",
                total_samples, v2_hw_wp_label, val,
                (unsigned long)store_ip, fname, (unsigned long)foff,
                (unsigned long)addr);

            // Disable after 200 samples (safety) — enough to capture writers between
            // a few frame transitions without flooding stderr.
            if (total_samples >= 200) {
                ioctl(v2_hw_wp_fd, PERF_EVENT_IOC_DISABLE, 0);
                wp_disabled = true;
                fprintf(stderr, "HW-WP: DISABLED after %d samples (val=0x%02X)\n", total_samples, val);
            }
        }
        tail += hdr.size;
    }
    __atomic_store_n(&v2_hw_wp_mmap->data_tail, tail, __ATOMIC_RELEASE);
}

// Convenience: arm on shadow DS offset
void v2_hw_wp_arm_ds(uint16_t offset) {
    static char label[64];
    snprintf(label, sizeof(label), "shadow:0x%04X", offset);
    v2_hw_wp_arm(v2_vm_shadow_ds + offset, label);
}

#else  // !__linux__ — no-op stubs for non-Linux platforms (e.g. mingw Windows build)
void v2_hw_wp_arm(uint8_t* /*ptr*/, const char* /*label*/) {}
void v2_hw_wp_drain() {}
void v2_hw_wp_arm_ds(uint16_t /*offset*/) {}
#endif  // __linux__


// Forward declarations
static int32_t v2_spawn_object_13809(uint8_t* s, uint16_t code_seg_idx, uint16_t di_spawn,
                          uint16_t si_anim);
static void v2_vm_init_table();

// ============================================================================
// V2 Segment Resolver — maps segment:offset to shadow buffer pointers.
// In standalone mode, segment values are fake (assigned by v2_alloc_segments_12ab8).
// This function maps them to the correct shadow buffer + offset.
// ============================================================================
// fn-test hook (wave A, cmd14 unit): the anim decompressor writes through
// [slot+0x94D]/[0x B4D] segment fields; when a unit points them at the game
// DS segment, the oracle writes into its own DS image (compared byte-for-
// byte), and v2 must write into ITS scratch DS — not the m2c fallback zone
// (which is the oracle's restored image). Zero = off.
extern "C" uint16_t v2_fntest_ds_seg_override = 0;
extern "C" uint8_t* v2_fntest_ds_seg_ptr = nullptr;

uint8_t* v2_resolve_segment(uint16_t seg, uint8_t* shadow_ds) {
    if (v2_fntest_ds_seg_override && seg == v2_fntest_ds_seg_override && v2_fntest_ds_seg_ptr)
        return v2_fntest_ds_seg_ptr;
    if (v2_replay_verify_active && v2_m2c_base) {
        return v2_m2c_base + (uint32_t)seg * 16;
    }
    if (!shadow_ds) shadow_ds = v2_vm_shadow_ds;
    // Check each shadow segment by comparing with stored DS value.
    // ORDER MATTERS: narrow ranges first, wide ranges last.
    // Sprite segment: range [base .. base + 0x700 paragraphs]
    uint16_t sprite_base = *(uint16_t*)(shadow_ds + DS_SEG_SPRITE);
    if (sprite_base && seg >= sprite_base && seg < (uint16_t)(sprite_base + 0x700)) {
        return v2_sprite_shadow + (uint32_t)(seg - sprite_base) * 16;
    }
    // Exact segment matches
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_TILEGFX)) return v2_vm_shadow_tilegfx;
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_GS)) return v2_vm_shadow_gs;
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_TILEDATA)) return v2_vm_shadow_gs_tiledata;
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_TILEMAP)) return v2_vm_shadow_tilemap;
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_FS)) return v2_vm_shadow_fs;
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_ANIM)) return v2_vm_shadow_animdata;
    // Sound buffer alias: 0xE47-paragraph buffer at ds:0x992C contains chunks 1+2+3 (orig
    // sub_111f8). Any seg in [base, base+0xE47) maps to offset within shadow_sound.
    // Covers ds:0x2E6F (chunk 2 start), ds:0x2E6D (chunk 3 start), ds:0x2E6B (after).
    {
        uint16_t snd_base = *(uint16_t*)(shadow_ds + DS_SEG_SOUND_BASE);
        if (snd_base && seg >= snd_base && seg < (uint16_t)(snd_base + 0xE47)) {
            return v2_vm_shadow_sound + (uint32_t)(seg - snd_base) * 16;
        }
    }
    if (seg == *(uint16_t*)(shadow_ds + DS_SEG_SOUND)) return v2_vm_shadow_sound;
    // Animdata: range [base .. base + 0xC00 paragraphs] (for normalized pointers)
    uint16_t anim_base = *(uint16_t*)(shadow_ds + DS_SEG_ANIM);
    if (anim_base && seg >= anim_base && seg < (uint16_t)(anim_base + 0xC00)) {
        return v2_vm_shadow_animdata + (uint32_t)(seg - anim_base) * 16;
    }
    // Chunk buffer: range [base .. base + 0x2ABA paragraphs] — LAST (widest range)
    uint16_t chunk_base = *(uint16_t*)(shadow_ds + DS_SEG_CHUNK);
    if (chunk_base && seg >= chunk_base && seg < (uint16_t)(chunk_base + 0x2ABA)) {
        static int chunk_dbg = 0;
        if (chunk_dbg < 3) {
            chunk_dbg++;
            printf("V2-RESOLVE-CHUNK: seg=0x%04X chunk_base=0x%04X off=0x%X\n",
                   seg, chunk_base, (uint32_t)(seg - chunk_base) * 16);
        }
        return v2_vm_shadow_chunk + (uint32_t)(seg - chunk_base) * 16;
    }
    // Fallback to original emulated memory if available
    if (v2_m2c_base) {
#ifdef V2_ONLY
        // V2_ONLY: the fallback lands in the static-EXE snapshot buffer.
        // Static addresses (< 0x29F00: seg001 text, CS tables) are valid data;
        // a DYNAMIC segment here means the shadow resolve failed and the
        // caller reads zeros — make that visible instead of silent.
        if ((uint32_t)seg * 16 >= V2_EXE_STATIC_SIZE) {
            static int fb_dyn = 0;
            if (fb_dyn < 10) {
                fb_dyn++;
                printf("V2-RESOLVE-FALLBACK(V2_ONLY): dynamic seg 0x%04X not in "
                       "shadow tables — returning snapshot zeros [%d/10]\n", seg, fb_dyn);
            }
        }
#endif
        return v2_m2c_base + (uint32_t)seg * 16;
    }
    printf("V2-RESOLVE: unknown segment 0x%04X!\n", seg);
    return nullptr;
}

// ============================================================================
// V2 Resource System — LZSS decompressor + DATA.DAT reader
// Exact replica of sub_10982 (read_chunk). Writes to shadow buffers.
// ============================================================================
static FILE* v2_data_handle = nullptr; // v2's own DATA.DAT handle
static uint8_t* v2_vm_real_ds_ptr = nullptr; // for verification — set by init_shadow_early

// LZSS decompress from compressed data into destination buffer.
// Exact replica of sub_10982 decompression loop.
// src = compressed data, dest = output buffer, decompressed_size = target size.
// Returns number of bytes written.
// ring_out: if non-null, receives the final ring buffer state (LZSS sliding window).
// In the original, this is FS[0..0xFFF] — written by the decompressor during operation.
static bool v2_lzss_trace = false; // set before call to enable tracing
static uint32_t v2_lzss_decompress(const uint8_t* src, uint8_t* dest, uint16_t decompressed_size,
                                    uint8_t* ring_out = nullptr) {
    uint8_t ring[4096]; // 4KB ring buffer (ds:0..0xFFF in original)
    memset(ring, 0, 4096);
    uint16_t bx = 0;   // ring buffer write pos
    uint16_t si = 0;    // source read pos
    uint16_t di = 0;    // dest write pos
    uint16_t dx = decompressed_size;
    int _trace_n = 0;
    if (v2_lzss_trace) fprintf(stderr, "LZSS-TRACE: START decomp_size=%d src[0..3]=%02X%02X%02X%02X\n", decompressed_size, src[0], src[1], src[2], src[3]);

    auto finish = [&]() {
        if (ring_out) memcpy(ring_out, ring, 4096);
        return di;
    };

    while (true) {
        uint8_t flags = src[si++];
        for (int bit = 0; bit < 8; bit++) {
            if (flags & 1) {
                // Literal byte
                uint8_t val = src[si++];
                if (v2_lzss_trace && _trace_n < 30) { _trace_n++; fprintf(stderr, "LZSS[%d]: LIT si=%04X val=%02X → di=%04X bx=%04X\n", _trace_n, si-1, val, di, bx); }
                ring[bx] = val;
                bx = (bx + 1) & 0xFFF;
                dest[di++] = val;
                dx--;
                if (dx >= decompressed_size) return finish();
            } else {
                // Back-reference: 2 bytes → offset (12 bits) + length (4 bits) + 3
                uint16_t ref = *(uint16_t*)(src + si);
                si += 2;
                uint16_t length = ((ref >> 12) & 0xF) + 3;
                uint16_t offset = ref & 0xFFF;
                if (v2_lzss_trace && _trace_n < 30) { _trace_n++; fprintf(stderr, "LZSS[%d]: REF si=%04X ref=%04X off=%03X len=%d → di=%04X bx=%04X ring[off]=%02X\n", _trace_n, si-2, ref, offset, length, di, bx, ring[offset]); }
                for (uint16_t j = 0; j < length; j++) {
                    uint8_t val = ring[offset];
                    ring[bx] = val;
                    bx = (bx + 1) & 0xFFF;
                    dest[di++] = val;
                    dx--;
                    if (dx >= decompressed_size) return finish();
                    offset = (offset + 1) & 0xFFF;
                }
            }
            flags >>= 1;
        }
    }
    return finish();
}

// v2_read_chunk: read chunk from DATA.DAT into buffer.
// Exact replica of sub_10982/read_chunk: seek, read compressed, LZSS decompress.
// chunk_id = chunk number, dest = destination buffer, max_size = buffer size.
// Returns decompressed size, or 0 on failure.
// ds_ctx: the DS image receiving the orig side effects (header at 0x2BB4,
// plane size at 0x2BBC — orig sub_10982 freads them straight into DS).
// Defaults to the live shadow; isolated units pass their test image.
static uint32_t v2_read_chunk(uint16_t chunk_id, uint8_t* dest, uint32_t max_size,
                              uint8_t* ds_ctx = nullptr) {
    uint8_t* dctx = ds_ctx ? ds_ctx : v2_vm_shadow_ds;
    if (!v2_data_handle) {
        v2_data_handle = fopen("DATA.DAT", "rb");
        if (!v2_data_handle) return 0;
    }
    if (chunk_id == 0xFFFA) return 0; // special: no-op

    // Read chunk table entry: seek to chunk_id * 4
    uint32_t table_offset = (uint32_t)chunk_id * 4;
    if (fseek(v2_data_handle, table_offset, SEEK_SET)) return 0;

    // Read 8 bytes: offset (4) + next_offset (4)
    // Original sub_10982: fread(raddr(ds,0x2BB4), 8, 1, data_handle)
    uint8_t header[8];
    if (fread(header, 8, 1, v2_data_handle) != 1) return 0;
    uint32_t chunk_offset = *(uint32_t*)(header);
    uint32_t next_offset = *(uint32_t*)(header + 4);
    uint32_t compressed_size = next_offset - chunk_offset;
    // Write header to the DS context (orig sub_10982 writes ds:0x2BB4)
    memcpy(dctx + DS_CHUNK_HDR, header, 8);

    // Seek to chunk data
    if (fseek(v2_data_handle, chunk_offset, SEEK_SET)) return 0;

    // Read decompressed size (first 2 bytes)
    // Original: fread(raddr(ds,0x2BBC), 2, 1, data_handle)
    uint16_t decompressed_size;
    if (fread(&decompressed_size, 2, 1, v2_data_handle) != 1) return 0;
    *(uint16_t*)(dctx + DS_DECOMP_SIZE) = decompressed_size;

    // Original sub_10982: ecx = compressed_size (including 2-byte header already read).
    // After reading the 2-byte header, file position = chunk_offset + 2.
    // Original reads CX (the LOW 16 BITS of ecx) bytes from that position into
    // FS:0x1000 — 2 bytes more than the actual compressed data (spills into the
    // next chunk's first bytes; harmless, the decompressor stops on dx underflow).
    static uint8_t comp_buf[0x10000];
    uint32_t eax_check = compressed_size >> 4;    // orig: SHR eax,4 (32-bit)
    if (eax_check >= 0x0B08) {
        // Orig loc_1098e: sub_10dba twice = the FATAL "chunk too big" handler
        // (close file, print error via INT21, exit). No alternate load path
        // exists — the previous v2 "Non-FS temp" branch was invented. Real
        // DATA.DAT chunks never reach this (~45KB compressed limit).
        fprintf(stderr, "V2-CHUNK-FATAL: id=0x%X compressed=%u >= 0xB080 — orig would "
                "abort via sub_10dba (chunk too big)\n", chunk_id, compressed_size);
        return 0;
    }
    // Original: fread(fs:0x1000, cx, 1, data_handle), cx = low 16 bits of ecx.
    uint32_t fs_read_size = (uint16_t)compressed_size;
    size_t read = fread(v2_vm_shadow_fs + 0x1000, 1, fs_read_size, v2_data_handle);
    // Zero shadow_fs[0..0xFFF] — original: memset(ds:0, 0, 0x800 words)
    memset(v2_vm_shadow_fs, 0, 0x1000);
    // Copy to comp_buf for LZSS decompression
    if (read > 0) memcpy(comp_buf, v2_vm_shadow_fs + 0x1000, read);
    printf("V2-CHUNK: id=0x%X use_fs_temp comp=%d decomp=%d\n", chunk_id, (int)fs_read_size, decompressed_size);
    if (read == 0) return 0;
    bool use_fs_temp = true;   // ring lives in shadow FS (orig: ds = [ds:0x2E69])

    // LZSS decompress. When using FS as temp, the sliding window (ring buffer)
    // is written to shadow_fs[0..0xFFF] — replicating the original's ds:[bx] writes.
    if (chunk_id == 0x1AA) {
        v2_lzss_trace = true;
        fprintf(stderr, "V2-CHUNK-LZSS: chunk 0x1AA decomp=%d comp=%d use_fs=%d\n", decompressed_size, (int)compressed_size, use_fs_temp);
    }
    auto result = v2_lzss_decompress(comp_buf, dest, decompressed_size,
                              use_fs_temp ? v2_vm_shadow_fs : nullptr);
    if (chunk_id == 0x1AA) {
        v2_lzss_trace = false;
        // Compare decompressed output with orig segment IMMEDIATELY
        if (v2_m2c_base && v2_vm_real_ds_ptr) {
            uint16_t gs_seg = *(uint16_t*)(v2_vm_real_ds_ptr + 0x2E5D);
            if (gs_seg) {
                uint8_t* orig_gs = v2_m2c_base + (uint32_t)gs_seg * 16;
                fprintf(stderr, "V2-LZSS-IMMED: orig_gs[0..7]: %02X %02X %02X %02X %02X %02X %02X %02X\n",
                    orig_gs[0],orig_gs[1],orig_gs[2],orig_gs[3],orig_gs[4],orig_gs[5],orig_gs[6],orig_gs[7]);
                fprintf(stderr, "V2-LZSS-IMMED: v2_dest[0..7]: %02X %02X %02X %02X %02X %02X %02X %02X\n",
                    dest[0],dest[1],dest[2],dest[3],dest[4],dest[5],dest[6],dest[7]);
            }
        }
    }
    return result;
}

// Unit-31 wrappers: run v2_read_chunk against a caller buffer and expose the
// v2 side effects the runner compares (ring = shadow FS window, the ds:0x2BB4
// header mirror). v2_fntest_set_data_file_v2 switches the v2 file handle to a
// synthetic fixture (paired with the oracle-side v2_fntest_set_data_file).
extern "C" int v2_fntest_set_data_file_v2(const char* path) {
    if (v2_data_handle) { fclose(v2_data_handle); v2_data_handle = nullptr; }
    v2_data_handle = fopen(path, "rb");
    return v2_data_handle ? 1 : 0;
}
// Unit-32: raw-chunk read (sub_10cd8's file half). hdr10_out = 8-byte table
// entry + plane_size; returns plane_size (0 on failure/0xFFFA).
static uint16_t v2_read_raw_chunk(uint16_t chunk_id, uint8_t* dest, uint32_t max_size,
                                  uint8_t* hdr8_out);
extern "C" uint32_t v2_fntest_call_raw_chunk(uint16_t chunk_id, uint8_t* dest,
                                             uint8_t* hdr10_out) {
    memset(hdr10_out, 0, 10);
    uint16_t ps = v2_read_raw_chunk(chunk_id, dest, 0x40000, hdr10_out);
    *(uint16_t*)(hdr10_out + 8) = ps;
    return ps;
}
extern "C" uint32_t v2_fntest_call_read_chunk(uint16_t chunk_id, uint8_t* dest,
                                              uint8_t* ring_out, uint8_t* hdr10_out) {
    memset(v2_vm_shadow_fs, 0, 0x1000);          // deterministic ring baseline per case
    memset(v2_vm_shadow_ds + DS_CHUNK_HDR, 0, 10);     // header mirror baseline
    uint32_t n = v2_read_chunk(chunk_id, dest, 0x10000);
    memcpy(ring_out, v2_vm_shadow_fs, 0x1000);
    memcpy(hdr10_out, v2_vm_shadow_ds + DS_CHUNK_HDR, 10);
    return n;
}

// sub_10cd8: read raw chunk (no LZSS decompression).
// Reads plane_size (2 bytes) + raw data (plane_size * 4 bytes) from DATA.DAT.
// Returns plane_size. dest receives raw plane data (plane_size * 4 bytes).
static uint16_t v2_read_raw_chunk(uint16_t chunk_id, uint8_t* dest, uint32_t max_size,
                                  uint8_t* hdr8_out = nullptr) {
    if (!v2_data_handle) {
        v2_data_handle = fopen("DATA.DAT", "rb");
        if (!v2_data_handle) return 0;
    }
    if (chunk_id == 0xFFFA) return 0;

    // Read chunk table entry
    uint32_t table_offset = (uint32_t)chunk_id * 4;
    if (fseek(v2_data_handle, table_offset, SEEK_SET)) return 0;

    uint8_t header[8];
    if (fread(header, 8, 1, v2_data_handle) != 1) return 0;
    uint32_t chunk_offset = *(uint32_t*)(header);
    if (hdr8_out) memcpy(hdr8_out, header, 8);

    // Seek to chunk data
    if (fseek(v2_data_handle, chunk_offset, SEEK_SET)) return 0;

    // Read plane_size (2 bytes)
    uint16_t plane_size;
    if (fread(&plane_size, 2, 1, v2_data_handle) != 1) return 0;

    // Read raw plane data (plane_size * 4 bytes)
    uint32_t data_size = (uint32_t)plane_size * 4;
    if (data_size > max_size) data_size = max_size;
    if (fread(dest, 1, data_size, v2_data_handle) != data_size) return 0;

    return plane_size;
}

// v2_load_chunk_10cd8: exact copy of orig sub_10cd8 (read_and_display_raw_chunk).
// Orig flow:
//   1. plane_size = read 2 bytes from DATA.DAT into ds:0x2BBC
//   2. chunk_addr = ds:0x2E77 (chunk segment)
//   3. fread plane_size*4 bytes into raddr(chunk_addr, 0)
//   4. if (display_offset == 0) v2_draw_hud_background(ds, chunk_addr, plane_size)
//      else                     v2_draw_viewport_chunk(chunk_addr, plane_size)
//   5. VGA OUTs + MOVSW (commented in v2)
// Args: ax = chunk_id, di = display_offset (VGA dest)
static void v2_load_chunk_10cd8(uint8_t* shadow, uint16_t ax, uint16_t di) {
    uint16_t chunk_seg = *(uint16_t*)(shadow + DS_SEG_CHUNK);
    uint16_t plane_size = v2_read_raw_chunk(ax, v2_vm_shadow_chunk, V2_CHUNK_SHADOW_SIZE);
    *(uint16_t*)(shadow + DS_DECOMP_SIZE) = plane_size; // ds:0x2BBC = plane_size (mirror orig)
    if (plane_size == 0) return;
    if (di == 0) {
        v2_draw_hud_background(v2_current_ds_val, chunk_seg, plane_size);
    } else {
        v2_draw_viewport_chunk(chunk_seg, plane_size);
    }
    // shadow-VGA: replay the orig 4-plane VGA copy (read_and_display_raw_chunk,
    // seg000 eips 0xD50..0xD8A: OUT plane select + MOV A000:[di+i] ← chunk[p*ps+i]).
    {
        extern void v2_vga_glyph_px(uint32_t addr, uint32_t plane, uint8_t val);
        for (uint32_t p = 0; p < 4; p++)
            for (uint32_t i = 0; i < plane_size; i++)
                v2_vga_glyph_px((uint16_t)(di + i), p,
                                v2_vm_shadow_chunk[(uint32_t)plane_size * p + i]);
    }
}

