// sub_10fe6: write full palette to VGA DAC. Reads 768 bytes from ds:0x8202 —
// the asm HARDCODES the source (0x0FEC: MOV si, 8202h); word_303E0 is only the
// source pointer of the sub_10ffc partial animation bursts, NOT of this full
// upload. (An earlier comment here claimed [word_303E0] — wrong.)
// Original: OUT 0x3C8=0 (start color), REP OUTSB 0x300 bytes to port 0x3C9, then setPalette().
// For v2: palette in shadow DS at 0x8202, applied by render callback. DS write: word_303DE=0.
static void v2_pal_dac_write_10fe6(uint8_t* s) {
    *(uint16_t*)(s + DS_PAL_REQ) = 0; // word_303DE = 0 (palette write complete)
    // Original VGA DAC write:
    // OUT(0x3C8, 0);  // start at color 0
    // REP OUTSB ds:0x8202, 0x300 bytes → port 0x3C9
    // for (i=0; i<256; i++) setPalette(i, ds[0x8202+i*3+0]<<2, ds[0x8202+i*3+1]<<2, ds[0x8202+i*3+2]<<2);
    // v2 shadow DAC (task #22): full upload, source hardcoded ds:0x8202.
    memcpy(v2_dac_shadow, s + DS_PAL_OUT, 768);
}

// sub_10ffc: palette animation (underwater/lava cycling). Processes 8 animation slots (bx=7→0).
// Each slot: check enable flag, copy timer, compute color range, write partial palette to VGA DAC.
// DS writes: [bx+0x258C] = timer copy, word_303DE = 0. VGA: OUT + setPalette for affected ranges.
static void v2_pal_anim_10ffc(uint8_t* s) {
    *(uint16_t*)(s + DS_PAL_REQ) = 0; // word_303DE = 0
    uint16_t pal_base = *(uint16_t*)(s + DS_PAL_SRC_PTR); // word_303E0 = palette data pointer
    for (int16_t bx = 7; bx >= 0; bx--) {
        uint8_t mask = s[(uint16_t)(bx - LUT_BYTE_OR)]; // bit mask from table
        if (!(s[DS_PAL_ANIM_EN] & mask)) continue;          // byte_2AA63: animation enable bits
        if (s[bx + DS_PAL_ANIM_TIMER] != 0) continue;          // timer not zero → skip
        s[bx + DS_PAL_ANIM_TIMER] = s[bx + DS_PAL_ANIM_RELOAD];            // reset timer from reload value
        uint8_t end_color = s[bx + DS_PAL_ANIM_END];
        uint8_t start_color = s[bx + DS_PAL_ANIM_START];
        // Orig 0x1023: MOVZX cx,byte[259C]; SUB cl,[2594] — 8-bit SUB (CH stays 0);
        // JZ next (ZF of the BYTE) / JS loc_1104d (SF = BIT 7 of the byte result).
        // NOT an int16 model: end=0x00,start=0xFF gives diff8=0x01, SF=0 → the
        // POSITIVE path runs with count=2 and DAC index wrapping 0xFF→0x00
        // (unit-34 finding: the old int16 range sent this to the negative path).
        uint8_t diff8 = (uint8_t)(end_color - start_color);
        if (diff8 == 0) continue;
        // Both branches are pure VGA DAC writes (OUT 0x3C8/0x3C9), no DS effects:
        // bit7=0: OUT(0x3C8, start_color); count=diff8+1 (INC cx, ch=0); REP OUTSB
        //         count*3 bytes from ds:[word_303E0 + start_color*3].
        // bit7=1 (loc_1104d): NEG cl → count=(uint8)(start-end)+1; OUT(0x3C8, end);
        //         REP OUTSB count*3 bytes from ds:[word_303E0 + count*3] — orig
        //         quirk: source offset is count*3, NOT end_color*3.
        // v2 shadow DAC (task #22): mirror both bursts from SHADOW data. Source can
        // be 0x7F02 (word_303E0) — NOT 0x8202 — which is why the old "screen =
        // 0x8202 snapshot" display model diverged (V2-PAL-DIVERGE idx 0x71).
        // DAC slot autoincrement wraps 8-bit; (slot*3+i)%768 is byte-exact for it
        // (768 = 256*3 keeps the 3-phase alignment).
        if (!(diff8 & 0x80)) {
            uint16_t count = (uint16_t)diff8 + 1;
            for (uint16_t i = 0; i < count * 3; i++)
                v2_dac_shadow[(start_color * 3 + i) % 768] =
                    s[(uint16_t)(pal_base + start_color * 3 + i)];
        } else {
            uint16_t count = (uint16_t)(uint8_t)(0 - diff8) + 1;
            for (uint16_t i = 0; i < count * 3; i++)
                v2_dac_shadow[(end_color * 3 + i) % 768] =
                    s[(uint16_t)(pal_base + count * 3 + i)];
        }
    }
}

// sub_10fa0: palette fade to black. Blocking render loop bx=0→0x45.
// sub_10f03: palette shading — reads ds:0x7F02 (source palette), writes ds:0x8202 (shaded palette).
// Subtracts shade bytes (ds:0x342-0x347) from each RGB component, clamps to [0, 0x3F].
static void v2_pal_shade_10f03(uint8_t* s) {
    uint8_t r_shade = s[DS_PAL_SHADE_R] | s[DS_PAL_SHADE_R2];
    uint8_t g_shade = s[DS_PAL_SHADE_G] | s[DS_PAL_SHADE_G2];
    uint8_t b_shade = s[DS_PAL_SHADE_B] | s[DS_PAL_SHADE_B2];
    uint8_t* src = s + DS_PAL_SRC;
    uint8_t* dst = s + DS_PAL_OUT;
    for (int i = 0; i < 0x100; i++) {
        int r = src[0] - r_shade; if (r < 0) r = 0; if (r >= 0x40) r = 0x3F; dst[0] = (uint8_t)r;
        int g = src[1] - g_shade; if (g < 0) g = 0; if (g >= 0x40) g = 0x3F; dst[1] = (uint8_t)g;
        int b = src[2] - b_shade; if (b < 0) b = 0; if (b >= 0x40) b = 0x3F; dst[2] = (uint8_t)b;
        src += 3; dst += 3;
    }
}

static void v2_vsync_wait_10130(uint8_t* s); // forward decl
static void v2_pal_fade_seq_10fa0(uint8_t* s) {
    // Original: loop bx from 0 to 0x45 (70 iterations).
    // NOTE: orig seg000 has debug hack "bx = 0x45" (line 3246) that reduces to 1 iteration.
    // v2 MUST match orig behavior.
    for (uint16_t bx = 0x45; bx <= 0x45; bx++) {
        s[DS_PAL_SHADE_R] = (uint8_t)bx; // byte_28822
        s[DS_PAL_SHADE_G] = (uint8_t)bx; // byte_28823
        s[DS_PAL_SHADE_B] = (uint8_t)bx; // byte_28824
        v2_pal_shade_10f03(s);                    // sub_10f03: palette shading → ds:0x8202
        *(uint16_t*)(s + DS_PAL_REQ) = 4;       // word_303DE = 4 (request palette write)
        *(uint16_t*)(s + DS_PAL_SRC_PTR) = DS_PAL_OUT;  // word_303E0 = shaded palette pointer
        // Original: CALL sub_16775; CALL sub_10130
        v2_page_flip_16775(s);                     // sub_16775: page flip DS writes
        v2_vsync_wait_10130(s);                     // sub_10130: vsync + palette dispatch (DS: DEC A39C)
    }
    s[DS_PAL_SHADE_R] = 0;                                                       // MOV byte_28822, 0
    s[DS_PAL_SHADE_G] = 0;                                                       // MOV byte_28823, 0
    s[DS_PAL_SHADE_B] = 0;                                                       // MOV byte_28824, 0
    *(uint16_t*)(s + DS_PAL_SRC_PTR) = DS_PAL_OUT;                                  // MOV word_303E0, 8202h
}

static void v2_pal_correct_10e99(uint8_t* s); // forward decl for v2_save_game_1450b

// sub_1450b (seg000): save game state.
// Original: seg000 lines 9467-9482 (eip 0x450B..0x452F).
// DS writes: ds:0x342 = al<<1, ds:0x343 = si<<1 (byte), ds:0x344 = di<<1 (byte),
//            ds:0x7EFD |= 1, ds:0x7EFE = 4, ds:0x7F00 = 0x8202.
// Then JMP sub_10E99 (palette correction).
static void v2_save_game_1450b(uint8_t* s, uint8_t al, uint16_t si, uint16_t di) {
    s[DS_PAL_SHADE_R] = (uint8_t)(al << 1);                                  // SHL al, 1; MOV ds:342h, al
    s[DS_PAL_SHADE_G] = (uint8_t)((uint8_t)si << 1);                        // SHL al, 1; MOV ds:343h, al
    s[DS_PAL_SHADE_B] = (uint8_t)((uint8_t)di << 1);                        // SHL al, 1; MOV ds:344h, al
    s[DS_PAL_FLAGS] |= 1;                                                 // OR byte ptr ds:7EFDh, 1
    *(uint16_t*)(s + DS_PAL_REQ) = 4;                                   // MOV word ptr ds:7EFEh, 4
    *(uint16_t*)(s + DS_PAL_SRC_PTR) = DS_PAL_OUT;                              // MOV word ptr ds:7F00h, 8202h
    // JMP sub_10E99: palette correction — writes 768 bytes to ds:0x8202
    v2_pal_correct_10e99(s);
}

// ============================================================================
// sub_10130: VGA vsync wait. Original (DOS, eip 0x0130-0x0137):
//   loop: cmp word_3287c, 1; jge loop; retn
// word_3287c was DEC'd by the VGA vertical-retrace interrupt (sub_1797b)
// at ~60Hz, which also dispatched palette writes via off_17974[word_303DE]
// (sub_10fe6 / sub_10ffc / nullsub_1).
//
// Port architecture: no real vsync interrupt — game thread + render thread.
// Previously render thread imitated the interrupt by DEC'ing shadow[0xA39C]
// and dispatching shadow palette async. That raced with trace_compare
// snapshots (taken at op-N moments in respective game threads): if render
// fired between orig snapshot and v2 snapshot, the two saw different DEC
// counts → forced 0xA39C / 0x7EFE into v2_ds_hash_skip.
//
// Fix: render thread no longer touches DS. v2_vsync_wait_10130 (this function)
// sleeps one vsync (~16ms) and then calls v2_render_callback, which is
// the v2 mirror of orig sub_1797b (DEC word_3287c + palette dispatch on
// shadow). This mirrors orig sub_10130 m2c calling sub_1797b on real.
// Each game thread mutates its own DS only — orig writes match orig
// DECs 1:1, v2 mirror writes match v2 mirror DECs 1:1 → snapshots agree
// byte-for-byte. Game pacing stays ~60 FPS because game code calls
// sub_10130 at every page-flip site.
// ============================================================================
extern void v2_render_callback();  // v2 mirror of sub_1797b (defined below)
static void v2_vsync_wait_10130(uint8_t* s) {
    extern bool need_quit;
    // #32 localization probe: entry counter value = deterministic iteration
    // count of this wait (v2_render_callback DECs once per loop pass).
    if (getenv("V2_FLIPTRACE")) {
        static long _wn = 0;
        extern int v2_dbg_pre_vm_iter;
        fprintf(stderr, "V2-WAIT[%ld] f=%d a39c=%04X\n",
                ++_wn, v2_dbg_pre_vm_iter, *(uint16_t*)(s + DS_VSYNC_COUNT));
    }
    {
        // #32 groove trap: always record (see the flip-site note).
        extern int v2_dbg_pre_vm_iter;
        extern void v2_flipring_push(uint8_t tag, uint16_t frame,
                                     uint16_t a39c, uint16_t lv, void* ra);
        v2_flipring_push(2, (uint16_t)v2_dbg_pre_vm_iter,
                         *(uint16_t*)(s + DS_VSYNC_COUNT), 0,
                         __builtin_return_address(0));
    }
    while ((int16_t)*(uint16_t*)(s + DS_VSYNC_COUNT) >= 1) {
        if (need_quit) return;
#ifdef V2_ONLY
        SDL_Delay(16);                // vsync 60Hz pacing for interactive
#elif defined(HEADLESS)
        // headless: no display → spin without pacing (render thread decrements
        // 0xA39C fast). Tiny yield to avoid starving the render thread.
        SDL_Delay(0);
#else
        SDL_Delay(4);                 // default mode: faster verify
#endif
        v2_render_callback();         // mirrors orig sub_10130 → sub_1797b call
    }
}

// Task #37: mirror of the orig INT9 line eip 0x647F-0x6483 —
//   ax = ds:[si-0x7198] (si = scancode*2); word_2876C = ax.
// Fired from the SDL KEYDOWN handler for EVERY key press (typematic repeats
// included — DOS hardware repeat re-sent make codes, and the password
// bytecode polls/clears ds:0x028C per character). The LUT itself is the
// ORIGINAL static table read from DS (letters/digits → ASCII, ENTER/SPACE →
// 0x81, non-character keys → 0), never hardcoded here.
extern "C" void v2_mirror_int9_char(uint8_t dos_scan) {
    uint16_t off = (uint16_t)((uint16_t)(dos_scan * 2) - 0x7198);
    if (v2_vm_shadow_ds) {
        uint16_t val = *(uint16_t*)(v2_vm_shadow_ds + off);
        *(uint16_t*)(v2_vm_shadow_ds + DS_LAST_CHAR) = val;
    }
#ifndef V2_ONLY
    if (v2_m2c_base && v2_current_ds_val) {
        uint8_t* rds = v2_m2c_base + ((uint32_t)v2_current_ds_val << 4);
        *(uint16_t*)(rds + DS_LAST_CHAR) = *(uint16_t*)(rds + off);
    }
#endif
}

// Atomic flag set when shadow DS is initialized — gates v2_render_callback
// (which runs on render thread) from touching uninitialized shadow.
static std::atomic<bool> v2_render_cb_enabled{false};

// sub_10255 (seg000 eip 0x0255-0x02AC): rotate one 3-byte palette entry from
// cur=[si+0x259C] to end=[si+0x2594] inside the table at ds:dx. The entry at
// cur*3+dx is saved to word_309e4/byte_309e6 (ds:0x8504-0x8506), the block
// between them shifts down 3 bytes (REP MOVSB forward, DF=0, cx = end*3 -
// cur*3 wrapped uint16), the saved entry lands at end*3+dx. The byte loop IS
// the REP MOVSB model: 16-bit pointer wrap included, so orig-UB inputs
// (end < cur → huge wrapped count) replicate exactly too.
static void v2_pal_rotate_fwd_10255(uint8_t* s, uint16_t si, uint16_t dx) {
    uint8_t cur = s[(uint16_t)(si + DS_PAL_ANIM_END)];                  // AL = [si+259Ch]
    uint8_t endi = s[(uint16_t)(si + DS_PAL_ANIM_START)];                 // AL = [si+2594h]
    uint16_t di = (uint16_t)((uint16_t)((uint16_t)cur * 3) + dx); // ax=cur*3; di=ax+dx
    s[DS_BYTE_SAVE_0] = s[di];                                         // byte ptr word_309E4   = [di]
    s[DS_BYTE_SAVE_1] = s[(uint16_t)(di + 1)];                         // byte ptr word_309E4+1 = [di+1]
    s[DS_BYTE_SAVE_2] = s[(uint16_t)(di + 2)];                         // byte_309E6            = [di+2]
    uint16_t cx = (uint16_t)((uint16_t)((uint16_t)endi * 3 + dx) - di); // cx = end*3+dx - di
    uint16_t src = (uint16_t)(di + 3);                         // si = di+3
    while (cx--) { s[di] = s[src]; di++; src++; }              // REP MOVSB (DF=0)
    s[di] = s[DS_BYTE_SAVE_0];                                         // [di]   = word_309E4 lo
    s[(uint16_t)(di + 1)] = s[DS_BYTE_SAVE_1];                         // [di+1] = word_309E4 hi
    s[(uint16_t)(di + 2)] = s[DS_BYTE_SAVE_2];                         // [di+2] = byte_309E6
}

// sub_1020f (seg000 eip 0x020F-0x0254): the inverse rotate — entry at
// cur*3+dx saved (WORD read [di] → word_309e4, byte [di+2] → byte_309e6),
// block shifts up 3 bytes backwards (STD; REP MOVSB with cx = (cur-end)*3
// wrapped, si=di-1, di=di+2), then the saved entry is written at [di-2]
// (WORD) / [di] (byte) where di ended at end*3+dx+2.
static void v2_pal_rotate_back_1020f(uint8_t* s, uint16_t si, uint16_t dx) {
    uint8_t cur = s[(uint16_t)(si + DS_PAL_ANIM_END)];                  // movzx ax, [si+259Ch]
    uint8_t endi = s[(uint16_t)(si + DS_PAL_ANIM_START)];                 // movzx ax, [si+2594h]
    uint16_t di0 = (uint16_t)((uint16_t)((uint16_t)cur * 3) + dx); // di=cur*3+dx
    s[DS_BYTE_SAVE_0] = s[di0];                                        // word_309E4 = [di] (WORD, LE)
    s[DS_BYTE_SAVE_1] = s[(uint16_t)(di0 + 1)];
    s[DS_BYTE_SAVE_2] = s[(uint16_t)(di0 + 2)];                        // byte_309E6 = [di+2]
    uint16_t cx = (uint16_t)((uint16_t)((uint16_t)cur - (uint16_t)endi) * 3); // cx=(cur-end)*3
    uint16_t sp = (uint16_t)(di0 - 1);                         // si = di-1
    uint16_t dp = (uint16_t)(di0 + 2);                         // di = di+2
    while (cx--) { s[dp] = s[sp]; dp--; sp--; }                // STD; REP MOVSB; CLD
    s[(uint16_t)(dp - 2)] = s[DS_BYTE_SAVE_0];                         // [di-2] = word_309E4 (WORD, LE)
    s[(uint16_t)(dp - 1)] = s[DS_BYTE_SAVE_1];
    s[dp] = s[DS_BYTE_SAVE_2];                                         // [di] = byte_309E6
}

// sub_101be (seg000): Palette cycling for UI elements.
// Verified with seg000 lines 2086-2148.
// Iterates 8 palette channels (si=7 down to 0).
// For each: checks mask (byte_2AA63 at ds:0x2583), counter at [si+0x258C].
// If counter reaches 0: rotates 3-byte palette entries (sub_10255 for cur<end:
// block shifts down, saved entry lands at end; sub_1020f for cur>end: the reverse).
// DS writes: DEC [si+0x258C], word_303DE=2, palette buffer rotations at ds:0x8202+ area.
static void v2_pal_ui_cycle_101be(uint8_t* s) {
    static int _dbg_calls = 0, _dbg_rotations = 0;
    _dbg_calls++;
    // ROOT-CAUSE diag: shadow counters + palette state at slot 1 cur_idx.
    if (s[DS_PAL_ANIM_EN] != 0) {
        static int _printed = 0;
        if (_printed < 300) {
            _printed++;
            uint8_t cur_i = s[1 + DS_PAL_ANIM_END];
            uint8_t end_i = s[1 + DS_PAL_ANIM_START];
            uint16_t addr_82 = (uint16_t)cur_i * 3 + DS_PAL_OUT;
            uint16_t addr_7f = (uint16_t)cur_i * 3 + DS_PAL_SRC;
            fprintf(stderr, "V2-101BE-CALL[#%d] 2583=%02X cnt[0..7]=%02X %02X %02X %02X %02X %02X %02X %02X | slot1 cur=%02X end=%02X r82[%04X]=%02X%02X%02X r7f[%04X]=%02X%02X%02X scratch=%02X%02X%02X\n",
                _dbg_calls, s[DS_PAL_ANIM_EN],
                s[DS_PAL_ANIM_TIMER], s[DS_PAL_ANIM_TIMER_1], s[DS_PAL_ANIM_TIMER_2], s[DS_PAL_ANIM_TIMER_3],
                s[DS_PAL_ANIM_TIMER_4], s[DS_PAL_ANIM_TIMER_5], s[DS_PAL_ANIM_TIMER_6], s[DS_PAL_ANIM_TIMER_7],
                cur_i, end_i,
                addr_82, s[addr_82], s[addr_82+1], s[addr_82+2],
                addr_7f, s[addr_7f], s[addr_7f+1], s[addr_7f+2],
                s[DS_BYTE_SAVE_0], s[DS_BYTE_SAVE_1], s[DS_BYTE_SAVE_2]);
        }
    }
    if (s[DS_PAL_ANIM_EN] == 0) {                                           // TEST byte_2AA63, 0FFh; JZ loc_1020b
        if (_dbg_calls % 60 == 1) fprintf(stderr, "V2-101BE[%d]: EARLY-EXIT 2583=0\n", _dbg_calls);
        return;                                                      // early exit — NO word_303DE write
    }
    for (int16_t si = 7; si >= 0; si--) {                           // si=7; DEC si; JNS
        uint8_t mask = s[DS_PAL_ANIM_EN];                                    // byte_2AA63
        if (!(s[(uint16_t)(si - LUT_BYTE_OR)] & mask)) continue;        // TEST [si-6C44h], al; JZ
        if (s[si + DS_PAL_ANIM_TIMER] == 0) continue;                         // TEST [si+258Ch]; JZ
        s[si + DS_PAL_ANIM_TIMER]--;                                           // DEC [si+258Ch]
        if (s[si + DS_PAL_ANIM_TIMER] != 0) continue;                         // JNZ skip
        // Counter reached 0: rotate palette entries
        _dbg_rotations++;
        if (_dbg_rotations <= 20) {
            uint8_t cur_i = s[si + DS_PAL_ANIM_END], end_i = s[si + DS_PAL_ANIM_START];
            uint16_t addr_82 = cur_i * 3 + DS_PAL_OUT;
            uint16_t addr_7f = cur_i * 3 + DS_PAL_SRC;
            fprintf(stderr, "V2-101BE-ROT[%d call=%d si=%d cur=%02X end=%02X path=%s | r82[%04X]=%02X%02X%02X r7f[%04X]=%02X%02X%02X scratch_before=%02X%02X%02X]\n",
                _dbg_rotations, _dbg_calls, si, cur_i, end_i,
                (cur_i < end_i) ? "10255" : "1020F",
                addr_82, s[addr_82], s[addr_82+1], s[addr_82+2],
                addr_7f, s[addr_7f], s[addr_7f+1], s[addr_7f+2],
                s[DS_BYTE_SAVE_0], s[DS_BYTE_SAVE_1], s[DS_BYTE_SAVE_2]);
        }
        uint8_t cur_idx = s[si + DS_PAL_ANIM_END];                          // [si+259Ch] = current
        uint8_t end_idx = s[si + DS_PAL_ANIM_START];                          // [si+2594h] = end
        // word_309e4 is at linear 0x309E4 = ds:0x8504 (NOT 0x7944).
        if (cur_idx < end_idx) {
            // orig: mov dx,8202h; call sub_10255; mov dx,7F02h; call sub_10255
            v2_pal_rotate_fwd_10255(s, (uint16_t)si, DS_PAL_OUT);
            v2_pal_rotate_fwd_10255(s, (uint16_t)si, DS_PAL_SRC);
        } else {
            // orig: mov dx,8202h; call sub_1020F; mov dx,7F02h; call sub_1020F
            v2_pal_rotate_back_1020f(s, (uint16_t)si, DS_PAL_OUT);
            v2_pal_rotate_back_1020f(s, (uint16_t)si, DS_PAL_SRC);
        }
    }
    *(uint16_t*)(s + DS_PAL_REQ) = 2;                                  // word_303DE = 2
}

// sub_108c8 (seg000): Sound state toggle + cleanup.
// Verified with seg000 lines 2894-2953.
// DS writes: byte_3166B (ds:0x918B), word_287E4 (ds:0x0304), sound handles (ds:0x990E-0x9914),
//            byte_3167E (ds:0x919E), word_287E2 (ds:0x0302).
static void v2_audio_tick_108c8(uint8_t* s) {
    uint16_t ax = *(uint16_t*)(s + DS_MUSIC_MUTE) & *(uint16_t*)(s + DS_SFX_MUTE);  // word_287E2 & word_287E4
    if (ax & 0x8000) return;                                              // TEST ax, 8000h; JNZ ret
    V2_WRITE_91A4_SHAD(sdl_spec_get(DS_KEY_ALT), "v2:sub_108c8");
    s[DS_SPEC_KEY_S] = sdl_spec_get(0x918B);  // SDL S — exact orig INT9
    if (s[DS_KEY_ALT] != 1) return;        // CMP byte_31684, 1; JNZ ret
    if (s[DS_SPEC_KEY_S] == 1) {              // CMP byte_3166B, 1; JNZ skip
        s[DS_SPEC_KEY_S] = 0;                                                   // MOV byte_3166B, 0
        s[DS_SFX_MUTE] ^= 1;                                                  // XOR byte ptr word_287E4, 1
        if (s[DS_SFX_MUTE] != 0) {                                           // JZ skips stop → do stop when nonzero
            // Mute toggled ON: stop SFX channels via SDL handles.
            for (uint16_t si = 2; si < 0x0A; si += 2) {
                uint16_t h_off = (uint16_t)(si - 0x66F4);
                uint16_t handle = *(uint16_t*)(s + h_off);
                if (handle != 0xFFFF) {
                    v2_pool.stop_xmidi(handle);  // v2_pool — independent from orig
                    *(uint16_t*)(s + h_off) = 0xFFFF;                    // clear handle
                    *(uint16_t*)(s + (uint16_t)(si - 0x66EA)) = 0xFFFF; // clear sequence
                }
            }
        }
    }
    // loc_10935: music toggle
    s[DS_SPEC_KEY_M] = sdl_spec_get(0x919E);  // SDL M — exact orig INT9
    if (s[DS_SPEC_KEY_M] != 1) return;        // CMP byte_3167E, 1; JNZ ret
    s[DS_SPEC_KEY_M] = 0;                                                       // MOV byte_3167E, 0
    s[DS_MUSIC_MUTE] ^= 1;                                                      // XOR byte ptr word_287E2, 1
    if (s[DS_MUSIC_MUTE] != 0) {                                                 // JNZ loc_10959 (music STOP path)
        // loc_10959: music OFF. Skip if bit 15 set.
        if (!(*(uint16_t*)(s + DS_MUSIC_MUTE) & 0x8000)) {
            uint16_t mh = v2_pool.get_music_handle();
            if (mh != 0) v2_pool.stop_xmidi(mh);  // v2_pool — independent from orig
        }
    } else {                                                              // music ON path
        // sub_176BD(si=0, ax=0, bx=word_2B34B): play music with sequence from ds:0x2E6B
        // (orig fall-through path at eip 0x947). v2_music_play_176bd_v2 handles SDL replacement
        // and updates v2_id_music + dontstop.
        uint16_t bx_seg = *(uint16_t*)(s + DS_SEG_SOUND);  // word_2B34B at ds:0x2E6B
        fx::play_music(s, bx_seg);
    }
}

// sub_1686f (seg000): VGA mode restore on exit. Verified with seg000 lines 15588-15597.
