            // sub_14590 (only from loc_10469 path)
            shadow[DS_PAL_SHADE_R] = 0; shadow[DS_PAL_SHADE_G] = 0; shadow[DS_PAL_SHADE_B] = 0;
            shadow[DS_PAL_FLAGS] &= 0xFE;
