                                        uint16_t saved = found_di;
                                        uint16_t di3 = *(uint16_t*)(shadow + DS_HUD_DRAW_DI);
                                        uint16_t ax3 = *(uint16_t*)(shadow + di3 + (DS_HUD_SEL));
                                        di3 = ((di3 << 1) + ax3) << 1;
                                        uint16_t si_v = saved >> 1;
                                        di3 = (di3 >> 2) & 0xFFFE;
                                        *(uint16_t*)(shadow + di3 + (DS_HUD_SEL)) = si_v;
