                                *(uint16_t*)(shadow + DS_HUD_DRAW_DI) = di_b; // word_28901
                                uint16_t ax_b = *(uint16_t*)(shadow + di_b + (DS_HUD_SEL));
                                di_b = ((di_b << 1) + ax_b) << 1;
