// Viewport movers — called from v2_game_loop_post_vm (sub_1064b camera follow)
static void v2_scroll_left_17496(uint8_t* s, int16_t si_speed) {
    // Scroll left: ds:0x44 = max(ds:0x44 - si_speed, 0)
    if (*(uint16_t*)(s + DS_SCROLL_LOCK_X)) return; // lock flag
    int16_t ax = (int16_t)*(uint16_t*)(s + DS_VIEWPORT_X);
    ax -= si_speed;
    if (ax < 0) ax = 0;
    int16_t dx = (int16_t)*(uint16_t*)(s + DS_VIEWPORT_X) - ax;
    *(uint16_t*)(s + DS_VIEWPORT_X) = (uint16_t)ax;
    *(uint16_t*)(s + DS_SCROLL_COL) = (uint16_t)ax >> 3;
    *(uint16_t*)(s + DS_SCROLL_DELTA_X) = (uint16_t)dx;
}

static void v2_scroll_right_1746c(uint8_t* s, int16_t si_speed) {
    // Scroll right: ds:0x44 = min(ds:0x44 + si_speed, ds:0x25A4)
    if (*(uint16_t*)(s + DS_SCROLL_LOCK_X)) return;
    int16_t ax = (int16_t)*(uint16_t*)(s + DS_VIEWPORT_X);
    ax += si_speed;
    uint16_t limit = *(uint16_t*)(s + DS_SCROLL_LIMIT_X);
    if ((uint16_t)ax >= limit) ax = (int16_t)limit;
    int16_t dx = ax - (int16_t)*(uint16_t*)(s + DS_VIEWPORT_X);
    *(uint16_t*)(s + DS_VIEWPORT_X) = (uint16_t)ax;
    *(uint16_t*)(s + DS_SCROLL_COL) = (uint16_t)ax >> 3;
    *(uint16_t*)(s + DS_SCROLL_DELTA_X) = (uint16_t)dx;
}

static void v2_scroll_up_174e9(uint8_t* s, int16_t si_speed) {
    // Scroll up: ds:0x46 = max(ds:0x46 - si_speed, 0)
    if (*(uint16_t*)(s + DS_SCROLL_LOCK_Y)) return;
    int16_t ax = (int16_t)*(uint16_t*)(s + DS_VIEWPORT_Y);
    ax -= si_speed;
    if (ax < 0) ax = 0;
    int16_t dx = (int16_t)*(uint16_t*)(s + DS_VIEWPORT_Y) - ax;
    *(uint16_t*)(s + DS_VIEWPORT_Y) = (uint16_t)ax;
    *(uint16_t*)(s + DS_SCROLL_ROW) = (uint16_t)ax >> 3;
    *(uint16_t*)(s + DS_SCROLL_DELTA_Y) = (uint16_t)dx;
}

static void v2_scroll_down_174bf(uint8_t* s, int16_t si_speed) {
    // Scroll down: ds:0x46 = min(ds:0x46 + si_speed, ds:0x25A6)
    if (*(uint16_t*)(s + DS_SCROLL_LOCK_Y)) return;
    int16_t ax = (int16_t)*(uint16_t*)(s + DS_VIEWPORT_Y);
    ax += si_speed;
    uint16_t limit = *(uint16_t*)(s + DS_SCROLL_LIMIT_Y);
    if ((uint16_t)ax >= limit) ax = (int16_t)limit;
    int16_t dx = ax - (int16_t)*(uint16_t*)(s + DS_VIEWPORT_Y);
    *(uint16_t*)(s + DS_VIEWPORT_Y) = (uint16_t)ax;
    *(uint16_t*)(s + DS_SCROLL_ROW) = (uint16_t)ax >> 3;
    *(uint16_t*)(s + DS_SCROLL_DELTA_Y) = (uint16_t)dx;
}

// sub_10704 / sub_10753 (orig eips 0x704-0x752 / 0x753-0x7A1): apply the
// pending per-axis scroll amounts through a speed table. X: 0x3D8 (left) wins
// over 0x3DA (right); Y: 0x3DE (up) wins over 0x3DC (down). Speed lookup =
// ds:[amount*2 + table] (0x2B82 for sub_10704, 0x2B80 for sub_10753).
// Consolidated from three inline lambda copies (sub_115d2 zone x2 call sites,
// POST_FLIP1 zone, POST_FLIP2 zone); covered by FNSELFTEST.
static void v2_scroll_apply(uint8_t* s, uint16_t table_off) {
    uint16_t v = *(uint16_t*)(s + DS_SCROLL_AMT_LEFT);
    if (v != 0) v2_scroll_left_17496(s, *(int16_t*)(s + (uint16_t)(v * 2 + table_off)));
    else {
        v = *(uint16_t*)(s + DS_SCROLL_AMT_RIGHT);
        if (v != 0) v2_scroll_right_1746c(s, *(int16_t*)(s + (uint16_t)(v * 2 + table_off)));
    }
    v = *(uint16_t*)(s + DS_SCROLL_AMT_UP);
    if (v != 0) v2_scroll_up_174e9(s, *(int16_t*)(s + (uint16_t)(v * 2 + table_off)));
    else {
        v = *(uint16_t*)(s + DS_SCROLL_AMT_DOWN);
        if (v != 0) v2_scroll_down_174bf(s, *(int16_t*)(s + (uint16_t)(v * 2 + table_off)));
    }
}
static void v2_scroll_step1_10704(uint8_t* s) { v2_scroll_apply(s, DS_SCROLL_STEP1_TBL); }
static void v2_scroll_step2_10753(uint8_t* s) { v2_scroll_apply(s, DS_SCROLL_STEP2_TBL); }

// sub_1064b (orig eips 0x64B-0x702): camera follow — compute per-axis scroll
// amounts toward the active viking and move the viewport via the speed table
// at ds:0x2B84.
// FLAG MODEL (same class FNSELFTEST caught in sub_13c0c): every branch here
// is ADD/SUB (16-bit wrap, flags dropped) then SUB + JLE — i.e. the SIGNED
// COMPARE of the last SUB's OPERANDS, while the stored amount is the wrapped
// difference itself. The old code compared the sign of the difference, which
// diverges when the subtraction overflows.
static void v2_camera_follow_1064b(uint8_t* s) {
    *(uint16_t*)(s + DS_SCROLL_DELTA_X) = 0; // word_2882E
    *(uint16_t*)(s + DS_SCROLL_DELTA_Y) = 0; // word_28830
    *(uint16_t*)(s + DS_SCROLL_AMT_LEFT) = 0; // word_288B8
    *(uint16_t*)(s + DS_SCROLL_AMT_RIGHT) = 0; // word_288BA
    *(uint16_t*)(s + DS_SCROLL_AMT_UP) = 0; // word_288BE
    *(uint16_t*)(s + DS_SCROLL_AMT_DOWN) = 0; // word_288BC

    uint16_t di = *(uint16_t*)(s + DS_ACTIVE_VIKING); // active viking

    // X (orig eips 0x66F-0x6B8)
    {
        uint16_t sum = (uint16_t)(*(uint16_t*)(s + DS_VIEWPORT_X) + 0x90);
        uint16_t obj = ObjMem{s, di}.u16(OBJ_WORLD_X);
        if ((int16_t)sum > (int16_t)obj) {                 // JLE not taken
            uint16_t amt = (uint16_t)(sum - obj);          // wrapped SUB value
            if ((int16_t)amt >= (int16_t)0x10) amt = 0x10; // CMP si,10h; JL
            *(uint16_t*)(s + DS_SCROLL_AMT_LEFT) = amt;
            v2_scroll_left_17496(s, *(int16_t*)(s + (uint16_t)(amt * 2 + DS_SCROLL_AMT_TBL)));
        } else {                                           // loc_10698
            uint16_t diff = (uint16_t)(obj - *(uint16_t*)(s + DS_VIEWPORT_X));
            if ((int16_t)diff > (int16_t)0xB0) {           // SUB si,0B0h; JLE
                uint16_t amt = (uint16_t)(diff - 0xB0);
                if ((int16_t)amt >= (int16_t)0x10) amt = 0x10;
                *(uint16_t*)(s + DS_SCROLL_AMT_RIGHT) = amt;
                v2_scroll_right_1746c(s, *(int16_t*)(s + (uint16_t)(amt * 2 + DS_SCROLL_AMT_TBL)));
            }
        }
    }
    // Y (orig eips 0x6BB-0x702; up/down are tail-jumps into the movers)
    {
        uint16_t sum = (uint16_t)(*(uint16_t*)(s + DS_VIEWPORT_Y) + 0x50);
        uint16_t obj = ObjMem{s, di}.u16(OBJ_WORLD_Y);
        if ((int16_t)sum > (int16_t)obj) {
            uint16_t amt = (uint16_t)(sum - obj);
            if ((int16_t)amt >= (int16_t)0x10) amt = 0x10;
            *(uint16_t*)(s + DS_SCROLL_AMT_UP) = amt;
            v2_scroll_up_174e9(s, *(int16_t*)(s + (uint16_t)(amt * 2 + DS_SCROLL_AMT_TBL)));
        } else {
            uint16_t diff = (uint16_t)(obj - *(uint16_t*)(s + DS_VIEWPORT_Y));
            if ((int16_t)diff > (int16_t)0x60) {
                uint16_t amt = (uint16_t)(diff - 0x60);
                if ((int16_t)amt >= (int16_t)0x10) amt = 0x10;
                *(uint16_t*)(s + DS_SCROLL_AMT_DOWN) = amt;
                v2_scroll_down_174bf(s, *(int16_t*)(s + (uint16_t)(amt * 2 + DS_SCROLL_AMT_TBL)));
            }
        }
    }
}

// Standalone sub_15fbe for use in game loop (before V2VM struct is defined).
// sub_15fbe: object search with y_check = ds:[obj_di + 0x150D] + 1.
// Returns true (carry set) if matching object found.
static bool v2_gameloop_obj_search_down_15fbe(uint8_t* ds, uint16_t filter_si, uint16_t obj_di) {
    uint16_t y_check = *(uint16_t*)(ds + obj_di + OBJ_BBOX_Y1) + 1;
    *(uint16_t*)(ds + 0x34) = filter_si;
    *(uint16_t*)(ds + 0x36) = y_check;
    uint16_t table_end = *(uint16_t*)(ds + DS_OBJ_COUNT);
    for (uint16_t si = 0; si == 0 || (int16_t)si < (int16_t)table_end; si += 2) {   // orig do-while: first slot unconditional (ADD si,2; CMP si,[372]; JL)
        if (*(uint16_t*)(ds + si + OBJ_CODE_SEG) == 0) continue;
        if (si == *(uint16_t*)(ds + DS_CUR_OBJ)) continue;
        *(uint16_t*)(ds + 0x3A) = si;
        uint8_t obj_type = (uint8_t)*(uint16_t*)(ds + si + OBJ_TYPE_ID);
        uint16_t flt = filter_si;
        bool match = false;
        while (true) {
            uint8_t fval = *(uint8_t*)(ds + (uint16_t)(flt - LUT_SCAN_FILTER));
            if (obj_type < fval) break;
            if (obj_type == fval) { match = true; break; }
            flt++;
        }
        if (!match) continue;
        if ((int16_t)y_check < (int16_t)*(uint16_t*)(ds + si + OBJ_BBOX_Y0)) continue;
        if ((int16_t)(y_check - 1) >= (int16_t)*(uint16_t*)(ds + si + OBJ_BBOX_Y1)) continue;
        if ((int16_t)*(uint16_t*)(ds + obj_di + OBJ_BBOX_X1) < (int16_t)*(uint16_t*)(ds + si + OBJ_BBOX_X0)) continue;
        if ((int16_t)*(uint16_t*)(ds + si + OBJ_BBOX_X1) < (int16_t)*(uint16_t*)(ds + obj_di + OBJ_BBOX_X0)) continue;
        // orig eip 0x601C re-reads [si+0x17DD] as full WORD for ds:0x3B2 (NOT the
        // byte-truncated obj_type used for filter scan). High byte preserved.
        *(uint16_t*)(ds + 0x3B2) = *(uint16_t*)(ds + si + OBJ_TYPE_ID);
        *(uint16_t*)(ds + 0x3B4) = si;
        return true;
    }
    return false;
}

// Generic per-phase divergence trap.
//   shadow: v2 shadow DS to compare against v2_vm_real_ds_ptr
//   label : checkpoint name (printed in output)
//   watch : array of DS word addresses to compare (uint16_t reads)
//   n     : length of watch
//   found : caller-owned bool[n], set to true once that address has fired (one-shot per address)
// Prints "V2-DIVERGE[label]: addr=... real=... shadow=..." on first divergence per address.
// Caller controls scope (per-phase, per-frame, etc) by where they call it.
static void v2_phase_diverge_trap(uint8_t* shadow, const char* label,
                                   const uint16_t* watch, size_t n, bool* found) {
    if (!v2_vm_real_ds_ptr) return;
    uint8_t* r = v2_vm_real_ds_ptr;
    for (size_t k = 0; k < n; k++) {
        if (found[k]) continue;
        uint16_t rv = *(uint16_t*)(r + watch[k]);
        uint16_t sv = *(uint16_t*)(shadow + watch[k]);
        if (rv != sv) {
            found[k] = true;
            fprintf(stderr, "V2-DIVERGE[%s]: addr=0x%04X real=%04X shadow=%04X\n",
                label, watch[k], rv, sv);
        }
    }
}

// Per-sub-function DS hash + byte snapshots from orig main thread. orig records
// hash AND full DS bytes AFTER each sub_1386b/1625d/15546/13916/1064b on real_ds.
// v2 phase_post_vm compares its shadow hash AFTER the matching v2 sub-function
// (v2_postvm_check_hash). On hash mismatch dumps timepoint-aligned byte diffs.
// PSNAP MAIN_AFTER_* indices (17..21) provide byte-level coverage at same
// boundaries via watch list; hash check is catch-all safety net for non-watched.
//
// Index → orig sub:
//   0: sub_1386b (gravity / velocity apply)
//   1: sub_1625d (ground detection / Y snap)
//   2: sub_15546 (collision detection VM)
//   3: sub_13916 (collision resolution)
//   4: sub_1064b (camera follow)
uint32_t v2_orig_post_vm_ds_hash[5] = {0,0,0,0,0};
static uint8_t v2_orig_post_vm_ds_bytes[5][0x10000];
static bool    v2_orig_post_vm_ds_valid[5] = {0};
int v2_orig_post_vm_frame = 0; // bumps on each idx=0 record (once per game frame)
static uint32_t v2_ds_hash(uint8_t* ds); // forward; defined later in this file
void v2_record_orig_post_vm_hash(int idx) {
    if (idx < 0 || idx >= 5) return;
    if (!v2_vm_real_ds_ptr) return;
    if (idx == 0) v2_orig_post_vm_frame++;
    v2_orig_post_vm_ds_hash[idx] = v2_ds_hash(v2_vm_real_ds_ptr);
    memcpy(v2_orig_post_vm_ds_bytes[idx], v2_vm_real_ds_ptr, 0x10000);
    v2_orig_post_vm_ds_valid[idx] = true;
}
// Invalidate post-VM snapshots taken during orig main loop. Called from v2_load_level_11080
// (level transition) so v2_postvm_check_hash doesn't fire false positives from
// previous frame's main loop snapshot vs v2's sub_115d2 internal state.
void v2_invalidate_postvm_snaps() {
    for (int i = 0; i < 5; i++) v2_orig_post_vm_ds_valid[i] = false;
}

// ============================================================================
// Universal phase snapshot infrastructure (extended verify).
// Captures orig DS at well-defined phase boundaries (FRAME_BEGIN, PRE_VM_END,
// VM_END, POST_VM_END, RENDER1/2/3_END, POST_FLIP1/2/3_END). v2 compares its
// shadow against the corresponding snapshot at its phase entry. On first
// divergence in any watched address, dumps phase name + diff list + main VM
// trace + collision ring → bisects exactly which phase introduced drift.
// ============================================================================
// V2PhaseSnapIdx enum forward-declared at top of file (line ~611).
static const char* v2_psnap_names[V2_PSNAP_COUNT] = {
    "FRAME_BEGIN", "PRE_VM_END", "VM_END", "POST_VM_END",
    "RENDER1_END", "POST_FLIP1_END", "RENDER2_END", "POST_FLIP2_END",
    "RENDER3_END", "POST_FLIP3_END",
    "T_SF1_VM_END", "T_SF1_POSTVM_END", "T_SF1_PF1_END", "T_SF1_PF2_END",
    "T_SF2_PF_END", "T_SF3_PF_END", "T_SF4_END",
    "MAIN_AFTER_1386B", "MAIN_AFTER_1625D", "MAIN_AFTER_15546",
    "MAIN_AFTER_13916", "MAIN_AFTER_1064B"
};
static uint8_t v2_psnap_ds[V2_PSNAP_COUNT][0x10000];
static bool    v2_psnap_valid[V2_PSNAP_COUNT] = {0};
static int     v2_psnap_frame[V2_PSNAP_COUNT] = {0};

// Variant D: render thread patches all stored phase snapshots in lockstep with
// real+shadow word_30bbe updates. Maintains verify consistency without
// excluding 0x86DE/0x86DC from snapshot model. Called from v2_shadow_input_or/
// v2_shadow_input_and_not (defined near top of file).
//
// Race notes:
// - snapshot memcpy in v2_record_orig_phase_snap: large copy (~64KB). If render
//   thread patches during memcpy, snapshot may have inconsistent 0x86DE byte.
//   Acceptable because next render write will re-patch and verify only compares
//   the watched addresses (0x86DC/0x86DE) which we atomic-or.
// - Per-snap atomic ensures no torn write on the 16-bit value.
static void v2_patch_all_snaps_input(uint16_t bit, bool press) {
    for (int i = 0; i < V2_PSNAP_COUNT; i++) {
        if (!v2_psnap_valid[i]) continue;
        uint16_t* p_30bbe = reinterpret_cast<uint16_t*>(&v2_psnap_ds[i][0x86DE]);
        if (press) __atomic_or_fetch(p_30bbe, bit, __ATOMIC_RELAXED);
        else       __atomic_and_fetch(p_30bbe, (uint16_t)~bit, __ATOMIC_RELAXED);
    }
}

