// 0x10 (sub_14327): Destroy object via sub_13c93 + exit VM. 0 bytes consumed.
// sub_14327: di = ds:0x42; call sub_13c93; si = ds:0x42; POP ax; RETN
// POP ax + RETN = exit opcode loop (skip caller's return address)
// sub_13c93 (seg000 eips 0x3C93..0x3D2F): despawn object — clear sub-sprite
// slots (DO-WHILE), unlink 0x1805/0x182D pair, kill code_seg/anim PC, shrink
// ds:0x372 by the JS-terminated backward scan, then the 0x16C5+flag-0x100
// re-spawn tail (sub_139ef viewport bounds + sub_13ae0 table probe).
static void v2_despawn_13c93(V2VM& vm, uint16_t di) {
    // === sub_13c93 logic ===
    // 1. Clear all sub-sprites if 0x1AD5 != 0. Orig loop loc_13CA2 is a
    // DO-WHILE (body first, CMP si,ax / JL at end) — at least one iteration.
    if (ObjRef{vm, di}.u16(OBJ_SUB_COUNT) != 0) {
        uint16_t ax = ObjRef{vm, di}.u16(OBJ_SUB_END);
        uint16_t si = ObjRef{vm, di}.u16(OBJ_SUB_SLOT);
        do {
            ObjRef sub{vm, si};                          // sub-sprite slot (cursor)
            sub.w16(OBJ_SPRITE_FLAGS, 0);       // clear flags
            sub.w16(OBJ_DIRTY_MODE, 0x400);  // set dirty = 0x400
            si += 2;
        } while ((int16_t)si < (int16_t)ax);              // CMP si,ax / JL
    }

    // 2. Unlink from linked list (0x1805 = prev, 0x182D = next)
    uint16_t prev = ObjRef{vm, di}.u16(OBJ_PARENT);
    if (prev != 0xFFFF) {
        ObjRef{vm, prev}.w16(OBJ_CHILD, 0xFFFF);
    }
    uint16_t next = ObjRef{vm, di}.u16(OBJ_CHILD);
    if (next != 0xFFFF) {
        ObjRef{vm, next}.w16(OBJ_PARENT, 0xFFFF);
    }

    // 3. Clear object: code_seg=0, anim_data=0xFFFF
    ObjRef{vm, di}.w16(OBJ_CODE_SEG, 0);
    ObjRef{vm, di}.w16(OBJ_ANIM_PC, 0xFFFF);

    // 4. Adjust ds:0x372 (max active object index)
    // if di+2 == ds:0x372, scan backwards to find new max
    uint16_t di_plus2 = di + 2;
    if (vm.ds_read(DS_OBJ_COUNT) == di_plus2) {
        uint16_t scan = di_plus2;
        while (true) {
            scan -= 2;
            if ((int16_t)scan < 0) break;
            if (ObjRef{vm, scan}.u16(OBJ_CODE_SEG) != 0) break;
        }
        vm.ds_write(DS_OBJ_COUNT, scan + 2);
    }

    // 5. Respawn tail (orig eips 0x3cfd..0x3d2e): [16C5]==FFFF -> ret;
    // TEST [1585],0x100 -> ret; else full viewport bounds (sub_139EF), then
    // sub_13AE0 for THIS spawn index (di = idx*0x0E) under [42]=FFFF.
    if (ObjRef{vm, di}.u16(OBJ_ANIM_SUB) != 0xFFFF) {              // 0x3cfd
        if (ObjRef{vm, di}.u16(OBJ_FLAGS) & 0x100) {               // 0x3d04 TEST
            uint8_t* s = vm.shadow;
            v2_viewport_bounds_139ef(s);                           // 0x3d0d CALL sub_139EF
            uint16_t spawn_idx = ObjRef{vm, di}.u16(OBJ_ANIM_SUB); // 0x3d10 si=[16C5]
            uint16_t di_off = (uint16_t)(spawn_idx * 0x0E);        // 0x3d14 MUL 0Eh
            uint16_t save_42 = *(uint16_t*)(s + DS_CUR_OBJ);       // 0x3d1d PUSH [42]
            *(uint16_t*)(s + DS_CUR_OBJ) = 0xFFFF;                 // 0x3d21
            v2_spawn_visible_entry_13ae0(s, spawn_idx, di_off);    // 0x3d27 CALL sub_13AE0
            *(uint16_t*)(s + DS_CUR_OBJ) = save_42;                // 0x3d2a POP [42]
        }
    }
}

static void v2_vm_op_10(V2VM& vm) {
    uint16_t di = vm.global_r(DS_CUR_OBJ);
    // orig exit regs: di=[0x42] (sub_13c93 is PUSH/POP di-balanced),
    // si=[0x42] re-read after the call (0x432F) — task #15 tracking.
    vm.di_track = di;
    vm.si_track = di;

    v2_despawn_13c93(vm, di);
    // Exit VM: POP ax + RETN in original skips the opcode loop return
    vm.running = false;
}

// 0x1C (sub_1443d): If ds:[obj+0x1A35] != 0 → skip 2, else jump. 0 bytes.
static void v2_vm_op_1C(V2VM& vm) {
    if (vm.field_r(OBJ_ANIM_TIMER) != 0) { vm.pc += 2; } else { v2_vm_do_jump(vm); }
}

// 0x3F (sub_145e5): OR 0x4000 on all sub-sprites + set dirty. 0 bytes.
// Loop from [obj+0x1A85] to [obj+0x1AAD], OR flags with 0x4000,
// OR byte [si+0x114E] with 2 (equivalent to OR word 0x114D with 0x0200).
// Orig loop is a DO-WHILE with NO [0x1AD5] gate (loc_145F1: body first,
// CMP si,cx / JL at end) — the body runs at least once unconditionally.
static void v2_vm_op_3F(V2VM& vm) {
    ObjRef self{vm, vm.global_r(DS_CUR_OBJ)};
    uint16_t cx = self.u16(OBJ_SUB_END);
    uint16_t si = self.u16(OBJ_SUB_SLOT);
    do {
        ObjRef sub{vm, si};                              // sub-sprite slot (cursor)
        sub.w16(OBJ_SPRITE_FLAGS, sub.u16(OBJ_SPRITE_FLAGS) | 0x4000);
        // OR byte at [si+0x114E] with 2 — high byte of word at 0x114D
        sub.w16(OBJ_DIRTY_MODE, sub.u16(OBJ_DIRTY_MODE) | 0x0200);
        si += 2;
    } while ((int16_t)si < (int16_t)cx);                 // CMP si,cx / JL
}

// 0x40 (sub_14604): Clear bits 13-14 on all sub-sprites. 0 bytes.
// Same DO-WHILE shape as sub_145e5 (loc_14610) — at least one iteration.
static void v2_vm_op_40(V2VM& vm) {
    ObjRef self{vm, vm.global_r(DS_CUR_OBJ)};
    uint16_t cx = self.u16(OBJ_SUB_END);
    uint16_t si = self.u16(OBJ_SUB_SLOT);
    do {
        ObjRef sub{vm, si};                              // sub-sprite slot (cursor)
        sub.w16(OBJ_SPRITE_FLAGS, sub.u16(OBJ_SPRITE_FLAGS) & 0x9FFF);
        sub.w16(OBJ_DIRTY_MODE, 2);
        si += 2;
    } while ((int16_t)si < (int16_t)cx);                 // CMP si,cx / JL
}

// 0x5C (sub_1474b): Subtract acc from indexed field. 1 byte.
static void v2_vm_op_5C(V2VM& vm) {
    uint16_t idx = vm.read_u8();
    uint16_t lookup = (uint16_t)(idx - LUT_FIELD_OFF);
    uint16_t si = *(uint16_t*)(vm.shadow +lookup);
    si += vm.global_r(DS_CUR_OBJ);
    uint16_t addr = (uint16_t)(si + OBJ_BBOX_Y0);
    vm.ds_write(addr, vm.ds_read(addr) - v2_vm_accumulator);
}

// sub_15972: Y position snap after tile collision (sub_15AFD carry path).
// ax = collision result from sub_15AFD: 0 = plain match, negative = slope (|ax|=adjustment), positive = moved up
// di = object index
static void v2_vm_y_snap_tile_15972(V2VM& vm, int16_t ax, uint16_t di) {
    uint16_t dx;
    if (di == 0) {
        static int _s15972 = 0; if (++_s15972 <= 30)
            fprintf(stderr, "V2-15972[%d]: di=0 ax=%04X(s=%d) Y=%04X Y_end=%04X Y_start=%04X\n",
                _s15972, (uint16_t)ax, ax, vm.ds_read(OBJ_WORLD_Y), vm.ds_read(OBJ_BBOX_Y1), vm.ds_read(OBJ_BBOX_Y0));
    }
    if (ax == 0) {
        // loc_15984: snap Y_end to tile boundary
        uint16_t y_end = ObjRef{vm, di}.u16(OBJ_BBOX_Y1);
        uint16_t snapped = (y_end & 0xFFF0) - 1;
        ObjRef{vm, di}.w16(OBJ_BBOX_Y1, snapped);
        dx = y_end - snapped;
    } else if (ax < 0) {
        // ax < 0: slope adjustment. dx = ax & 0xFF. Y_end -= dx.
        dx = (uint16_t)(ax & 0xFF);
        ObjRef{vm, di}.w16(OBJ_BBOX_Y1, ObjRef{vm, di}.u16(OBJ_BBOX_Y1) - dx);
    } else {
        // ax > 0: snap Y_start up to next tile boundary
        uint16_t y_start = ObjRef{vm, di}.u16(OBJ_BBOX_Y0);
        uint16_t snapped = (y_start | 0xF) + 1;
        ObjRef{vm, di}.w16(OBJ_BBOX_Y0, snapped);
        dx = y_start - snapped; // negative (wraps as uint16_t)
        ObjRef{vm, di}.w16(OBJ_WORLD_Y, ObjRef{vm, di}.u16(OBJ_WORLD_Y) - dx);
        ObjRef{vm, di}.w16(OBJ_BBOX_Y1, ObjRef{vm, di}.u16(OBJ_BBOX_Y1) - dx);
        ObjRef{vm, di}.w16(OBJ_FRAC_Y, 0);
        return;
    }
    // Common path for ax == 0 and ax < 0
    ObjRef{vm, di}.w16(OBJ_WORLD_Y, ObjRef{vm, di}.u16(OBJ_WORLD_Y) - dx);
    ObjRef{vm, di}.w16(OBJ_BBOX_Y0, ObjRef{vm, di}.u16(OBJ_BBOX_Y0) - dx);
    ObjRef{vm, di}.w16(OBJ_FRAC_Y, 0);
}

