// Units 94-95: sub_1555c / sub_15569 — per-object collision-VM passes.
static void v2_coll_pass_1555c(uint8_t* shadow, uint16_t si);
static void v2_coll_pass_15569(uint8_t* shadow, uint16_t si);
static void v2_vm_init_table();
static void v2_fntest_coll_pass_common(uint8_t* test_shadow, uint16_t si, bool full_1555c) {
    v2_vm_init_table();
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    extern int v2_fntest_vm_soft;
    int saved_soft = v2_fntest_vm_soft;
    v2_fntest_vm_soft = 1;   // VM FATALs become soft aborts
    bool saved_rv = v2_replay_verify_active;
    v2_replay_verify_active = true;
    if (full_1555c) v2_coll_pass_1555c(test_shadow, si);
    else            v2_coll_pass_15569(test_shadow, si);
    v2_replay_verify_active = saved_rv;
    v2_fntest_vm_soft = saved_soft;
    v2_vm_acc_base = saved_acc;
}
static bool v2_vm_collision_check_155d6(V2VM& vm);
static bool v2_vm_collision_check_156c0(V2VM& vm);
static int v2_fntest_coll_check_common(uint8_t* test_shadow, uint16_t pc, bool d6) {
    v2_vm_init_table();
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    extern int v2_fntest_vm_soft;
    int saved_soft = v2_fntest_vm_soft;
    v2_fntest_vm_soft = 1;
    bool saved_rv = v2_replay_verify_active;
    v2_replay_verify_active = true;
    V2VM vm{};
    vm.ds = test_shadow; vm.shadow = test_shadow;
    vm.es = v2_resolve_segment(0x4000 /*FT_VM_TESTSEG*/, test_shadow);
    vm.cs_base = v2_m2c_base ? v2_m2c_base + 0x1A20 : nullptr;
    vm.obj = *(uint16_t*)(test_shadow + DS_CUR_OBJ);
    vm.pc = pc; vm.running = true; vm.carry = false;
    bool cf = d6 ? v2_vm_collision_check_155d6(vm)
                 : v2_vm_collision_check_156c0(vm);
    int out = ((int)vm.pc << 1) | (cf ? 1 : 0);
    v2_replay_verify_active = saved_rv;
    v2_fntest_vm_soft = saved_soft;
    v2_vm_acc_base = saved_acc;
    return out;
}
// sub_16390 (seg000 eips 0x6390..0x63AB): slope height diff.
// idx = ((tile&0xF)<<4) | (x&0xF); sv = ds:[idx-0x7684] & 0xF;
// return ([di+150D]&0xF) - sv (true difference in AX).
static int16_t v2_slope_diff_16390(uint8_t* shadow, uint16_t tile_ax, uint16_t x_si, uint16_t di) {
    uint16_t sidx = (uint16_t)(((tile_ax & 0xF) << 4) + (x_si & 0xF));
    uint8_t sv = shadow[(uint16_t)(sidx - 0x7684)] & 0xF;
    return (int16_t)((*(uint16_t*)(shadow + (uint16_t)(di + OBJ_BBOX_Y1)) & 0xF) - sv);
}
