static void v2_vm_anim_tail_135cf(V2VM& vm);   // defined below
extern "C" void v2_fntest_call_anim(uint8_t* test_shadow, uint16_t obj, int which) {
    V2VM vm{};
    vm.ds = test_shadow; vm.shadow = test_shadow;
    vm.es = test_shadow;
    // anim cmds read constant tables from the CS segment (e.g. cmd 0x15's
    // sprite-type table at cs:0x32D7) — point at real seg000 like the game.
    vm.cs_base = v2_m2c_base ? v2_m2c_base + 0x1A20 : nullptr;
    vm.obj = obj; vm.pc = 0; vm.running = true; vm.carry = false;
    vm.slot = obj / 2;
    extern int v2_fntest_vm_soft;
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    bool saved_rv = v2_replay_verify_active;
    v2_replay_verify_active = true;
    v2_fntest_vm_soft = 1;
    v2_vm_anim_interp_1303a(vm);
    if (which) v2_vm_anim_tail_135cf(vm);
    v2_replay_verify_active = saved_rv;
    v2_vm_acc_base = saved_acc;
}

// Wave B1b: tile helpers (sub_14199/141a7/141b3/141ba/141e0 mirrors).
// which: 0=141ba word, 1=141b3 low10, 2=141a7 type, 3=14199 type@pixel,
// 4=141e0 write (ax_in). Units point [2E63] at the game DS segment via
// v2_fntest_ds_seg_override, so reads/writes hit the scratch image.
extern "C" void v2_fntest_call_tile(int which, uint8_t* test_shadow,
                                    uint16_t si, uint16_t di, uint16_t ax_in,
                                    uint16_t* out_ax) {
    V2VM vm{};
    vm.ds = test_shadow; vm.shadow = test_shadow;
    vm.es = test_shadow;
    vm.cs_base = v2_m2c_base ? v2_m2c_base + 0x1A20 : nullptr;
    vm.obj = 6; vm.pc = 0; vm.running = true; vm.carry = false; vm.slot = 3;
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    uint16_t r = ax_in;
    switch (which) {
    case 0: r = v2_vm_tile_read_141ba(vm, si, di); break;
    case 1: r = v2_vm_tile_low_141b3(vm, si, di); break;
    case 2: r = v2_vm_tile_type_141a7(vm, si, di); break;
    case 3: r = v2_vm_tile_type_px_14199(vm, si, di); break;
    case 4: v2_vm_tile_write_141e0(vm, si, di, ax_in); break;
    }
    if (out_ax) *out_ax = r;
    v2_vm_acc_base = saved_acc;
}

// Wave B1b: channel getters (sub_1547e/15485/1549a/154a3 mirrors). The unit
// plants the byte stream in the FT_VM_TESTSEG zone of m2c::m; the oracle
// reads it via v2_fntest_es_override, v2 via vm.es pointed at the same zone.
extern "C" void v2_fntest_call_ch_getter(int ch, uint8_t* test_shadow,
                                         uint16_t pc, uint16_t testseg,
                                         uint16_t* out_val, uint16_t* out_pc) {
    V2VM vm{};
    vm.ds = test_shadow; vm.shadow = test_shadow;
    vm.es = v2_m2c_base ? v2_m2c_base + (uint32_t)testseg * 16 : test_shadow;
    vm.cs_base = v2_m2c_base ? v2_m2c_base + 0x1A20 : nullptr;
    vm.obj = 6; vm.pc = pc; vm.running = true; vm.carry = false; vm.slot = 3;
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    uint16_t v = 0;
    switch (ch) {
    case 0: v = v2_vm_read_literal(vm); break;
    case 1: v = v2_vm_read_indexed_field(vm); break;
    case 2: v = v2_vm_read_indirect(vm); break;
    case 3: v = v2_vm_read_indexed_field_1995(vm); break;
    }
    if (out_val) *out_val = v;
    if (out_pc) *out_pc = vm.pc;
    v2_vm_acc_base = saved_acc;
}

// Anim-search family (sub_158aa..sub_158e6 mirrors). A minimal V2VM over the
// case image; segment parity via v2_replay_verify_active (tile reads resolve
// [ds:0x2E63] linearly into m2c::m, same as the oracle's raddr).
// Returns carry (compared against the oracle's CF).
extern "C" int v2_fntest_call_search(uint8_t* test_shadow, int which,
                                     uint16_t filter, uint16_t obj) {
    V2VM vm{};
    vm.ds = test_shadow; vm.shadow = test_shadow;
    vm.es = test_shadow;
    vm.cs_base = v2_m2c_base ? v2_m2c_base + 0x1A20 : nullptr;
    vm.obj = obj; vm.pc = 0; vm.running = true; vm.carry = false;
    vm.slot = obj / 2;
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    bool saved_rv = v2_replay_verify_active;
    v2_replay_verify_active = true;
    switch (which) {
    case 0: v2_vm_probe_left_158aa(vm, filter, obj); break;
    case 1: v2_vm_probe_right_158b9(vm, filter, obj); break;
    case 2: v2_vm_probe_up_158c8(vm, filter, obj); break;
    case 3: v2_vm_probe_down_158d7(vm, filter, obj); break;
    case 5: vm.carry = v2_vm_tile_at_pos_15ae9(vm, filter); break;   // unit 83
    case 6: vm.carry = v2_vm_obj_at_pos_160cf(vm, filter); break;    // unit 82
    case 7: v2_vm_probe_at_pos_1589b(vm, filter); break;             // unit 84
    case 8:  vm.carry = v2_vm_tile_scan_x_159f6(vm, filter, obj,     // unit 85: sub_159c6
                 (uint16_t)(*(uint16_t*)(test_shadow + (uint16_t)(obj + OBJ_BBOX_X0)) - 1)); break;
    case 9:  vm.carry = v2_vm_tile_scan_x_159f6(vm, filter, obj,     // unit 86: sub_159d3
                 *(uint16_t*)(test_shadow + (uint16_t)(obj + OBJ_BBOX_X0))); break;
    case 10: vm.carry = v2_vm_tile_search_right_159df(vm, filter, obj); break; // unit 87
    case 11: vm.carry = v2_vm_tile_search_up_15a57(vm, filter, obj); break;    // unit 88
    case 12: vm.carry = v2_vm_tile_probe_15ac4(vm, filter, obj); break;        // unit 89
    default: v2_vm_probe_front_158e6(vm, filter, obj); break;
    }
    v2_replay_verify_active = saved_rv;
    v2_vm_acc_base = saved_acc;
    return vm.carry ? 1 : 0;
}
// Vel/collision scan family (units 27-30). Same minimal-V2VM setup as the
// search wrapper. Returns -1 on CLC; on STC returns the 16-bit AX the orig
// leaves: sub_1614e → 0, sub_15c37/sub_15c93 → direction (1=cef/left-or-d3c,
// 0=cf5/right-or-d42), sub_15afd → tile snap value (0x8000|x or 0).
static bool v2_vm_obj_coll_scan_1614e(V2VM& vm, uint16_t filter_si, uint16_t obj_di);
static bool v2_vm_xvel_obj_search_15c37(V2VM& vm, uint16_t filter_si, uint16_t di,
                            int16_t& out_dir, uint16_t& out_partner);
static bool v2_vm_tile_coll_down_15afd(V2VM& vm, uint16_t filter_si, uint16_t di,
                            int16_t& out_tile_ax, bool dbg);
extern "C" int32_t v2_fntest_call_scan(uint8_t* test_shadow, int which,
                                       uint16_t filter, uint16_t obj) {
    V2VM vm{};
    vm.ds = test_shadow; vm.shadow = test_shadow;
    vm.es = test_shadow;
    vm.cs_base = v2_m2c_base ? v2_m2c_base + 0x1A20 : nullptr;
    vm.obj = obj; vm.pc = 0; vm.running = true; vm.carry = false;
    vm.slot = obj / 2;
    uint8_t* saved_acc = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    bool saved_rv = v2_replay_verify_active;
    v2_replay_verify_active = true;
    int32_t r = -1;
    switch (which) {
    case 0: if (v2_vm_obj_coll_scan_1614e(vm, filter, obj)) r = 0; break;
    case 1: { int16_t dir = 0; uint16_t partner = 0;
              if (v2_vm_xvel_obj_search_15c37(vm, filter, obj, dir, partner)) r = (uint16_t)dir; break; }
    case 2: { uint16_t dir = 0;
              if (v2_yvel_obj_search_15c93(vm, filter, obj, dir)) r = dir; break; }
    default: { int16_t tile_ax = 0;
               if (v2_vm_tile_coll_down_15afd(vm, filter, obj, tile_ax, false)) r = (uint16_t)tile_ax; break; }
    }
    v2_replay_verify_active = saved_rv;
    v2_vm_acc_base = saved_acc;
    return r;
}
// Units 33-36: spawn/despawn slot family — pure DS leaf mirrors, no VM state.
// which: 0=sub_13c0c (despawn cull), 1=sub_13d68 (slot run alloc, returns CF),
//        2=sub_13dd6 (slot init), 3=sub_13e15 (slot size/type init).
extern "C" int32_t v2_fntest_call_snapfam(uint8_t* test_shadow, int which, uint16_t si) {
    switch (which) {
    case 0: v2_despawn_bounds_13c0c(test_shadow); return -1;
    case 1: return v2_slot_alloc_13d68(test_shadow, si) ? 1 : 0;
    case 2: v2_slot_init_13dd6(test_shadow, si); return -1;
    default: v2_slot_size_init_13e15(test_shadow, si); return -1;
    }
}
// Units 33-34 (DAC): run the v2 palette-dispatch mirrors on a case image and
// expose the resulting shadow-DAC state. which: 0=sub_10fe6, 1=sub_10ffc.
// The caller resets v2_dac_shadow to the same baseline as the oracle's
// drawPalette before each case (both start equal; only call effects differ).
extern "C" void v2_fntest_call_pal(uint8_t* test_shadow, int which, uint8_t* dac_out768) {
    if (which == 0) v2_pal_dac_write_10fe6(test_shadow);
    else            v2_pal_anim_10ffc(test_shadow);
    memcpy(dac_out768, v2_dac_shadow, 768);
}
extern "C" void v2_fntest_reset_v2_dac(void) { memset(v2_dac_shadow, 0, 768); }
// Class-B: per-object VM exec (v2_vm_execute_object, fwd-declared at top).
// v2_vm_accumulator is a file-scope global carried across opcodes — reset it
// so each synthetic case starts from the canonical zero accumulator.
extern "C" void v2_fntest_call_vm_exec(uint8_t* test_shadow, uint16_t si) {
    extern int v2_fntest_vm_soft;
    v2_vm_init_table();      // selftest bypasses the game init that fills the optable
    // The accumulator lives at DS:0x8A (macro over v2_vm_acc_base) — point it
    // at the case image for the call so acc is part of the compared DS state,
    // exactly like the oracle (whose opcodes use ds:0x8A too).
    uint8_t* saved_acc_base = v2_vm_acc_base;
    v2_vm_acc_base = test_shadow;
    v2_fntest_vm_soft = 1;   // VM FATALs (op>0xD7 etc.) become soft aborts (→2)
    // Segment parity with the oracle: resolve EVERY segment linearly into
    // m2c::m (the oracle's raddr does exactly that). Without this, seg values
    // that happen to equal a zeroed shadow-segment key (e.g. es=[ds:0x2E67]=0
    // in a spawn path) would resolve to a v2 shadow buffer while the oracle
    // reads real low memory — incomparable.
    bool saved_rv = v2_replay_verify_active;
    v2_replay_verify_active = true;
    v2_vm_di_track = 0;      // oracle io_regs enter with di=0 (task #15)
    v2_vm_execute_object(test_shadow, si);
    v2_replay_verify_active = saved_rv;
    v2_vm_acc_base = saved_acc_base;
}
extern "C" void v2_fntest_call_sub_13dd6(uint8_t* test_shadow, uint16_t si) {
    v2_slot_init_13dd6(test_shadow, si);
}
extern "C" void v2_fntest_call_sub_13e15(uint8_t* test_shadow, uint16_t si) {
    v2_slot_size_init_13e15(test_shadow, si);
}

// sub_161a1: bounding box check for sub_1614E. di=self, si=target.
// Returns true (carry) if collision.
static bool v2_vm_bbox_check_161a1(V2VM& vm, uint16_t di, uint16_t si) {
    ObjRef self{vm, di}, target{vm, si};
    // X overlap check
    if (self.bbox_x1() < target.bbox_x0()) return false;
    if (target.bbox_x1() < self.bbox_x0()) return false;

    // Y_end clamped to >= 0
    int16_t y_end = self.bbox_y1();
    if (y_end < 0) y_end = 0;
    vm.ds_write(DS_MODE_WORD, (uint16_t)y_end);             // MOV ds:32h, ax

    // Adjusted Y = Y_end - Y_center + old_Y_center, clamp to > 0
    // Orig 0x61cb-0x61d3: SUB ax,[1765]; ADD ax,[13CD]; JG — flags come from the ADD:
    // its operands are the WRAPPED int16 SUB result and [13CD]; JG tests the TRUE sum
    // of those two operands (SF^OF of the ADD), while AX keeps the wrapped bits.
    int16_t sub16 = (int16_t)(uint16_t)(self.u16(OBJ_BBOX_Y1) - self.u16(OBJ_WORLD_Y));
    int32_t add32 = (int32_t)sub16 + (int32_t)self.y_prev();
    uint16_t adj_y = (add32 > 0) ? (uint16_t)add32 : 0;

    // ds:0x34 = min, ds:0x36 = max of (ds32, adj_y)
    if ((int16_t)(uint16_t)adj_y < (int16_t)vm.ds_read(DS_MODE_WORD)) {
        vm.ds_write(DS_SCRATCH_34, (uint16_t)adj_y);          // MOV ds:34h, ax
        vm.ds_write(DS_SCRATCH_36, vm.ds_read(DS_MODE_WORD));         // MOV ds:36h, ax (= ds:32)
    } else {
        vm.ds_write(DS_SCRATCH_36, (uint16_t)adj_y);          // MOV ds:36h, ax
        vm.ds_write(DS_SCRATCH_34, vm.ds_read(DS_MODE_WORD));         // MOV ds:34h, ax (= ds:32)
    }
    uint16_t ds34 = vm.ds_read(DS_SCRATCH_34);
    uint16_t ds36 = vm.ds_read(DS_SCRATCH_36);

    // Target's adjusted Y: [si+14E5] - [si+1765] + [si+13CD]
    int16_t target_adj = target.bbox_y0() - target.world_y() + target.y_prev();
    if ((int16_t)target_adj < target.bbox_y0()) {
        // target_adj < target.Y_start: orig loc_161f2 — MOV ds:32h, ax (= target_adj) at eip 0x6204.
        vm.ds_write(DS_MODE_WORD, (uint16_t)target_adj);
        // check ds:0x36 >= target_adj AND target.Y_start >= ds:0x34
        if ((int16_t)ds36 < target_adj) return false;
        if (target.bbox_y0() < (int16_t)ds34) return false;
    } else {
        // target_adj >= target.Y_start: orig loc_1621c — MOV ds:32h, ax where AX is still
        // target_adj at the JGE entry (computed at eips 0x61F2-0x61FA, before the cmp/jge).
        vm.ds_write(DS_MODE_WORD, (uint16_t)target_adj);
        // check ds:0x36 >= target.Y_start AND target_adj >= ds:0x34
        if ((int16_t)ds36 < target.bbox_y0()) return false;
        if ((int16_t)target_adj < (int16_t)ds34) return false;
    }
    return true;
}

// sub_1614E: object collision detection for sub_1584e.
// Scans objects for type match + Y velocity comparison + sub_161a1 bounding box.
static bool v2_vm_obj_coll_scan_1614e(V2VM& vm, uint16_t filter_si, uint16_t obj_di) {
    vm.ds_write(DS_SCRATCH_3A, filter_si);
    ObjRef self{vm, obj_di};
    uint8_t* rds = vm.shadow;
    uint16_t table_end = *(uint16_t*)(rds + DS_OBJ_COUNT);
    for (uint16_t si = 0; si == 0 || (int16_t)si < (int16_t)table_end; si += 2) {   // orig do-while: first slot unconditional (ADD si,2; CMP si,[372]; JL)
        ObjMem cand{rds, si};
        if (cand.code_seg() == 0) continue;
        if (si == *(uint16_t*)(rds + DS_CUR_OBJ)) continue;
        vm.ds_write(DS_SCRATCH_38, si);
        uint8_t obj_type = (uint8_t)cand.type_id();
        // Filter match
        uint16_t flt = filter_si;
        bool match = false;
        while (true) {
            uint8_t fv = *(uint8_t*)(rds + (uint16_t)(flt - LUT_SCAN_FILTER));
            if (obj_type < fv) break;
            if (obj_type == fv) { match = true; break; }
            flt++;
        }
        if (!match) continue;
        // Y velocity check: self.vel_Y - target.vel_Y
        // Orig 0x6181: SUB ax,[si+196D]; JZ skip; JL skip — JL is SF^OF of the SUB,
        // i.e. the sign of the TRUE 32-bit difference (not the truncated int16).
        int32_t vel_diff = (int32_t)self.vel_y() - (int32_t)cand.vel_y();
        if (vel_diff <= 0) continue; // JZ (ZF: wrapped==0 ⇔ diff==0 in ±65534) or JL (true sign) → skip
        // sub_161a1: bounding box check
        if (v2_vm_bbox_check_161a1(vm, obj_di, si)) {
            // Found! ax = 0, STC
            return true;
        }
    }
    return false;
}

// sub_15DA8: Y position snap after object collision.
// ax = direction (0 = moved down, !0 = moved up). si = partner, di = self.
static void v2_vm_y_snap_obj_15DA8(V2VM& vm, int16_t ax_dir, uint16_t si_partner, uint16_t di) {
    uint16_t dx;
    if (di == 0) {
        static int _s15da8 = 0; if (++_s15da8 <= 30)
            fprintf(stderr, "V2-15DA8[%d]: di=0 ax_dir=%d si=%04X Y=%04X Y_end=%04X p_Y_end=%04X p_Y_start=%04X\n",
                _s15da8, ax_dir, si_partner, vm.ds_read(OBJ_WORLD_Y), vm.ds_read(OBJ_BBOX_Y1),
                ObjRef{vm, si_partner}.u16(OBJ_BBOX_Y1), ObjRef{vm, si_partner}.u16(OBJ_BBOX_Y0));
    }
    ObjRef self{vm, di}, partner{vm, si_partner};
    if (ax_dir == 0) {
        // Moved down: snap up. dx = self.Y_end - partner.Y_start + 1
        dx = self.u16(OBJ_BBOX_Y1) - partner.u16(OBJ_BBOX_Y0) + 1;
        self.w16(OBJ_WORLD_Y, self.u16(OBJ_WORLD_Y) - dx);
        self.w16(OBJ_BBOX_Y0, self.u16(OBJ_BBOX_Y0) - dx);
        self.w16(OBJ_BBOX_Y1, self.u16(OBJ_BBOX_Y1) - dx);
    } else {
        // Moved up: snap down. dx = partner.Y_end - self.Y_start + 1
        dx = partner.u16(OBJ_BBOX_Y1) - self.u16(OBJ_BBOX_Y0) + 1;
        self.w16(OBJ_WORLD_Y, self.u16(OBJ_WORLD_Y) + dx);
        self.w16(OBJ_BBOX_Y0, self.u16(OBJ_BBOX_Y0) + dx);
        self.w16(OBJ_BBOX_Y1, self.u16(OBJ_BBOX_Y1) + dx);
    }
    self.w16(OBJ_FRAC_Y, 0);
}

// sub_15d6b: X position snap for sub_15788 (object collision from sub_15c37).
// ax = direction (0 = moved right, !0 = moved left). si = partner, di = self.
static void v2_vm_x_snap_obj_15d6b(V2VM& vm, int16_t ax_dir, uint16_t si_partner, uint16_t di) {
    uint16_t dx;
    ObjRef self{vm, di}, partner{vm, si_partner};
    if (ax_dir == 0) {
        // Moved right: snap self left. dx = self.X_end - partner.X_start + 1
        dx = self.u16(OBJ_BBOX_X1) - partner.u16(OBJ_BBOX_X0) + 1;
        self.w16(OBJ_WORLD_X, self.u16(OBJ_WORLD_X) - dx);
        self.w16(OBJ_BBOX_X0, self.u16(OBJ_BBOX_X0) - dx);
        self.w16(OBJ_BBOX_X1, self.u16(OBJ_BBOX_X1) - dx);
    } else {
        // Moved left: snap self right. dx = partner.X_end - self.X_start + 1
        dx = partner.u16(OBJ_BBOX_X1) - self.u16(OBJ_BBOX_X0) + 1;
        self.w16(OBJ_WORLD_X, self.u16(OBJ_WORLD_X) + dx);
        self.w16(OBJ_BBOX_X0, self.u16(OBJ_BBOX_X0) + dx);
        self.w16(OBJ_BBOX_X1, self.u16(OBJ_BBOX_X1) + dx);
    }
    self.w16(OBJ_FRAC_X, 0); // clear X fractional accumulator
}

// sub_15afd (seg000 0x5afd-0x5c36): downward tile collision. si=filter, di=object.
// Returns CF; out_tile_ax = AX at the STC exits (slope paths: 0x8000|snap value
// via loc_15bab; horizontal-scan match: 0 via loc_15c20). DS writes: 0x6C/0x6E
// (only past the y_moved gate), 0x3A + 0x32 (slope probe), 0x36/0x38 (horizontal
// walk), [di+0x150D] pushed+restored around the slope probe.
// Orig does NOT write ds:0x34 — only ds:0x6C (filter) and ds:0x6E (di).
// (sub_15911, the Y-tile check for BOTH directions, has its own writers via loc_15a7d/64; not here.)
static bool v2_vm_tile_coll_down_15afd(V2VM& vm, uint16_t filter_si, uint16_t di, int16_t& out_tile_ax, bool dbg) {
    bool tile_found = false;
    int16_t tile_ax = 0; // result for sub_15972

    // Orig sub_15afd 0x5b01: SUB ax,[13CD]; JZ ret; JGE continue — continue iff the
    // TRUE difference (SF^OF of the SUB) is > 0, not the truncated int16.
    ObjRef self0{vm, di};
    int32_t y_moved = (int32_t)self0.world_y() - (int32_t)self0.y_prev();
    if (dbg) fprintf(stderr, "  y_moved=%d\n", (int)y_moved);
    if (y_moved > 0) {
        vm.ds_write(DS_TEXT_COL, filter_si);
        vm.ds_write(DS_TEXT_ROW, di);

        // Scan filter for slope type
        uint16_t flt = filter_si;
        uint8_t filt_val;
        while (true) {
            filt_val = vm.shadow[(uint16_t)(flt - LUT_SCAN_FILTER)];
            if (filt_val == 0xFF || filt_val >= 0x30) break;
            flt++;
        }

        if (dbg) fprintf(stderr, "  filt_val=%02X\n", filt_val);
        if (filt_val >= 0x30 && filt_val != 0xFF) {
            uint16_t obj_x = self0.u16(OBJ_WORLD_X);
            int16_t adj_y = (int16_t)(self0.y_prev() - self0.world_y() + self0.bbox_y1());
            uint16_t tt = (v2_vm_tile_read_141ba(vm, obj_x >> 4, (uint16_t)adj_y >> 4) & 0xFC00) >> 10;
            if (dbg) fprintf(stderr, "  obj_x=%04X adj_y=%04X tt=%02X\n", obj_x, adj_y, tt);
            if (tt >= 0x30) {
                vm.ds_write(DS_SCRATCH_3A, tt);
                di = vm.ds_read(DS_TEXT_ROW);
                ObjRef selfA{vm, di};
                uint16_t cur_y_end = selfA.u16(OBJ_BBOX_Y1);
                uint16_t tt2 = (v2_vm_tile_read_141ba(vm, obj_x >> 4, cur_y_end >> 4) & 0xFC00) >> 10;
                if (dbg) fprintf(stderr, "  cur_y_end=%04X tt2=%02X\n", cur_y_end, tt2);
                if (tt2 < 0x30) {
                    uint16_t saved = cur_y_end;
                    uint16_t temp = (tt2 & 0xFFF0) - 1;
                    selfA.w16(OBJ_BBOX_Y1, temp);
                    uint16_t slope_tt = vm.ds_read(DS_SCRATCH_3A);
                    int16_t sr = v2_slope_diff_16390(vm.shadow, slope_tt, obj_x, (uint16_t)vm.obj);
                    if (dbg) fprintf(stderr, "  saved=%04X temp=%04X slope_tt=%02X sr=%d\n",
                        saved, temp, slope_tt, sr);
                    if (sr >= 0) {
                        // Orig eip 0x5B72: MOV ds:32h, ax (=sr from sub_16390) — used at eip 0x5B7D ADD ax, ds:32h.
                        vm.ds_write(DS_MODE_WORD, (uint16_t)sr);
                        selfA.w16(OBJ_BBOX_Y1, saved);
                        tile_ax = (int16_t)((uint16_t)((saved & 0xF) + (uint16_t)sr + 1) | 0x8000);
                        tile_found = true;
                        if (dbg) fprintf(stderr, "  PATH=A tile_ax=%04X\n", (uint16_t)tile_ax);
                    } else {
                        // Orig loc_15b84: just POP into [di+150Dh] — restore saved.
                        selfA.w16(OBJ_BBOX_Y1, saved);
                    }
                }
            }
        }

        // loc_15b88 is reached ONLY from inside loc_15b2a (slope filter found path).
        // Orig SKIPS loc_15b88 when filter scan finds 0xFF (jmps directly to loc_15bb8).
        // Therefore guard on slope filter actually being found.
        bool slope_filter_found = (filt_val >= 0x30 && filt_val != 0xFF);
        // skip_horizontal: orig at loc_15b88 with tt3>=0x30 AND sr<0 jumps to loc_15c2d
        // (CLC RET, no horizontal scan, no sub_1614e via carry — caller IS still
        // sub_1584e which on no-carry calls sub_1614e regardless).
        // So orig sr<0 path STILL runs sub_1614e but skips horizontal scan.
        bool skip_horizontal = false;
        if (!tile_found && slope_filter_found) {
            // loc_15b88: check slope at current position
            di = vm.ds_read(DS_TEXT_ROW);
            ObjRef selfB{vm, di};
            uint16_t obj_x = selfB.u16(OBJ_WORLD_X);
            uint16_t cur_y = selfB.u16(OBJ_BBOX_Y1);
            uint16_t tt3 = (v2_vm_tile_read_141ba(vm, obj_x >> 4, cur_y >> 4) & 0xFC00) >> 10;
            if (dbg) fprintf(stderr, "  loc_15b88: cur_y=%04X tt3=%02X\n", cur_y, tt3);
            if (tt3 >= 0x30) {
                int16_t sr = v2_slope_diff_16390(vm.shadow, tt3, obj_x, di);
                if (dbg) fprintf(stderr, "    sr=%d\n", sr);
                if (sr >= 0) { tile_ax = (int16_t)((uint16_t)sr | 0x8000); tile_found = true;
                    if (dbg) fprintf(stderr, "    PATH=B tile_ax=%04X\n", (uint16_t)tile_ax);
                } else {
                    // orig eip 0x5BA8: jmp loc_15c2d → CLC RET, skipping horizontal scan
                    skip_horizontal = true;
                }
            }
            // tt3 < 0x30: orig falls through to loc_15bb8 (horizontal scan)
        }

        if (!tile_found && !skip_horizontal) {
            // loc_15bb8: horizontal tile scan
            di = vm.ds_read(DS_TEXT_ROW);
            ObjRef selfC{vm, di};
            filter_si = vm.ds_read(DS_TEXT_COL);
            uint16_t ye = selfC.u16(OBJ_BBOX_Y1);
            uint16_t old_ye = (uint16_t)((int16_t)ye - selfC.world_y() + selfC.y_prev());
            if ((old_ye & 0xFFF0) != (ye & 0xFFF0)) {
                uint16_t xe = selfC.u16(OBJ_BBOX_X1);
                vm.ds_write(DS_SCRATCH_36, ye); vm.ds_write(DS_SCRATCH_38, xe);
                for (uint16_t s = selfC.u16(OBJ_BBOX_X0); ; ) {
                    uint8_t al = (uint8_t)((v2_vm_tile_read_141ba(vm, s >> 4, vm.ds_read(DS_SCRATCH_36) >> 4) & 0xFC00) >> 10);
                    bool advance = false;
                    if (al >= 0x30) {
                        // orig loc_15bf0: if slope (>= 0x30), JGE loc_15c0b — SKIP slope, continue scan.
                        // Slope adjustment is NOT applied in horizontal scan.
                        advance = true;
                    } else {
                        // Filter scan (loc_15c00): cmp al with each filter byte until match or above.
                        uint16_t f = filter_si; bool m = false; bool below = false;
                        while (true) {
                            uint8_t fv = vm.shadow[(uint16_t)(f - LUT_SCAN_FILTER)];
                            // JB (al < fv) → loc_15c0b (advance)
                            if (al < fv) { below = true; break; }
                            // JZ (al == fv) → loc_15c20 (match)
                            if (al == fv) { m = true; break; }
                            f++;
                        }
                        if (m) { tile_ax = 0; tile_found = true; break; }
                        // below or fall through: advance
                        (void)below;
                        advance = true;
                    }
                    if (advance) {
                        // loc_15c0b: cmp si, ds:38 (X_end)
                        if (s == xe) break; // jz loc_15c2d (CLC return)
                        s += 0x10;
                        // cmp si, ds:38; jl loc_15bf0 → continue
                        // else: si = ds:38 (clamp); jmp loc_15bf0
                        if ((int16_t)s >= (int16_t)xe) s = xe;
                        continue;
                    }
                }
            }
        }
    }
    out_tile_ax = tile_ax;
    return tile_found;
}

// sub_1584e collision check helper — different from sub_155d6!
// All paths consume 1 byte. Returns carry flag (true = collision).
// Path 1 (ds:0x390 > 0): full bounding box check via sub_15AFD etc.
// Path 2 (ds:0x390 < 0): no collision, just consume byte
// Path 3 (ds:0x390 == 0): check bit in [obj+0x13F5] → collision if set
static bool v2_vm_collision_check_1584e(V2VM& vm) {
    int16_t state = (int16_t)vm.global_r(DS_COLL_PHASE);
    static int _coll_dbg = 0;
    bool dbg = (vm.obj == 0 && _coll_dbg < 30);
    if (dbg) {
        _coll_dbg++;
        fprintf(stderr, "V2-COLL-1584E[%d]: obj=0 state=%d Y=%04X Y_prev=%04X Y_end=%04X Y_start=%04X\n",
            _coll_dbg, state,
            vm.ds_read(vm.obj + OBJ_WORLD_Y), vm.ds_read(vm.obj + OBJ_Y_PREV),
            vm.ds_read(vm.obj + OBJ_BBOX_Y1), vm.ds_read(vm.obj + OBJ_BBOX_Y0));
    }

    if (state == 0) {
        // loc_15886: INC bx + check bit in collision flags
        vm.pc += 1;
        uint16_t di = vm.global_r(DS_CUR_OBJ);
        vm.di_track = di;   // orig: MOV di,ds:42h (task #15)
        uint16_t si = vm.global_r(DS_COLL_BIT_IDX);
        uint16_t mask = *(uint16_t*)(vm.shadow +(uint16_t)(si - LUT_BIT_MASK));
        uint16_t flags = ObjRef{vm, di}.u16(OBJ_COLL_BITS);
        if (flags & mask) {
            return true;   // STC — collision
        }
        return false;      // CLC — no collision
    }

    if (state < 0) {
        // loc_15883: INC bx + CLC
        vm.pc += 1;
        return false;
    }

    // state > 0: full collision check path.
    // sub_15AFD (tile) → sub_15972 (snap), or sub_1614E (obj) → sub_15DA8 (snap).
    // Set collision bit if found. ALWAYS returns CLC (false).
    {
        uint8_t filter = vm.read_u8();
        uint16_t di = vm.global_r(DS_CUR_OBJ);
        vm.di_track = di;   // orig 0x585F: MOV di,ds:42h; scans preserve DI (task #15)
        uint16_t filter_si = (uint16_t)filter;
        if (dbg) fprintf(stderr, "  filter_byte=%02X di=%04X\n", filter, di);

        // sub_15AFD: downward tile collision (extracted — see v2_vm_tile_coll_down_15afd above).
        int16_t tile_ax = 0; // result for sub_15972
        bool tile_found = v2_vm_tile_coll_down_15afd(vm, filter_si, di, tile_ax, dbg);
        di = vm.global_r(DS_CUR_OBJ);
        bool collision_found = false;
        if (tile_found) {
            // sub_15972: Y tile snap
            v2_vm_y_snap_tile_15972(vm, tile_ax, di);
            collision_found = true;
        } else {
            // sub_1614E: object collision check.
            // orig sub_1614e at loc_16179 does `mov si, ds:0x38` before returning CARRY,
            // so SI register = ds:0x38 = matched partner index. sub_15DA8 uses si as partner.
            if (v2_vm_obj_coll_scan_1614e(vm, filter_si, di)) {
                uint16_t partner = vm.ds_read(DS_SCRATCH_38);
                v2_vm_y_snap_obj_15DA8(vm, 0, partner, di); // ax=0 for sub_1584e (downward)
                collision_found = true;
            }
        }

        if (collision_found) {
            // loc_15875: set collision bit
            uint16_t si_38e = vm.global_r(DS_COLL_BIT_IDX);
            uint16_t mask = *(uint16_t*)(vm.shadow +(uint16_t)(si_38e - LUT_BIT_MASK));
            ObjRef{vm, di}.w16(OBJ_COLL_BITS, ObjRef{vm, di}.u16(OBJ_COLL_BITS) | mask);
        }
        return false; // ALWAYS CLC
    }
}

// sub_157eb: UPward collision check (orig — analog sub_1584e but uses sub_15911/sub_15c93).
// Same state-machine: state==0 → check collision bit (return CARRY if set),
// state<0 → INC bx, no carry, state>0 → full check (always CLC).
static bool v2_vm_collision_check_157eb(V2VM& vm) {
    int16_t state = (int16_t)vm.global_r(DS_COLL_PHASE);
    if (state == 0) {
        // loc_15823: INC bx + check collision bit
        vm.pc += 1;
        uint16_t di = vm.global_r(DS_CUR_OBJ);
        vm.di_track = di;   // orig: MOV di,ds:42h (task #15)
        uint16_t si = vm.global_r(DS_COLL_BIT_IDX);
        uint16_t mask = *(uint16_t*)(vm.shadow +(uint16_t)(si - LUT_BIT_MASK));
        if (ObjRef{vm, di}.u16(OBJ_COLL_BITS) & mask) return true;
        return false;
    }
    if (state < 0) {
        // loc_15820: INC bx + CLC — DI untouched
        vm.pc += 1;
        return false;
    }
    // state > 0 (orig sub_157eb body):
    //   mov si, es:[bx]; inc bx; and si, 0xFF; mov di, ds:42
    //   call sub_15911; if carry → sub_15972 + set bit; else call sub_15c93;
    //   if carry → sub_15da8 + set bit; else skip. Returns CLC always.
    uint8_t filter = vm.read_u8();
    uint16_t di = vm.global_r(DS_CUR_OBJ);
    vm.di_track = di;   // orig 0x57FC: MOV di,ds:42h; scans preserve DI (task #15)
    // NOTE: orig sub_157eb does NOT write ds:0x3A — filter is passed via SI register.
    // v2 passes filter as parameter to v2_tile_coll_y_15911 directly. Removed ds_write(0x3A).
    uint16_t out_dir = 0;
    bool collision_found = false;
    if (v2_tile_coll_y_15911(vm, di, (uint16_t)filter, out_dir)) {
        // sub_15972: Y tile snap. AX from sub_15911:
        //   out_dir=1 → cur_y < old_y (moved up)   → orig AX=1 → loc_159a5 snap Y_start UP
        //   out_dir=0 → cur_y > old_y (moved down) → orig AX=0 → loc_15984 snap Y_end DOWN
        v2_vm_y_snap_tile_15972(vm, (int16_t)out_dir, di);
        collision_found = true;
    } else {
        if (v2_yvel_obj_search_15c93(vm, (uint16_t)filter, di, out_dir)) {
            // orig sub_15c93 at loc_15CBE/loc_15CD7 also restores si from ds:0x38 before
            // CARRY return. AX is 0 or 1 (direction). sub_15DA8 uses si=ds:0x38 as partner.
            uint16_t partner = vm.ds_read(DS_SCRATCH_38);
            // AX from sub_15c93: 1 = vel_diff < 0 (moved up), 0 = vel_diff > 0 (moved down).
            // Pass via out_dir to match orig.
            v2_vm_y_snap_obj_15DA8(vm, (int16_t)out_dir, partner, di);
            collision_found = true;
        }
    }
    if (collision_found) {
        di = vm.global_r(DS_CUR_OBJ);
        uint16_t si_38e = vm.global_r(DS_COLL_BIT_IDX);
        uint16_t mask = *(uint16_t*)(vm.shadow +(uint16_t)(si_38e - LUT_BIT_MASK));
        ObjRef{vm, di}.w16(OBJ_COLL_BITS, ObjRef{vm, di}.u16(OBJ_COLL_BITS) | mask);
    }
    return false; // ALWAYS CLC
}

// 0x3C (sub_15838): Collision check via sub_1584e + ds:0x38E increment.
// BOTH paths (collision and no-collision) add 2 to ds:0x38E.
// On collision: call-jump. On no collision: skip 2.
static void v2_vm_op_3C(V2VM& vm) {
    bool collision = v2_vm_collision_check_1584e(vm);
    // Both paths: ADD ds:38Eh, 2
    vm.ds_write(DS_COLL_BIT_IDX, vm.ds_read(DS_COLL_BIT_IDX) + 2);
    if (!collision) { vm.pc += 2; } else { v2_vm_do_call_jump(vm); }
}

// 0xB2 (sub_14e37): sub_153ea (3 bytes bit test) + conditional.
// If ne → skip 2, eq → call-jump.
static void v2_vm_op_B2(V2VM& vm) {
    uint16_t result = v2_vm_bittest_153ea(vm);
    if (result != v2_vm_accumulator) { vm.pc += 2; } else { v2_vm_do_call_jump(vm); }
}

// 0x7E (sub_1494b): Signed >= comparison with indirect value (2 bytes).
// acc >= val (signed) → jump, else skip 2.
static void v2_vm_op_7E(V2VM& vm) {
    uint16_t val = v2_vm_read_indirect(vm);
    int16_t dx = (int16_t)v2_vm_accumulator - (int16_t)val;
    if ((int16_t)v2_vm_accumulator >= (int16_t)val) {
        v2_vm_do_jump(vm);
    } else {
        vm.pc += 2;
    }
}

// 0x83 (sub_149c3): Signed < comparison with indirect value (2 bytes).
// acc < val (signed) → jump, acc >= val → skip 2. Opposite of 0x7E.
static void v2_vm_op_83(V2VM& vm) {
    uint16_t val = v2_vm_read_indirect(vm);
    if ((int16_t)v2_vm_accumulator < (int16_t)val) {
        v2_vm_do_jump(vm);
    } else {
        vm.pc += 2;
    }
}

// 0x91 (sub_146f6): Conditional add/subtract accumulator to/from ds:[addr].
// If NOT hflip (flag 0x40 clear) → ds:[addr] += acc (sub_14704)
// If hflip (flag 0x40 set) → ds:[addr] -= acc (sub_14771)
// Consumes 2 bytes (word address from bytecode).
static void v2_vm_op_91(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    uint16_t addr = vm.read_u16();
    if (!(ObjRef{vm, si}.u16(OBJ_FLAGS) & 0x40)) {
        // sub_14704: ds:[addr] += acc
        vm.ds_write(addr, vm.ds_read(addr) + v2_vm_accumulator);
    } else {
        // sub_14771: ds:[addr] -= acc
        vm.ds_write(addr, vm.ds_read(addr) - v2_vm_accumulator);
    }
}

// 0x98 (sub_14b52): Load accumulator from sub_15403 (indexed field bit test, 2 bytes).
// sub_15403: byte idx1 (mask), byte idx2 (field) → pattern B (ds:0x42-relative).
// si = ds:[idx2 - 0x6CBA] + ds:0x42; ax = ds:[si + 0x14E5] & ds:[idx1 - 0x6C34]; acc = 0 or 1.
static void v2_vm_op_98(V2VM& vm) {
    v2_vm_accumulator = v2_vm_bittest_15403(vm);
}

// 0xAD (sub_14de4): sub_153ea bit test (3 bytes) + if eq → skip 2, ne → jump.
// Opposite of 0xB2 (which does call-jump instead of jump).
static void v2_vm_op_AD(V2VM& vm) {
    uint16_t result = v2_vm_bittest_153ea(vm);
    if (result == v2_vm_accumulator) { vm.pc += 2; } else { v2_vm_do_jump(vm); }
}

// 0xCF (sub_152c6): Viewport bounds check on sub-object → outside viewport: jump, within: skip 2.
// Checks ds:[obj+0x1995] object's X/Y against viewport ds:0x44/0x46.
// PUSH 2 → if within: off_30C92[2] = skip 2, if outside: off_30C94[2] = jump
static void v2_vm_op_CF(V2VM& vm) {
    uint16_t si_obj = vm.global_r(DS_CUR_OBJ);
    uint16_t si = ObjRef{vm, si_obj}.u16(OBJ_PARTNER); // sub-object

    uint16_t vp_x = vm.ds_read(DS_VIEWPORT_X);
    uint16_t vp_y = vm.ds_read(DS_VIEWPORT_Y);
    uint16_t obj_x = ObjRef{vm, si}.u16(OBJ_WORLD_X);
    uint16_t obj_y = ObjRef{vm, si}.u16(OBJ_WORLD_Y);

    bool within = true;
    // X bounds: vp_x + 0x1F <= obj_x AND vp_x + 0x1F + 0x102 >= obj_x
    if ((int16_t)(vp_x + 0x1F) >= (int16_t)obj_x) within = false;
    if ((int16_t)(vp_x + 0x1F + 0x102) < (int16_t)obj_x) within = false;
    // Y bounds: vp_y + 0x1F <= obj_y AND vp_y + 0x1F + 0x72 >= obj_y
    if (within) {
        if ((int16_t)(vp_y + 0x1F) >= (int16_t)obj_y) within = false;
        if ((int16_t)(vp_y + 0x1F + 0x72) < (int16_t)obj_y) within = false;
    }

    // PUSH 2: off_30C92[2] = skip 2 (within), off_30C94[2] = jump (outside)
    if (within) { vm.pc += 2; } else { v2_vm_do_jump(vm); }
}

// 0x6A (sub_1488b): Unsigned >= comparison with INDIRECT value (2 bytes).
// CALL sub_1549a (read indirect, 2B) → acc >= val → jump, else skip 2.
static void v2_vm_op_6A(V2VM& vm) {
    uint16_t val = v2_vm_read_indirect(vm); // sub_1549a: 2 bytes
    if (v2_vm_accumulator >= val) {
        v2_vm_do_jump(vm);
    } else {
        vm.pc += 2;
    }
}

// 0x94 (sub_14763): Conditional add/sub acc to addr — OPPOSITE of 0x91.
// NOT hflip → subtract (sub_14771), hflip → add (sub_14704). 2 bytes.
static void v2_vm_op_94(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    uint16_t addr = vm.read_u16();
    if (!(ObjRef{vm, si}.u16(OBJ_FLAGS) & 0x40)) {
        // sub_14771: ds:[addr] -= acc
        vm.ds_write(addr, vm.ds_read(addr) - v2_vm_accumulator);
    } else {
        // sub_14704: ds:[addr] += acc
        vm.ds_write(addr, vm.ds_read(addr) + v2_vm_accumulator);
    }
}

// 0xA8 (sub_14d91): sub_153ea bit test (3 bytes). If ne → skip 2, eq → jump.
// sub_153ea: byte idx + word VALUE (bytecode literal, NOT ds:[addr]!) → test
static void v2_vm_op_A8(V2VM& vm) {
    uint16_t result = v2_vm_bittest_153ea(vm);
    if (result != v2_vm_accumulator) { vm.pc += 2; } else { v2_vm_do_jump(vm); }
}

// 0xB3 (sub_14e47): sub_15403 bit test (2B, pattern B). If ne → skip 2, eq → call-jump.
static void v2_vm_op_B3(V2VM& vm) {
    uint16_t result = v2_vm_bittest_15403(vm);
    if (result != v2_vm_accumulator) { vm.pc += 2; } else { v2_vm_do_call_jump(vm); }
}

// 0x0B (sub_1369c): Unconditional hflip. 0 bytes. Always flips.
// sub_1369c: MOV si, ds:42h; falls through to sub_136a0 (full hflip with sub-sprites).
static void v2_vm_op_0B(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    v2_vm_hflip_body_136a0(vm, si);
}

// 0x17 (sub_143f2): Set [obj+141D]=0, then read 2 signed bytes as X/Y velocity. 2 bytes.
static void v2_vm_op_17(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    ObjRef{vm, si}.w16(OBJ_ANIM_TABLE, 0);
    // loc_14415: read signed byte → X velocity, read signed byte → Y velocity
    int8_t vx = (int8_t)vm.es[vm.pc]; vm.pc++;
    ObjRef{vm, si}.w16(OBJ_VEL_X, (uint16_t)(int16_t)vx); // CBW: sign-extend
    int8_t vy = (int8_t)vm.es[vm.pc]; vm.pc++;
    ObjRef{vm, si}.w16(OBJ_VEL_Y, (uint16_t)(int16_t)vy);
}

static void v2_vm_pal_correct_10e99(V2VM& vm); // forward decl

// 0x3E (sub_14590): Clear palette base. 0 bytes.
// Clears ds:0x342-0x344, AND ds:0x7EFD & 0xFE, conditional ds:0x7F00, then sub_10e99.
static void v2_vm_op_3E(V2VM& vm) {
    vm.ds_write_b(DS_PAL_SHADE_R, 0);
    vm.ds_write_b(DS_PAL_SHADE_G, 0);
    vm.ds_write_b(DS_PAL_SHADE_B, 0);
    uint8_t flags = vm.shadow[DS_PAL_FLAGS] & 0xFE;
    vm.ds_write_b(DS_PAL_FLAGS, flags);
    if (flags == 0) {
        vm.ds_write(DS_PAL_SRC_PTR, DS_PAL_SRC);
    }
    vm.ds_write(DS_PAL_REQ, 4);
    v2_vm_pal_correct_10e99(vm);
}

// 0x29 (sub_15017): Write tile to map + mark dirty. 2 mode bytes + 3 dispatches.
// mode1: bits 0-2 = X dispatch, bits 3-5 = Y dispatch
// mode2: bits 0-2 = tile value dispatch
// Calls sub_141e0 (tile map write) + sub_13fc2 (mark tile dirty, update tracking)
static void v2_vm_op_29(V2VM& vm) {
    // Mode byte 1: X/Y via dual dispatch
    uint16_t word1 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode1 = (uint8_t)(word1 & 0xFF);
    bool ch_intr = false;
    uint16_t si = v2_vm_dispatch_30C98(vm, mode1, 0x501C, &ch_intr);       // X coord (tile units)
    if (ch_intr) { v2_vm_ch67_ub_guard(vm, "op29/X@0x501C: RETN onto PUSHed mode word"); return; }
    uint16_t di = v2_vm_dispatch_30C98(vm, mode1 >> 3, 0x5022, &ch_intr);  // Y coord (tile units)
    if (ch_intr) return;   // clean

    // Mode byte 2: tile value
    uint16_t word2 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode2 = (uint8_t)(word2 & 0xFF);
    uint16_t tile_val = v2_vm_dispatch_30C98(vm, mode2, 0x502B, &ch_intr);
    if (ch_intr) return;   // clean (no live pushes at the 3rd site)
    // №40: Y lives in DX (MOV dx,ax @0x5025) across the tile fetch; a ch4
    // Path1 fetch destroys DX via MUL edx, and MOV di,dx @0x5030 then loads
    // the multiply's high half as the Y coordinate — replicate that.
    if (vm.ch4_mul_clobber) di = vm.ch4_mul_dx;

    v2_vm_tile_write_141e0(vm, si, di, tile_val);
    v2_vm_tile_dirty_13fc2(vm, si, di, tile_val);   // sets si/di_track (di*4, w3)
}

// 0x2C (sub_15f2c): Collision search with type filter + jump. 3 bytes (1 mode + 2 target).
// Searches objects 0,2,4 for matching type + bounds overlap.
// On match: bx = jump target, stores matched obj. On no match: bx += 4 (3 params + 1 extra).
static void v2_vm_op_2C(V2VM& vm) {
    // ds:0x3AE = ds:[si+0x14E5] - 1 (self Y - 1)
    uint16_t self_si = vm.global_r(DS_CUR_OBJ);
    vm.ds_write(DS_SEARCH_Y, ObjRef{vm, self_si}.u16(OBJ_BBOX_Y0) - 1);

    // Read params: filter type index (1 byte) + jump target word (2 bytes)
    uint16_t ax_word = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint16_t filter_idx = ax_word & 0xFF;
    vm.ds_write(DS_SEARCH_FILTER, filter_idx);
    uint16_t jump_target = *(uint16_t*)(vm.es + vm.pc); vm.pc += 2;
    vm.ds_write(DS_SEARCH_JUMP, jump_target);

    // Search objects 0, 2, 4
    for (uint16_t si = 0; si < 6; si += 2) {
        if (ObjRef{vm, si}.u16(OBJ_CODE_SEG) == 0) continue;  // inactive
        if (si == self_si) continue;                   // skip self

        // Type match via sorted filter table at ds:[(uint16_t)(di - 0x6B34)]
        uint8_t obj_type = (uint8_t)ObjRef{vm, si}.u16(OBJ_TYPE_ID);
        uint16_t di = filter_idx;
        bool matched = false;
        for (;;) {
            uint8_t filt = vm.shadow[(uint16_t)(di - LUT_SCAN_FILTER)];
            if (obj_type < filt) break;     // below range → no match
            if (obj_type == filt) { matched = true; break; }
            di++;  // scan next entry
        }
        vm.di_track = di;   // orig: filter-scan stop position stays in DI
        if (!matched) continue;

        // Y bounds: 3AE >= [si+14E5] AND (3AE-1) < [si+150D]
        uint16_t y_ref = vm.ds_read(DS_SEARCH_Y);
        if (y_ref < ObjRef{vm, si}.u16(OBJ_BBOX_Y0)) continue;
        if ((uint16_t)(y_ref - 1) >= ObjRef{vm, si}.u16(OBJ_BBOX_Y1)) continue;

        // X bounds: [di+155D] >= [si+1535] AND [si+155D] >= [di+1535]
        uint16_t di2 = self_si;
        vm.di_track = di2;  // orig: MOV di,ds:42h before the X bbox
        if (ObjRef{vm, di2}.u16(OBJ_BBOX_X1) < ObjRef{vm, si}.u16(OBJ_BBOX_X0)) continue;
        if (ObjRef{vm, si}.u16(OBJ_BBOX_X1) < ObjRef{vm, di2}.u16(OBJ_BBOX_X0)) continue;

        // Match found
        vm.ds_write(DS_SEARCH_SI, si);
        ObjRef{vm, di2}.w16(OBJ_PARTNER, si);
        ObjRef{vm, di2}.w16(OBJ_ALT_PC, vm.pc);
        vm.pc = jump_target;
        return;
    }
    // No match — extra INC bx
    vm.pc += 1;
}

// 0x48 (sub_14fec): Position delta from dispatched coords. 1 mode byte + dispatch reads.
// Verified with seg000 lines 11685-11698.
// Reads mode byte, sub_15473(mode) → X target, sub_15470(mode) → Y target.
// DS writes: [obj+1945]=X_delta, [obj+196D]=Y_delta, [obj+141D]=0x100.
static void v2_vm_op_48(V2VM& vm) {
    // MOV ax, es:[bx]; INC bx — read mode byte
    uint16_t word = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode = (uint8_t)(word & 0xFF);
    // PUSH ax; CALL sub_15473 — dispatch X
    bool ch_intr = false;
    uint16_t x_pos = v2_vm_dispatch_30C98(vm, mode, 0x4FF1, &ch_intr);
    if (ch_intr) { v2_vm_ch67_ub_guard(vm, "op48/X@0x4FF1: RETN onto PUSHed mode word"); return; }
    // MOV si, ds:42h; SUB ax, [si+173Dh]; MOV [si+1945h], ax
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    ObjRef{vm, si}.w16(OBJ_VEL_X, x_pos - ObjRef{vm, si}.u16(OBJ_WORLD_X));
    // POP ax; CALL sub_15470 — dispatch Y (SHR ax,3 then dispatch)
    uint16_t y_pos = v2_vm_dispatch_30C98(vm, mode >> 3, 0x5001, &ch_intr);
    if (ch_intr) return;   // clean
    // MOV si, ds:42h; SUB ax, [si+1765h]; MOV [si+196Dh], ax
    ObjRef{vm, si}.w16(OBJ_VEL_Y, y_pos - ObjRef{vm, si}.u16(OBJ_WORLD_Y));
    // MOV [si+141Dh], 100h
    ObjRef{vm, si}.w16(OBJ_ANIM_TABLE, 0x100);
}

// 0x35 (sub_15e91): Collision search ALL objects (not just vikings). 3 bytes + 1 skip on miss.
// Like 0x2C but loop range is 0..ds:0x372 instead of 0..6.
// Verified with seg000 lines 14143-14201.
static void v2_vm_op_35(V2VM& vm) {
    uint16_t self_si = vm.global_r(DS_CUR_OBJ);
    vm.ds_write(DS_SEARCH_Y, ObjRef{vm, self_si}.u16(OBJ_BBOX_Y0) - 1);

    uint16_t ax_word = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint16_t filter_idx = ax_word & 0xFF;
    vm.ds_write(DS_SEARCH_FILTER, filter_idx);
    uint16_t jump_target = *(uint16_t*)(vm.es + vm.pc); vm.pc += 2;
    vm.ds_write(DS_SEARCH_JUMP, jump_target);

    uint16_t max_obj = vm.ds_read(DS_OBJ_COUNT);
    for (uint16_t si = 0; si == 0 || (int16_t)si < (int16_t)max_obj; si += 2) {   // orig do-while (sub_15e91 tail: ADD si,2; CMP si,[372]; JL)
        if (ObjRef{vm, si}.u16(OBJ_CODE_SEG) == 0) continue;
        if (si == self_si) continue;

        uint8_t obj_type = (uint8_t)ObjRef{vm, si}.u16(OBJ_TYPE_ID);
        uint16_t di = filter_idx;
        bool matched = false;
        for (;;) {
            uint8_t filt = vm.shadow[(uint16_t)(di - LUT_SCAN_FILTER)];
            if (obj_type < filt) break;       // JB: unsigned below
            if (obj_type == filt) { matched = true; break; }
            di++;
        }
        vm.di_track = di;   // orig: filter-scan stop position stays in DI
        if (!matched) continue;

        // Y bounds: signed JL comparisons (phase-B pilot: ObjRef views)
        ObjRef cand{vm, si};
        int16_t y_ref = (int16_t)vm.ds_read(DS_SEARCH_Y);
        if (y_ref < cand.bbox_y0()) continue;
        if ((int16_t)(uint16_t)(y_ref - 1) < cand.bbox_y1()) continue;

        // X bounds: signed JL comparisons
        ObjRef self{vm, self_si};
        vm.di_track = self.slot;  // orig 0x5EE3: MOV di,ds:42h before the X bbox
        if (self.bbox_x1() < cand.bbox_x0()) continue;
        if (cand.bbox_x1() < self.bbox_x0()) continue;

        // Match found
        vm.ds_write(DS_SEARCH_SI, si);
        self.set_partner(si);
        self.set_alt_pc(vm.pc);
        vm.pc = jump_target;
        return;
    }
    vm.pc += 1; // not found: skip 1 extra byte
}

// 0x2D (sub_15f25): Continue collision search from previous match. 0 bytes on miss.
// Resumes search from ds:0x3B0 + 2. On match: jump to ds:0x3AC. On miss: 0 bytes.
static void v2_vm_op_2D(V2VM& vm) {
    // DEC bx (original decrements PC by 1)
    vm.pc -= 1;
    uint16_t self_si = vm.global_r(DS_CUR_OBJ);
    uint16_t start_si = vm.ds_read(DS_SEARCH_SI);
    uint16_t filter_idx = vm.ds_read(DS_SEARCH_FILTER);

    for (uint16_t si = start_si + 2; si < 6; si += 2) {
        if (ObjRef{vm, si}.u16(OBJ_CODE_SEG) == 0) continue;
        if (si == self_si) continue;

        uint8_t obj_type = (uint8_t)ObjRef{vm, si}.u16(OBJ_TYPE_ID);
        uint16_t di = filter_idx;
        bool matched = false;
        for (;;) {
            uint8_t filt = vm.shadow[(uint16_t)(di - LUT_SCAN_FILTER)];
            if (obj_type < filt) break;
            if (obj_type == filt) { matched = true; break; }
            di++;
        }
        vm.di_track = di;   // orig: filter-scan stop position stays in DI
        if (!matched) continue;

        uint16_t y_ref = vm.ds_read(DS_SEARCH_Y);
        if (y_ref < ObjRef{vm, si}.u16(OBJ_BBOX_Y0)) continue;
        if ((uint16_t)(y_ref - 1) >= ObjRef{vm, si}.u16(OBJ_BBOX_Y1)) continue;

        uint16_t di2 = self_si;
        vm.di_track = di2;  // orig: MOV di,ds:42h before the X bbox
        if (ObjRef{vm, di2}.u16(OBJ_BBOX_X1) < ObjRef{vm, si}.u16(OBJ_BBOX_X0)) continue;
        if (ObjRef{vm, si}.u16(OBJ_BBOX_X1) < ObjRef{vm, di2}.u16(OBJ_BBOX_X0)) continue;

        vm.ds_write(DS_SEARCH_SI, si);
        ObjRef{vm, di2}.w16(OBJ_PARTNER, si);
        ObjRef{vm, di2}.w16(OBJ_ALT_PC, vm.pc);  // bx = B-1
        vm.pc = vm.ds_read(DS_SEARCH_JUMP);
        return;
    }
    // No match — INC bx restores PC
    vm.pc += 1;
}

// sub_10e99: Palette color correction. Copies ds:0x7F02 → ds:0x8202 (256×3 bytes)
// with per-channel subtraction and clamping to [0, 0x3F].
// Color offsets: R = ds:0x342 | ds:0x345, G = ds:0x343 | ds:0x346, B = ds:0x344 | ds:0x347.
// First 3 bytes get color correction, then 45 bytes copied raw, then 240×3 bytes corrected.
static void v2_vm_pal_correct_10e99(V2VM& vm) {
    uint8_t r_off = vm.shadow[DS_PAL_SHADE_R] | vm.shadow[DS_PAL_SHADE_R2];
    uint8_t g_off = vm.shadow[DS_PAL_SHADE_G] | vm.shadow[DS_PAL_SHADE_G2];
    uint8_t b_off = vm.shadow[DS_PAL_SHADE_B] | vm.shadow[DS_PAL_SHADE_B2];

    // Note: original m2c sub_10e99 doesn't correctly update palette buffer
    // (STOSB/es segment issue in m2c translation). v2 implementation is more correct.

    uint16_t si = DS_PAL_SRC; // source
    uint16_t di = DS_PAL_OUT; // destination

    // First iteration: 3 corrected bytes + 45 raw bytes
    // R
    int8_t v = (int8_t)(vm.shadow[si++] - r_off);
    vm.shadow[di++] = (v < 0) ? 0 : ((v & 0x40) ? 0x3F : (uint8_t)v);
    // G
    v = (int8_t)(vm.shadow[si++] - g_off);
    vm.shadow[di++] = (v < 0) ? 0 : ((v & 0x40) ? 0x3F : (uint8_t)v);
    // B
    v = (int8_t)(vm.shadow[si++] - b_off);
    vm.shadow[di++] = (v < 0) ? 0 : ((v & 0x40) ? 0x3F : (uint8_t)v);
    // 45 raw bytes
    memcpy(vm.shadow + di, vm.shadow + si, 0x2D);
    si += 0x2D;
    di += 0x2D;

    // Remaining 239 iterations: 3 corrected bytes each (colors 16-254)
    // Original: MOV cx, 0F0h (240); LOOP DEC-before-check → 239 iterations. Color 255 NOT processed.
    for (int i = 0; i < 239; i++) {
        v = (int8_t)(vm.shadow[si++] - r_off);
        vm.shadow[di++] = (v < 0) ? 0 : ((v & 0x40) ? 0x3F : (uint8_t)v);
        v = (int8_t)(vm.shadow[si++] - g_off);
        vm.shadow[di++] = (v < 0) ? 0 : ((v & 0x40) ? 0x3F : (uint8_t)v);
        v = (int8_t)(vm.shadow[si++] - b_off);
        vm.shadow[di++] = (v < 0) ? 0 : ((v & 0x40) ? 0x3F : (uint8_t)v);
    }
}

// Helper: compute indexed+1995 write target address.
// Pattern A: idx byte → di = ds:[idx-0x6CBA]; si = ds:0x42; di += ds:[si+0x1995]; target = di + 0x14E5
// Used by 0x5B (ADD), 0x5E (SUB), 0x64 (OR), 0x67 (AND) indexed+1995 variants.
static uint16_t v2_vm_indexed_1995_target(V2VM& vm) {
    uint16_t idx = vm.read_u8();
    uint16_t di = *(uint16_t*)(vm.shadow +(uint16_t)(idx - LUT_FIELD_OFF));
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    di += ObjRef{vm, si}.u16(OBJ_PARTNER);
    vm.si_track = si;               // orig: MOV si,ds:42h
    vm.di_track = di;               // orig: slot address left in DI (task #15)
    return (uint16_t)(di + OBJ_FIELD_BASE);
}

// 0x5B (sub_14721): ADD acc to indexed+1995 field. 1 byte.
static void v2_vm_op_5B(V2VM& vm) {
    uint16_t addr = v2_vm_indexed_1995_target(vm);
    vm.ds_write(addr, vm.ds_read(addr) + v2_vm_accumulator);
}

// 0x5E (sub_1478b): SUB acc from indexed+1995 field. 1 byte.
static void v2_vm_op_5E(V2VM& vm) {
    uint16_t addr = v2_vm_indexed_1995_target(vm);
    vm.ds_write(addr, vm.ds_read(addr) - v2_vm_accumulator);
}

// 0x64 (sub_1480b): OR acc into indexed+1995 field. 1 byte.
static void v2_vm_op_64(V2VM& vm) {
    uint16_t addr = v2_vm_indexed_1995_target(vm);
    vm.ds_write(addr, vm.ds_read(addr) | v2_vm_accumulator);
}

// 0x66 (sub_1483f): XOR acc with ds:[addr]. 2 bytes (direct address).
// si = es:[bx]; bx += 2; ds:[si] ^= acc
static void v2_vm_op_66(V2VM& vm) {
    uint16_t addr = vm.read_u16();
    vm.ds_write(addr, vm.ds_read(addr) ^ v2_vm_accumulator);
}

// Helper: compute indexed field B target address (ds:0x42-relative).
// Pattern B: idx byte → si = ds:[idx-0x6CBA]; si += ds:0x42; target = si + 0x14E5
// Used by 0x90, 0x93 conditional ADD/SUB variants.
static uint16_t v2_vm_indexed_field_b_target(V2VM& vm) {
    uint16_t idx = vm.read_u8();
    uint16_t si = *(uint16_t*)(vm.shadow +(uint16_t)(idx - LUT_FIELD_OFF));
    si += vm.global_r(DS_CUR_OBJ);
    return (uint16_t)(si + OBJ_BBOX_Y0);
}

// sub_146de: indexed field ADD (pattern B). 1 byte.
static void v2_vm_field_add_146de(V2VM& vm) {
    uint16_t addr = v2_vm_indexed_field_b_target(vm);
    vm.ds_write(addr, vm.ds_read(addr) + v2_vm_accumulator);
}

// sub_1474b: indexed field SUB (pattern B). 1 byte.
static void v2_vm_field_sub_1474b(V2VM& vm) {
    uint16_t addr = v2_vm_indexed_field_b_target(vm);
    vm.ds_write(addr, vm.ds_read(addr) - v2_vm_accumulator);
}

// 0x6E (sub_148d3): indexed field (sub_15485, 1B), unsigned acc < val → jump, else skip 2.
static void v2_vm_op_6E(V2VM& vm) {
    uint16_t val = v2_vm_read_indexed_field(vm);
    if (v2_vm_accumulator < val)
        v2_vm_do_jump(vm);
    else
        vm.pc += 2;
}

// 0x70 (sub_148f7): indexed+1995 (sub_154a3, 1B), unsigned acc < val → jump, else skip 2.
static void v2_vm_op_70(V2VM& vm) {
    uint16_t val = v2_vm_read_indexed_field_1995(vm);
    if (v2_vm_accumulator < val)
        v2_vm_do_jump(vm);
    else
        vm.pc += 2;
}

// 0x75 (sub_14a3b): indexed+1995 (sub_154a3, 1B), val != acc → skip 2, val == acc → jump.
static void v2_vm_op_75(V2VM& vm) {
    uint16_t val = v2_vm_read_indexed_field_1995(vm);
    if (val != v2_vm_accumulator)
        vm.pc += 2;
    else
        v2_vm_do_jump(vm);
}

// 0x7A (sub_14a8b): indexed+1995 (sub_154a3, 1B), val == acc → skip 2, val != acc → jump.
static void v2_vm_op_7A(V2VM& vm) {
    uint16_t val = v2_vm_read_indexed_field_1995(vm);
    if (val == v2_vm_accumulator)
        vm.pc += 2;
    else
        v2_vm_do_jump(vm);
}

// 0x84 (sub_149db): indexed+1995 (sub_154a3, 1B), signed acc >= val → skip 2, else → jump.
static void v2_vm_op_84(V2VM& vm) {
    uint16_t val = v2_vm_read_indexed_field_1995(vm);
    if ((int16_t)v2_vm_accumulator >= (int16_t)val)
        vm.pc += 2;
    else
        v2_vm_do_jump(vm);
}

// 0x90 (sub_146d0): conditional ADD/SUB based on bit 0x40 flag. 1 byte.
// If bit 0x40 clear → ADD (sub_146de). If set → SUB (sub_1474b).
static void v2_vm_op_90(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    if (ObjRef{vm, si}.u16(OBJ_FLAGS) & 0x40)
        v2_vm_field_sub_1474b(vm);
    else
        v2_vm_field_add_146de(vm);
}

// 0x93 (sub_1473d): conditional SUB/ADD — opposite of 0x90. 1 byte.
// If bit 0x40 clear → SUB (sub_1474b). If set → ADD (sub_146de).
static void v2_vm_op_93(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    if (ObjRef{vm, si}.u16(OBJ_FLAGS) & 0x40)
        v2_vm_field_add_146de(vm);
    else
        v2_vm_field_sub_1474b(vm);
}

// 0x92 (sub_14713): hflip conditional ADD/SUB indexed+1995. 1 byte.
// Verified with seg000 lines 9772-9775.
// bit 0x40 clear → ADD (v2_vm_op_5B), bit 0x40 set → SUB (v2_vm_op_5E)
static void v2_vm_op_92(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    if (ObjRef{vm, si}.u16(OBJ_FLAGS) & 0x40)
        v2_vm_op_5E(vm); // SUB indexed+1995
    else
        v2_vm_op_5B(vm); // ADD indexed+1995
}

// 0x95 (sub_1477d): hflip conditional SUB/ADD indexed+1995. 1 byte. Opposite of 0x92.
// Verified with seg000 lines 9854-9857.
static void v2_vm_op_95(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    if (ObjRef{vm, si}.u16(OBJ_FLAGS) & 0x40)
        v2_vm_op_5B(vm); // ADD indexed+1995
    else
        v2_vm_op_5E(vm); // SUB indexed+1995
}

// 0xCE (sub_152d6): Viewport visibility check. 2 bytes (jump target).
// Checks if object at ds:0x42 is within extended viewport bounds.
// In viewport → off_30C92[2] = skip 2. Not in viewport → off_30C94[2] = jump.
// Viewport check: (ds:0x44+0x1F < obj_X < ds:0x44+0x121) AND (ds:0x46+0x1F < obj_Y < ds:0x46+0x91)
static void v2_vm_op_CE(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    uint16_t obj_x = ObjRef{vm, si}.u16(OBJ_WORLD_X);
    uint16_t obj_y = ObjRef{vm, si}.u16(OBJ_WORLD_Y);
    uint16_t vp_x = vm.ds_read(DS_VIEWPORT_X);
    uint16_t vp_y = vm.ds_read(DS_VIEWPORT_Y);

    // Check X: (vp_x + 0x1F) < obj_x AND obj_x < (vp_x + 0x121)
    // Check Y: (vp_y + 0x1F) < obj_y AND obj_y < (vp_y + 0x91)
    bool in_viewport = true;
    int16_t ax = (int16_t)(vp_x + 0x1F);
    if (ax >= (int16_t)obj_x) in_viewport = false;
    else {
        ax += 0x102;
        if (ax < (int16_t)obj_x) in_viewport = false;
    }
    if (in_viewport) {
        ax = (int16_t)(vp_y + 0x1F);
        if (ax >= (int16_t)obj_y) in_viewport = false;
        else {
            ax += 0x72;
            if (ax < (int16_t)obj_y) in_viewport = false;
        }
    }

    if (in_viewport) {
        // off_30C92[2] = loc_15318 = skip 2
        vm.pc += 2;
    } else {
        // off_30C94[2] = sub_142cf = jump
        v2_vm_do_jump(vm);
    }
}

// 0x4C (sub_14561): Set color shading. 3 bytes (RGB offsets).
// Reads 3 bytes, SHL each by 1, stores to ds:0x345-347.
// Sets ds:0x7EFD |= 2, ds:0x7EFE = 4, ds:0x7F00 = 0x8202.
// Then calls sub_10e99 (palette color correction).
static void v2_vm_op_4C(V2VM& vm) {
    uint8_t r = vm.read_u8();
    vm.ds_write_b(DS_PAL_SHADE_R2, (uint8_t)(r << 1));
    uint8_t g = vm.read_u8();
    vm.ds_write_b(DS_PAL_SHADE_G2, (uint8_t)(g << 1));
    uint8_t b = vm.read_u8();
    vm.ds_write_b(DS_PAL_SHADE_B2, (uint8_t)(b << 1));
    uint8_t flags = vm.shadow[DS_PAL_FLAGS];
    vm.ds_write_b(DS_PAL_FLAGS, flags | 2);
    vm.ds_write(DS_PAL_REQ, 4);
    vm.ds_write(DS_PAL_SRC_PTR, DS_PAL_OUT);
    v2_vm_pal_correct_10e99(vm);
}

// 0x4D (sub_145b5): Clear color shading. 0 bytes.
// Clears ds:0x345-347 to 0, AND ds:0x7EFD with 0xFD.
// If result is 0: ds:0x7F00 = 0x7F02. ds:0x7EFE = 4.
// Then calls sub_10e99 (palette color correction).
static void v2_vm_op_4D(V2VM& vm) {
    vm.ds_write_b(DS_PAL_SHADE_R2, 0);
    vm.ds_write_b(DS_PAL_SHADE_G2, 0);
    vm.ds_write_b(DS_PAL_SHADE_B2, 0);
    uint8_t flags = vm.shadow[DS_PAL_FLAGS] & 0xFD;
    vm.ds_write_b(DS_PAL_FLAGS, flags);
    if (flags == 0) {
        vm.ds_write(DS_PAL_SRC_PTR, DS_PAL_SRC);
    }
    vm.ds_write(DS_PAL_REQ, 4);
    v2_vm_pal_correct_10e99(vm);
}

// 0x3B (sub_1524a): Set sprite/animation params. 2 bytes.
// ds:0x39C = ax & 0xFF; ds:0x3A0 = 0; ds:0x3A4 = (ax >> 6) & 0x3FC
static void v2_vm_op_3B(V2VM& vm) {
    uint16_t ax = vm.read_u16();
    vm.ds_write(DS_SHAKE_SRC_Y, ax & 0xFF);
    vm.ds_write(DS_SHAKE_Y, 0);
    vm.ds_write(DS_SHAKE_GATE_Y, (ax >> 6) & 0x3FC);
}

// 0x2A (sub_15078): Tilemap modification — set lower bits. 2 mode bytes + 3 dispatches.
// Reads X/Y position + tile index. Reads current tile, keeps upper 6 bits, ORs new lower 10 bits.
// Calls sub_141e0 (write) + sub_13fc2 (mark dirty).
static void v2_vm_op_2A(V2VM& vm) {
    // Mode byte 1: X/Y position via dual dispatch
    uint16_t word1 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode1 = (uint8_t)(word1 & 0xFF);
    bool ch_intr = false;
    uint16_t x_pos = v2_vm_dispatch_30C98(vm, mode1, 0x507D, &ch_intr);
    if (ch_intr) { v2_vm_ch67_ub_guard(vm, "op2A/X@0x507D: RETN onto PUSHed mode word"); return; }
    vm.ds_write(DS_TEXT_COL, x_pos);
    uint16_t y_pos = v2_vm_dispatch_30C98(vm, mode1 >> 3, 0x5084, &ch_intr);
    if (ch_intr) return;   // clean
    vm.ds_write(DS_TEXT_ROW, y_pos);
    // Mode byte 2: tile index via single dispatch
    uint16_t word2 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode2 = (uint8_t)(word2 & 0xFF);
    uint16_t tile_val = v2_vm_dispatch_30C98(vm, mode2, 0x508E, &ch_intr);
    if (ch_intr) return;   // clean
    vm.ds_write(DS_SCRATCH_34, tile_val);
    // sub_141ba: read current tile, AND FC00 (keep upper flags), OR with tile_val
    uint16_t si = x_pos, di = y_pos;
    uint16_t current = v2_vm_tile_read_141ba(vm, si, di);
    uint16_t merged = (current & 0xFC00) | tile_val;
    // sub_141e0: write merged tile back
    v2_vm_tile_write_141e0(vm, si, di, merged);
    // sub_13fc2: mark tile dirty
    v2_vm_tile_dirty_13fc2(vm, si, di, merged);
}

// 0x2B (sub_15039): Set upper tile flags. 2 mode bytes + 3 dispatches.
// Dispatches X, Y, tile_val. Transforms tile_val (xchg ah,al; shl 2; and FC00) to upper 6 bits.
// Reads current tile via sub_141b3 (& 0x3FF = lower 10 bits), ORs with new flags.
// Writes back via sub_141e0. No sub_13fc2 call.
static void v2_vm_op_2B(V2VM& vm) {
    // Mode byte 1: X/Y via dual dispatch
    uint16_t word1 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode1 = (uint8_t)(word1 & 0xFF);
    bool ch_intr = false;
    uint16_t x_pos = v2_vm_dispatch_30C98(vm, mode1, 0x503E, &ch_intr);
    if (ch_intr) { v2_vm_ch67_ub_guard(vm, "op2B/X@0x503E: RETN onto PUSHed mode word"); return; }
    vm.ds_write(DS_TEXT_COL, x_pos);
    uint16_t y_pos = v2_vm_dispatch_30C98(vm, mode1 >> 3, 0x5045, &ch_intr);
    if (ch_intr) return;   // clean
    vm.ds_write(DS_TEXT_ROW, y_pos);
    // Mode byte 2: tile flags value
    uint16_t word2 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode2 = (uint8_t)(word2 & 0xFF);
    uint16_t tile_raw = v2_vm_dispatch_30C98(vm, mode2, 0x504F, &ch_intr);
    if (ch_intr) return;   // clean
    // Transform: xchg ah,al → shl ax,2 → and ax,0xFC00
    uint16_t swapped = (uint16_t)((tile_raw >> 8) | (tile_raw << 8));
    uint16_t transformed = (swapped << 2) & 0xFC00;
    vm.ds_write(DS_SCRATCH_34, transformed);
    // sub_141b3: read current tile (& 0x3FF = lower 10 bits)
    uint16_t si = x_pos, di = y_pos;
    uint16_t current_low = v2_vm_tile_low_141b3(vm, si, di);
    uint16_t merged = current_low | transformed;
    // sub_141e0: write merged tile back
    v2_vm_tile_write_141e0(vm, si, di, merged);
    // No sub_13fc2 call in sub_15039
    // orig re-reads si=[0x6C] (0x506C) / di=[0x6E] (0x5070) before the
    // PUSH/POP-clean sub_141e0 — those are the exit registers (task #15).
    vm.si_track = vm.ds_read(DS_TEXT_COL);
    vm.di_track = vm.ds_read(DS_TEXT_ROW);
}

// 0x28 (sub_14f27): Tile-aligned position write. 2 mode bytes + 4 dispatches.
// Mode1: read X/Y from off_30C98, align to 16px grid (& 0xFFF0 | 8)
// Mode2: write via sub_154bf (X), loc_154bc (Y)
static void v2_vm_op_28(V2VM& vm) {
    // Read mode1 byte
    uint16_t word1 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode1 = (uint8_t)(word1 & 0xFF);
    bool ch_intr = false;
    // Dispatch X: (mode1 & 7) → align to tile
    uint16_t cx_val = (v2_vm_dispatch_30C98(vm, mode1, 0x4F2F, &ch_intr) & 0xFFF0) | 8;
    if (ch_intr) { v2_vm_ch67_ub_guard(vm, "op28/X@0x4F2F: RETN onto PUSHed mode word"); return; }
    // Dispatch Y: ((mode1 >> 3) & 7) → align to tile
    uint16_t dx_val = (v2_vm_dispatch_30C98(vm, mode1 >> 3, 0x4F3B, &ch_intr) & 0xFFF0) | 8;
    if (ch_intr) return;   // clean
    // Read mode2 byte
    uint8_t mode2 = vm.read_u8();
    // sub_154bf(cx_val, mode2) — X write
    v2_vm_setter_154bf(vm, cx_val, mode2);
    // loc_154bc: SHR mode2,3 → sub_154bf(dx_val, mode2>>3) — Y write
    v2_vm_setter_154bf(vm, dx_val, mode2 >> 3);
}

// Helper: collision search loop (shared by 0xD0, 0xD1, 0x35, 0x36).
// Iterates objects from si_start, checks type/bounds match, sets ds:0x3B0/0x1995/0x137D.
static void v2_vm_collision_search_loop(V2VM& vm, uint16_t si_start) {
    uint16_t table_end = vm.global_r(DS_OBJ_COUNT);
    uint16_t di = vm.global_r(DS_CUR_OBJ);

    for (uint16_t si = si_start + 2; (int16_t)si < (int16_t)table_end; si += 2) {
        if (ObjRef{vm, si}.u16(OBJ_CODE_SEG) == 0) continue;
        if (si == di) continue;
        // Type match
        uint8_t obj_type = (uint8_t)ObjRef{vm, si}.u16(OBJ_TYPE_ID);
        uint16_t flt = vm.ds_read(DS_SEARCH_FILTER);
        bool match = false;
        while (true) {
            uint8_t fval = *(uint8_t*)(vm.shadow +(uint16_t)(flt - LUT_SCAN_FILTER));
            if (obj_type < fval) break;
            if (obj_type == fval) { match = true; break; }
            flt++;
        }
        if (!match) continue;
        // Bounds check
        if ((int16_t)vm.ds_read(DS_SEARCH_Y) < (int16_t)ObjRef{vm, si}.u16(OBJ_BBOX_Y0)) continue;
        if ((int16_t)(vm.ds_read(DS_SEARCH_Y) - 1) < (int16_t)ObjRef{vm, si}.u16(OBJ_BBOX_Y1)) continue;
        if ((int16_t)ObjRef{vm, di}.u16(OBJ_BBOX_X1) < (int16_t)ObjRef{vm, si}.u16(OBJ_BBOX_X0)) continue;
        if ((int16_t)ObjRef{vm, si}.u16(OBJ_BBOX_X1) < (int16_t)ObjRef{vm, di}.u16(OBJ_BBOX_X0)) continue;
        // Match found
        vm.ds_write(DS_SEARCH_SI, si);
        ObjRef{vm, di}.w16(OBJ_PARTNER, si);
        ObjRef{vm, di}.w16(OBJ_ALT_PC, vm.pc);
        vm.pc = vm.ds_read(DS_SEARCH_JUMP);
        return;
    }
    // No match: INC bx (extra byte consumed — original has INC bx after loop exit)
    vm.pc += 1;
}

// 0xD0 (sub_15e7c): Collision search. 3 bytes consumed (1 filter + 2 target addr).
// Sets up ds:0x3AE (Y bound), ds:0x3AA (filter), ds:0x3AC (jump target), then searches.
static void v2_vm_op_D0(V2VM& vm) {
    uint16_t si = vm.global_r(DS_CUR_OBJ);
    vm.ds_write(DS_SEARCH_Y, ObjRef{vm, si}.u16(OBJ_BBOX_Y1) + 1);
    // Read 1 byte filter → ds:0x3AA
    uint8_t filter = vm.read_u8();
    vm.ds_write(DS_SEARCH_FILTER, filter);
    // Read 2 bytes jump target → ds:0x3AC
    uint16_t target = vm.read_u16();
    vm.ds_write(DS_SEARCH_JUMP, target);
    // Search from si=0
    v2_vm_collision_search_loop(vm, 0xFFFE); // -2 so first iteration = 0
}

// 0xD1 (sub_15f17): Vikings-only collision search (unsigned comparisons). 3 bytes.
// DIFFERENT from D0: loop limit si<6 (3 vikings only), unsigned JB/JNB for Y bounds,
// inverted second Y check (JNB = skip if >=, NOT JL = skip if <).
static void v2_vm_op_D1(V2VM& vm) {
    uint16_t si_self = vm.global_r(DS_CUR_OBJ);
    vm.ds_write(DS_SEARCH_Y, ObjRef{vm, si_self}.u16(OBJ_BBOX_Y1) + 1);
    uint8_t filter = vm.read_u8();
    vm.ds_write(DS_SEARCH_FILTER, filter);
    uint16_t target = vm.read_u16();
    vm.ds_write(DS_SEARCH_JUMP, target);
    // D1 search loop: vikings only (si<6), unsigned comparisons
    for (uint16_t si = 0; si < 6; si += 2) {
        if (ObjRef{vm, si}.u16(OBJ_CODE_SEG) == 0) continue;
        if (si == si_self) continue;
        // Type match (same as D0)
        uint8_t obj_type = (uint8_t)ObjRef{vm, si}.u16(OBJ_TYPE_ID);
        uint16_t flt = vm.ds_read(DS_SEARCH_FILTER);
        bool match = false;
        while (true) {
            uint8_t fval = *(uint8_t*)(vm.shadow +(uint16_t)(flt - LUT_SCAN_FILTER));
            if (obj_type < fval) break;  // JB (unsigned)
            if (obj_type == fval) { match = true; break; }
            flt++;
        }
        if (!match) continue;
        // Y bounds: unsigned, inverted second check
        uint16_t y_ref = vm.ds_read(DS_SEARCH_Y);
        if (y_ref < ObjRef{vm, si}.u16(OBJ_BBOX_Y0)) continue;  // JB: unsigned <
        if ((uint16_t)(y_ref - 1) >= ObjRef{vm, si}.u16(OBJ_BBOX_Y1)) continue;  // JNB: unsigned >=
        // X bounds: unsigned
        if (ObjRef{vm, si_self}.u16(OBJ_BBOX_X1) < ObjRef{vm, si}.u16(OBJ_BBOX_X0)) continue;  // JB
        if (ObjRef{vm, si}.u16(OBJ_BBOX_X1) < ObjRef{vm, si_self}.u16(OBJ_BBOX_X0)) continue;  // JB
        // Match found
        vm.ds_write(DS_SEARCH_SI, si);
        ObjRef{vm, si_self}.w16(OBJ_PARTNER, si);
        ObjRef{vm, si_self}.w16(OBJ_ALT_PC, vm.pc);
        vm.pc = vm.ds_read(DS_SEARCH_JUMP);
        return;
    }
    // No match: INC bx (skip 1 extra byte)
    vm.pc += 1;
}

// 0x43 (sub_1267b): Command buffer write type=4. 0 bytes.
static void v2_vm_op_43(V2VM& vm) {
    uint16_t bx_cmd = vm.ds_read(DS_CMD_WRITE);
    vm.ds_write(bx_cmd + DS_CMD_BUF, 4);
    vm.ds_write(DS_CMD_WRITE, bx_cmd + 2);
}

// sub_163ac: Tile type check for platform detection. 0 bytes. Sets carry.
// sub_163ac: Exact tile check chain. 3 sub_14199 calls with conditional logic.
static bool v2_vm_platform_check_163ac(V2VM& vm) {
    uint16_t obj = vm.global_r(DS_CUR_OBJ);
    uint16_t si_x;
    if (!(ObjRef{vm, obj}.u16(OBJ_FLAGS) & 0x40)) {
        si_x = ObjRef{vm, obj}.u16(OBJ_WORLD_X) + 0x10;
    } else {
        si_x = ObjRef{vm, obj}.u16(OBJ_WORLD_X) - 0x10;
    }
    uint16_t di_y = ObjRef{vm, obj}.u16(OBJ_BBOX_Y1);

    // Helper: tile type at (si, di) via sub_14199
    auto tile_type_at = [&](uint16_t sx, uint16_t dy) -> uint16_t {
        uint16_t tv = v2_vm_tile_read_141ba(vm, sx >> 4, dy >> 4);
        return (tv & 0xFC00) >> 10;
    };

    // Check 1: tile at (si_x, di_y)
    // (sub_14199 is PUSH si,di balanced; the orig DI register follows the
    //  local di variable through the branches — task #15 tracking below.)
    uint16_t ax = tile_type_at(si_x, di_y);
    vm.di_track = di_y;
    if (ax >= 0x30) return true; // carry

    if (ax == 1) {
        // Type 1: check tile above (di_y - 0x10)
        ax = tile_type_at(si_x, (uint16_t)(di_y - 0x10));
        vm.di_track = (uint16_t)(di_y - 0x10);
        if (ax >= 0x30) return true;
        if (ax == 0 || ax == 0x0C || ax == 3) return true;
        // Fall through to check 2
    }

    // Check 2: tile at original X position (si from obj+0x173D, NOT si_x)
    // Original reloads: di = ds:0x42; di = ds:[di+0x150D]; si preserved from check 1
    uint16_t di_y2 = vm.ds_read(vm.global_r(DS_CUR_OBJ) + OBJ_BBOX_Y1);
    ax = tile_type_at(si_x, di_y2);
    vm.di_track = di_y2;
    if (ax == 0 || ax == 0x0C || ax == 3) {
        // Check 3: tile below (di_y2 + 0x10)
        ax = tile_type_at(si_x, (uint16_t)(di_y2 + 0x10));
        vm.di_track = (uint16_t)(di_y2 + 0x10);
        if (ax >= 0x30) return true;
        if (ax == 1 || ax == 5 || ax == 0x20 || ax == 4 || ax == 2) return true;
        return false; // no carry
    }
    return false; // no carry
}

// 0x13 (sub_1434c): Level/palette command. 3 bytes consumed (always ADD bx,3).
// al byte determines action: 0xD9=palette copy, 0x11=text menu, 0x01=level transition.
// All paths end with ADD bx,3.
static void v2_vm_op_13(V2VM& vm) {
    uint16_t word = *(uint16_t*)(vm.es + vm.pc);
    uint8_t al = (uint8_t)(word & 0xFF);

    if (al == 0xD9) {
        // Palette copy: es:[bx+1] is a POINTER (offset in bytecode) to 48 bytes of palette data.
        // Original: MOV si, es:[bx+1]; swap ds/es; REP MOVSD from ds:si to es:8142 (48 bytes)
        uint16_t src_ptr = *(uint16_t*)(vm.es + vm.pc + 1); // read pointer value
        for (int i = 0; i < 48; i++) {
            vm.ds_write_b(DS_PAL_SRC_C192 + i, vm.es[src_ptr + i]);
        }
        for (int i = 0; i < 48; i++) {
            vm.ds_write_b(DS_PAL_SRC_C224 + i, vm.es[src_ptr + i]);
        }
        // sub_10e99: palette color correction (copies 7F02 → 8202 with shading)
        v2_vm_pal_correct_10e99(vm);
        vm.ds_write(DS_PAL_REQ, 4);
        vm.ds_write(DS_PAL_SRC_PTR, DS_PAL_OUT);
    } else if (al == 0x11) {
        // Orig sub_1434c loc_14396 — exact semantic translation to v2 bifurcated buffers.
        //
        // Orig VGA layout: HUD at VGA[0..~0x1580] (64 rows × 86-byte pitch), viewport
        // page areas at higher offsets (0x2ADC = page-0 start). HUD displayed via CRTC
        // line compare at row 176; viewport via CRTC start address (default 0x2ADC).
        //
        // Orig sequence:
        //   1. MOVSB src=0,    dst=0x2ADC, cnt=0x1600  ; copy HUD VGA bytes → viewport page-0 start
        //   2. MOVSB src=0,    dst=0x70BC, cnt=0x1600  ; copy HUD → another viewport page area
        //   3. STOSB di=0,     cnt=0x2ADC, val=0       ; clear HUD area + buffer
        //   4. STOSB di=0x40DC, cnt=0x2FE0, val=0      ; clear viewport page-1 area
        //   5. STOSB di=0x86BC, cnt=0x7000, val=0      ; clear viewport page-2 area
        //
        // Net visual effect: HUD picture COPIED to top of viewport, HUD cleared.
        // = "picture moves from HUD area UP to viewport top".
        //
        // V2 architecture: v2_hud_buf (320×64) holds HUD; v2_render_buf (320×176) holds
        // viewport. Translate orig's intermixed VGA ops to per-buffer ops:
        //   - Copy v2_hud_buf → v2_render_buf top 64 rows (viewport top gets HUD picture)
        //   - Clear v2_hud_buf (HUD area emptied)
        //   - Clear v2_render_buf rows 64..176 (rest of viewport cleared)
        extern uint8_t v2_render_buf[320*200];
        extern uint8_t v2_hud_buf[320*64];
        // Clear HUD area (= orig STOSB di=0..0x2ADC head part)
        memset(v2_hud_buf, 0, 320 * 64);
        // shadow-VGA: replay the orig 5-op VGA sequence into the shadow VGA verbatim.
        {
            extern void v2_vga_copy_span(uint16_t dst, uint16_t src, uint16_t nbytes);
            extern void v2_vga_glyph_px(uint32_t addr, uint32_t plane, uint8_t val);
            extern void v2_vga_fill_span(uint16_t dst, uint32_t nbytes, uint8_t val);
            (void)v2_vga_glyph_px;
            v2_vga_copy_span(0x2ADC, 0x0000, 0x1600);
            v2_vga_copy_span(0x70BC, 0x0000, 0x1600);
            v2_vga_fill_span(0x0000, 0x2ADC, 0);
            v2_vga_fill_span(0x40DC, 0x2FE0, 0);
            v2_vga_fill_span(0x86BC, 0x7000, 0);
        }
    } else if (al == 0x01) {
        // Orig sub_1434c loc_143eb → JMP loc_10E35: GAME EXIT.
        // loc_10E35 (eip 0x0E35) frees all DOS memory blocks (5× INT 21h 0x4900),
        // closes data file, calls sub_1686F + sub_1292F, then INT 21h 0x4C00 (DOS exit).
        // Used when user selects "Quit" from menu.
        // V2: trigger graceful exit similar to orig behavior.
        extern bool need_quit; need_quit = true; SDL_Delay(50); _exit(0);
    }

    // All paths: ADD bx, 3
    vm.pc += 3;
}

// 0x4E (sub_144fd): sub_163ac tile check + off_30C8E[0]. 0 bytes.
static void v2_vm_op_4E(V2VM& vm) {
    vm.carry = v2_vm_platform_check_163ac(vm);
    // off_30C8E[0] = loc_144e9: no carry → skip 2, carry → jump
    uint16_t cs_addr = *(uint16_t*)(vm.shadow +DS_VM_DISPATCH_TBL + 0);
    if (cs_addr == 0x44E9) {
        if (!vm.carry) { vm.pc += 2; } else { v2_vm_do_jump(vm); }
    } else if (cs_addr == 0x44F3) {
        if (vm.carry) { vm.pc += 2; } else { v2_vm_do_jump(vm); }
    } else {
        v2_vm_runtime_dispatch(vm, 0x87AE, 0);
    }
}

// 0xD3 (sub_12829): Password verify. 0 bytes. Searches password table, sets level.
static void v2_vm_op_D3(V2VM& vm) {
    // Search table at ds:[(uint16_t)(si - 0x7A5B)] for 4-byte match
    // with word_287F0..287F6 (at ds:0x0310..0x0316, offset = 0x287F0 - 0x284E0)
    uint16_t pw0 = vm.ds_read(DS_PW_CHAR0);
    uint16_t pw1 = vm.ds_read(DS_PW_CHAR1);
    uint16_t pw2 = vm.ds_read(DS_PW_CHAR2);
    uint16_t pw3 = vm.ds_read(DS_PW_CHAR3);

    for (uint16_t si = 0; (int16_t)si < 0x94; si += 4) {
        uint16_t addr_base = (uint16_t)(si - 0x7A5B);
        uint8_t c0 = *(vm.shadow + addr_base) & 0x7F;
        uint8_t c1 = *(vm.shadow + (uint16_t)(addr_base + 1)) & 0x7F;
        uint8_t c2 = *(vm.shadow + (uint16_t)(addr_base + 2)) & 0x7F;
        uint8_t c3 = *(vm.shadow + (uint16_t)(addr_base + 3)) & 0x7F;

        if (c0 == (pw0 & 0xFF) && c1 == (pw1 & 0xFF) &&
            c2 == (pw2 & 0xFF) && c3 == (pw3 & 0xFF)) {
            // Found: level = si / 4
            uint16_t level = si >> 2;
            // word_2AAA9 at ds:0x25C9
            vm.ds_write(DS_LEVEL_LOAD, level);
            // byte_287E8 at ds:0x0308
            vm.ds_write_b(DS_CMD_ACTIVE, 0);
            return;
        }
    }
    // Not found: byte_287E8 at ds:0x0308
    vm.ds_write_b(DS_CMD_ACTIVE, 1);
}

// 0x2E (sub_1522c): Set collision search params. 2 bytes consumed.
static void v2_vm_op_2E(V2VM& vm) {
    uint16_t word = vm.read_u16();
    vm.ds_write(DS_SHAKE_SRC_X, word & 0xFF);
    vm.ds_write(DS_SHAKE_X, 0);
    vm.ds_write(DS_SHAKE_GATE_X, (word >> 7) & 0x1FE);
}

// 0x50 (sub_126a9): Text position cmd. 2 mode bytes + 3 off_30C98 dispatches.
// Writes results to ds:0x34 (word_28514), ds:0x6C (word_2854C), ds:0x6E (word_2854E).
// Then writes command buffer entry (type=8, X, Y, param) + advances buffer.
static void v2_vm_op_50(V2VM& vm) {
    // Mode byte 1: dual dispatch
    uint16_t word1 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode1 = (uint8_t)(word1 & 0xFF);
    bool ch_intr = false;
    uint16_t val1 = v2_vm_dispatch_30C98(vm, mode1, 0x26AE, &ch_intr);
    if (ch_intr) { v2_vm_ch67_ub_guard(vm, "op50/1st@0x26AE: RETN onto PUSHed mode word"); return; }
    vm.ds_write(DS_SCRATCH_34, val1);  // word_28514
    uint16_t val2 = v2_vm_dispatch_30C98(vm, mode1 >> 3, 0x26B8, &ch_intr);
    if (ch_intr) return;   // clean (POP ax at 0x26B4 emptied the frame)
    vm.ds_write(DS_TEXT_COL, val2);  // word_2854C
    // Mode byte 2: single dispatch
    uint16_t word2 = *(uint16_t*)(vm.es + vm.pc); vm.pc += 1;
    uint8_t mode2 = (uint8_t)(word2 & 0xFF);
    uint16_t val3 = v2_vm_dispatch_30C98(vm, mode2, 0x26C2, &ch_intr);
    if (ch_intr) return;   // clean
    vm.ds_write(DS_TEXT_ROW, val3);  // word_2854E
    // Command buffer entry: type=8 + 3 values + advance by 8
    uint16_t bx_cmd = vm.ds_read(DS_CMD_WRITE);
    vm.ds_write(bx_cmd + DS_CMD_BUF, 8);
    vm.ds_write(bx_cmd + DS_CMD_ENTRY_SI, val1);
    vm.ds_write(bx_cmd + DS_CMD_ENTRY_DI, val2);
    vm.ds_write(bx_cmd + DS_CMD_ENTRY_PARAM, val3);
    vm.ds_write(DS_CMD_WRITE, bx_cmd + 8);
}

// 0x6D (sub_148c1): sub_1547e (literal, 2B). Unsigned acc < val → jump, acc >= val → skip 2.
static void v2_vm_op_6D(V2VM& vm) {
    uint16_t val = v2_vm_read_literal(vm);
    if (v2_vm_accumulator < val) { v2_vm_do_jump(vm); } else { vm.pc += 2; }
}

// ============================================================================
// Missing compare+branch opcodes — all verified against seg000 original.
// Each follows pattern: read value via dispatch, compare with acc, branch.
// ============================================================================

// 0x6B (sub_1489d): indexed+1995, unsigned acc >= val → jump. 1B + 2B jump.
// Verified: seg000 lines 10075-10084.
static void v2_vm_op_6B(V2VM& vm) {
    uint16_t val = v2_vm_read_indexed_field_1995(vm);
    if (v2_vm_accumulator >= val) { v2_vm_do_jump(vm); } else { vm.pc += 2; }
}

